/* =========================================================
   JYC UI POLISH v2 — mobile-first interaction layer
   Keeps the approved beige / black / red / gold palette.
   ========================================================= */
html{scroll-padding-top:92px}
body{overflow-x:hidden;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
button,a,input,textarea,select{-webkit-tap-highlight-color:transparent}
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--accent-gold);outline-offset:3px}
::selection{background:var(--accent-red);color:#fff}

/* reveal system */
.reveal{opacity:0;transform:translate3d(0,24px,0);transition:opacity .75s var(--ease),transform .75s var(--ease);transition-delay:var(--reveal-delay,0ms)}
.reveal.is-visible{opacity:1;transform:none}

/* richer but restrained page motion */
.app{animation:pageIn .55s var(--ease) both}
.nav{transition:background .45s var(--ease),border-color .45s var(--ease),box-shadow .45s var(--ease)}
.nav:hover{box-shadow:0 10px 35px color-mix(in srgb,var(--text-primary) 4%,transparent)}
.nav-inner{transition:height .35s var(--ease)}
.brand{transition:transform .3s var(--ease)}
.brand:hover{transform:translateY(-1px)}
.brand img{transition:transform .55s var(--ease)}
.brand:hover img{transform:rotate(-4deg) scale(1.04)}
.btn,.card,.contact-card,.featured,.gallery-item,.quick-grid button,.back,.discover button,.gallery-filter button,.seg button,.icon-btn,.search-trigger,.theme-toggle{will-change:transform}
.btn:active,.search-trigger:active,.theme-toggle:active,.back:active,.discover button:active,.gallery-filter button:active,.seg button:active{transform:scale(.97)}
.card:active,.featured:active,.gallery-item:active{transform:translateY(-2px) scale(.995)}

/* hero */
.hero-copy>*{animation:heroItem .8s var(--ease) both}
.hero-copy .eyebrow{animation-delay:.05s}
.hero-copy h1{animation-delay:.12s}
.hero-copy .hero-rule{animation-delay:.2s}
.hero-copy h4{animation-delay:.26s}
.hero-copy>p{animation-delay:.32s}
.hero-copy .hero-actions{animation-delay:.4s}
.hero-art{animation:heroArtIn 1.1s var(--ease) .12s both}
.orbit{transform-origin:center;will-change:transform}
.logo-core{will-change:transform}
.float-chip{transition:transform .45s var(--ease),border-color .35s,box-shadow .35s}
.float-chip:hover{transform:translateY(-5px) rotate(-1deg);border-color:var(--accent-gold)}

/* better media defaults */
img{max-width:100%}
.card,.contact-card,.featured,.club-hero,.fest-hero,.event-detail-poster,.quote-card,.editor-card,.login-card{box-shadow:0 18px 55px color-mix(in srgb,var(--text-primary) 5%,transparent)}
.card:hover,.contact-card:hover,.featured:hover,.gallery-item:hover{box-shadow:0 22px 65px color-mix(in srgb,var(--text-primary) 9%,transparent)}

/* mobile navigation drawer + bottom dock */
.mobile-dock{display:none}
.hamb{width:44px;height:44px;align-items:center;justify-content:center;border-radius:14px;transition:background .3s var(--ease),transform .3s var(--ease)}
.hamb:hover{background:var(--bg-card)}
.hamb i{transition:transform .35s var(--ease),opacity .25s}
.hamb.open i:nth-child(1){transform:translateY(7px) rotate(45deg)}
.hamb.open i:nth-child(2){opacity:0}
.hamb.open i:nth-child(3){transform:translateY(-7px) rotate(-45deg)}

.search-trigger{min-height:44px}
.theme-toggle{backdrop-filter:blur(12px)}
.overlay{overscroll-behavior:contain}
.search-modal{max-height:calc(100dvh - 130px);overflow:auto}
.search-list button{transition:background .25s var(--ease),transform .25s var(--ease)}
.search-list button:hover{transform:translateX(3px)}

/* touch-friendly controls */
@media(max-width:1050px){
  .nav-inner{gap:10px}
  .nav nav.open{top:78px;border-radius:0 0 22px 22px;box-shadow:0 18px 45px color-mix(in srgb,var(--text-primary) 10%,transparent);animation:drawerIn .35s var(--ease) both}
  .nav nav.open button{min-height:48px;text-align:left}
  .hamb{display:flex}
}
