/* =========================================================
   JYC UI / INTERACTION FINAL PASS
   Premium modern college-organisation direction.
   Uses only the approved beige / black / red / gold palette.
   ========================================================= */
:root{
  --surface-1:#fffdf7;
  --surface-2:#f1eadb;
  --surface-3:#e8dfcf;
  --shadow-soft:0 20px 60px rgba(26,25,29,.10);
  --shadow-hover:0 28px 85px rgba(26,25,29,.16);
}
:root[data-theme=dark]{
  --surface-1:#18161d;
  --surface-2:#211e25;
  --surface-3:#29252d;
  --shadow-soft:0 24px 75px rgba(0,0,0,.34);
  --shadow-hover:0 30px 100px rgba(0,0,0,.48);
}

html{background:var(--bg-main)}
body{min-width:320px;background:
  radial-gradient(circle at 85% 8%,color-mix(in srgb,var(--accent-gold) 7%,transparent),transparent 27rem),
  var(--bg-main);}
:root[data-theme=light] body{background:
  radial-gradient(circle at 90% 0%,rgba(191,156,111,.12),transparent 25rem),
  radial-gradient(circle at 8% 35%,rgba(168,36,32,.035),transparent 23rem),
  var(--bg-main);}

/* Brand mark is intentionally circular everywhere. */
.brand img,.admin-brand img,.footer-brand img,.loading-logo img{object-fit:contain;border-radius:50%;}
.brand img{width:62px;height:62px}

/* Cleaner desktop navigation */
.nav{background:color-mix(in srgb,var(--bg-main) 82%,transparent);box-shadow:0 1px 0 color-mix(in srgb,var(--text-primary) 3%,transparent);}
.nav-inner{height:88px;width:min(1440px,calc(100% - 48px));padding-right:72px}
.brand{gap:12px}
.brand span{font-size:17px;letter-spacing:-.02em}
.nav nav{gap:2px}
.nav nav button{border-radius:999px;padding:11px 13px}
.nav nav button:hover{background:color-mix(in srgb,var(--bg-card) 75%,transparent)}
.nav nav button.active{background:color-mix(in srgb,var(--accent-red) 7%,var(--bg-card));}
.nav nav button.active:after{bottom:5px;height:2px;border-radius:99px}
.admin-nav{margin-left:4px}
.search-trigger{background:color-mix(in srgb,var(--bg-card) 72%,transparent);padding:11px 15px}
.theme-toggle{background:color-mix(in srgb,var(--bg-card) 86%,transparent);border-color:var(--border-tech);box-shadow:var(--shadow-soft)}
.theme-toggle:hover{transform:translateY(-2px) rotate(4deg);border-color:var(--accent-gold)}

/* Hero: less oversized, more breathing room, no viewport clipping. */
.hero{min-height:calc(100svh - 88px);width:min(1440px,calc(100% - 48px));grid-template-columns:minmax(0,1.02fr) minmax(430px,.98fr);gap:48px}
.hero-copy{padding:72px 0 84px;max-width:760px}
