.hero-copy>p{max-width:640px;font-size:18px;line-height:1.7}
.hero-actions{margin-top:30px}
.hero-art{min-height:600px;overflow:visible}
.logo-core{width:min(330px,27vw);background:color-mix(in srgb,var(--bg-card) 94%,transparent);box-shadow:0 0 0 20px color-mix(in srgb,var(--accent-gold) 4%,transparent),0 0 0 58px color-mix(in srgb,var(--accent-gold) 2.5%,transparent),0 25px 80px color-mix(in srgb,var(--text-primary) 8%,transparent)}
.logo-core img{width:76%;height:76%}
.orbit{opacity:.75}
.float-chip{background:color-mix(in srgb,var(--bg-card) 90%,transparent);backdrop-filter:blur(12px)}

/* Premium surfaces */
.section{width:min(1320px,calc(100% - 48px));padding:96px 0}
.page{padding-top:64px}
.section-head{margin-bottom:38px}
.section-head h2{font-size:clamp(40px,5.5vw,72px)}
.card,.featured,.contact-card,.club-hero,.fest-hero,.event-detail-poster,.quote-card,.editor-card,.login-card{background:color-mix(in srgb,var(--bg-card) 94%,var(--bg-main));box-shadow:var(--shadow-soft);}
.card:hover,.contact-card:hover,.featured:hover,.gallery-item:hover{box-shadow:var(--shadow-hover);border-color:color-mix(in srgb,var(--accent-gold) 75%,var(--border-tech));}
.card{transform:translateZ(0)}
.card:hover{transform:translateY(-8px)}
.card:before,.featured:before,.contact-card:before{content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;background:linear-gradient(120deg,color-mix(in srgb,var(--accent-gold) 5%,transparent),transparent 35%);opacity:0;transition:opacity .45s var(--ease)}
.card:hover:before,.featured:hover:before,.contact-card:hover:before{opacity:1}
.card,.featured,.contact-card{position:relative}

/* Buttons feel physical instead of flashy. */
.btn{min-height:48px;border-radius:13px;box-shadow:0 8px 25px color-mix(in srgb,var(--accent-red) 13%,transparent)}
.btn.secondary{box-shadow:none;background:color-mix(in srgb,var(--bg-card) 80%,transparent)}
.btn:hover{box-shadow:0 15px 34px color-mix(in srgb,var(--accent-red) 19%,transparent)}
.btn:after{content:"";position:absolute;inset:1px;border:1px solid color-mix(in srgb,#fff 10%,transparent);border-radius:inherit;pointer-events:none}

/* Announcements */
.announcement{background:color-mix(in srgb,var(--bg-card) 94%,transparent);box-shadow:var(--shadow-soft);}

/* Search */
.overlay{background:color-mix(in srgb,var(--bg-main) 62%,rgba(0,0,0,.5));backdrop-filter:blur(10px)}
.search-modal{background:color-mix(in srgb,var(--bg-card) 96%,var(--bg-main));border-color:var(--border-tech);box-shadow:0 35px 120px rgba(0,0,0,.25)}
.search-list button:hover{background:color-mix(in srgb,var(--accent-gold) 8%,var(--bg-main));}

/* Gallery imagery */
.gallery-item{border-radius:22px;overflow:hidden;background:var(--bg-card)}
.gallery-item img{transition:transform .8s var(--ease);}
.gallery-item:hover img{transform:scale(1.035)}

/* Loading screen */
.loading{background:var(--bg-main)}
.loading-logo img{width:112px;height:112px;animation:loadingFloat 2.4s ease-in-out infinite}
.loadline{width:150px;height:2px;background:var(--border-tech);overflow:hidden}
.loadline i{display:block;height:100%;width:45%;background:var(--accent-red);animation:loadSweep 1.5s var(--ease) infinite}

/* Creator credit is visibly locked. */
.creator-locked{position:relative;overflow:hidden}
.creator-lock{display:flex;align-items:center;justify-content:space-between;gap:12px}
.lock-badge{font:700 9px 'Segoe UI',system-ui,sans-serif;letter-spacing:.16em;color:var(--accent-red);border:1px solid var(--border-tech);padding:7px 9px;border-radius:999px}
.creator-profile{display:flex;align-items:center;gap:14px;margin:18px 0}
.creator-avatar{width:58px;height:58px;border-radius:18px;background:var(--accent-red);color:#fff;display:grid;place-items:center;font:700 18px 'Segoe UI',system-ui,sans-serif;box-shadow:0 10px 28px color-mix(in srgb,var(--accent-red) 22%,transparent)}
.creator-profile div:last-child{display:grid;gap:3px}
.creator-profile strong{font:700 20px 'Segoe UI',system-ui,sans-serif}
.creator-profile span,.creator-profile small{color:var(--text-muted)}

/* Smooth route / section motion */
.app{animation:routeIn .5s var(--ease) both}
.reveal{transform:translate3d(0,30px,0) scale(.992);transition:opacity .8s var(--ease),transform .9s var(--ease);}
.reveal.is-visible{transform:none}

/* Better admin hierarchy */
.admin-app{background:transparent}
.admin-shell{background:transparent}
.admin-side{background:color-mix(in srgb,var(--bg-card) 82%,transparent);backdrop-filter:blur(18px)}
.admin-main{background:transparent}
.admin-top{border-bottom-color:var(--border-tech)}
.editor-card{border-radius:22px}
.admin-row{transition:transform .35s var(--ease),border-color .3s,background .3s,box-shadow .35s}
.admin-row:hover{transform:translateY(-2px);border-color:var(--accent-gold);box-shadow:var(--shadow-soft)}

/* Prevent accidental horizontal overflow. */
main,.app,.admin-app{overflow-x:clip}

@keyframes routeIn{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}
@keyframes loadingFloat{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-7px) scale(1.025)}}
@keyframes loadSweep{0%{transform:translateX(-130%)}100%{transform:translateX(320%)}}

