.hero{
  isolation:isolate;
  min-height:calc(100svh - 88px);
}
.hero-copy{position:relative;z-index:2}
.hero h1{
  max-width:690px;
  text-wrap:balance;
}
.hero h1 em:first-child{letter-spacing:-.085em}
.hero-copy>p{max-width:600px}
.hero-art{z-index:1}
.hero-art:before{
  content:"";
  position:absolute;
  width:min(520px,75vw);
  aspect-ratio:1;
  border-radius:50%;
  background:radial-gradient(circle,color-mix(in srgb,var(--accent-gold) 9%,transparent),transparent 66%);
  filter:blur(2px);
  opacity:.9;
  pointer-events:none;
}
.logo-core{
  width:min(350px,29vw);
  border:0;
  background:transparent;
  box-shadow:0 0 0 1px color-mix(in srgb,var(--accent-gold) 22%,transparent),
             0 0 0 14px color-mix(in srgb,var(--accent-gold) 4%,transparent),
             0 28px 80px color-mix(in srgb,var(--accent-gold) 10%,transparent);
  animation:float 7s ease-in-out infinite;
}
.logo-core img{width:100%;height:100%;filter:drop-shadow(0 18px 30px color-mix(in srgb,var(--accent-gold) 16%,transparent))}
.logo-core span{bottom:-28px}
.orbit{
  border-color:color-mix(in srgb,var(--accent-gold) 18%,transparent);
  opacity:.42;
}
.o1{width:520px;height:520px}
.o2{width:650px;height:400px;animation-duration:32s;opacity:.28}
.o3{width:450px;height:620px;animation-duration:40s;opacity:.20}
:root[data-theme="dark"] .orbit{opacity:.58;border-color:color-mix(in srgb,var(--accent-gold) 24%,transparent)}
:root[data-theme="dark"] .o2{opacity:.38}
:root[data-theme="dark"] .o3{opacity:.28}
.float-chip{
  backdrop-filter:blur(16px);
  box-shadow:var(--shadow-soft);
  transition:transform .4s var(--ease),border-color .4s,background .4s;
}
.float-chip:hover{transform:translateY(-4px);border-color:var(--accent-gold)}

/* Content cards: cleaner, less heavy. */
.card,.featured,.contact-card{
  box-shadow:var(--shadow-soft);
}
.card:hover,.featured:hover,.contact-card:hover{
  box-shadow:var(--shadow-hover);
}
.club-card{
  min-height:190px;
  grid-template-columns:76px minmax(0,1fr);
}
.club-logo{
  width:76px;height:76px;border-radius:20px;
  background:color-mix(in srgb,var(--bg-main) 70%,var(--bg-card));
}
.club-card h3,.event-card h3{letter-spacing:-.035em}
.chips span{transition:background .25s,border-color .25s,color .25s}
.card:hover .chips span{border-color:color-mix(in srgb,var(--accent-gold) 60%,var(--border-tech))}

/* Better controls */
.filters input,.filters select,.event-toolbar input,.event-toolbar select,
.form-grid input,.form-grid textarea,.form-grid select,.editor-card input,
.editor-card textarea,.editor-card select,.search-modal>input,
.builder-row input,.builder-row textarea,.schedule-editor input,.schedule-editor select{
  min-height:48px;
  transition:border-color .25s,box-shadow .25s,background .35s;
}
.btn,.search-trigger,.theme-toggle,.icon-btn,.discover button,.gallery-filter button,.seg button{
  transition:transform .3s var(--ease),border-color .3s,background .3s,box-shadow .3s,color .3s;
}
.btn:active,.search-trigger:active,.theme-toggle:active,.icon-btn:active{transform:translateY(1px) scale(.985)}

/* Page motion */
.app{animation:routeIn .55s cubic-bezier(.16,1,.3,1) both}
.reveal{
  opacity:0;
  transform:translate3d(0,28px,0) scale(.985);
  transition:opacity .8s cubic-bezier(.16,1,.3,1),transform .9s cubic-bezier(.16,1,.3,1);
  transition-delay:var(--reveal-delay,0ms);
}
.reveal.is-visible{opacity:1;transform:none}

/* Startup screen — intentional brand moment, not a generic spinner. */
.loading{
  position:fixed;inset:0;z-index:9999;
  display:grid;place-items:center;
  background:
    radial-gradient(circle at 50% 42%,color-mix(in srgb,var(--accent-gold) 7%,transparent),transparent 32%),
    var(--bg-main);
}
.loading:before{
  content:"";
  position:absolute;
  width:min(72vw,430px);aspect-ratio:1;border:1px solid color-mix(in srgb,var(--accent-gold) 18%,transparent);
  border-radius:50%;animation:bootRing 2.8s ease-in-out infinite;
}
.loading-logo{
  position:relative;display:grid;place-items:center;gap:20px;
  animation:bootLogo 1.2s cubic-bezier(.16,1,.3,1) both;
}
.loading-logo img{width:120px;height:120px}
.loading-logo span{
  color:var(--accent-red);font:700 10px 'Segoe UI',system-ui,sans-serif;
  letter-spacing:.32em;animation:bootText 1s .35s ease both;
}
.loadline{margin-top:28px}
@keyframes bootLogo{from{opacity:0;transform:translateY(18px) scale(.88)}to{opacity:1;transform:none}}
@keyframes bootText{from{opacity:0;letter-spacing:.6em}to{opacity:1;letter-spacing:.32em}}
@keyframes bootRing{0%,100%{transform:scale(.82);opacity:.2}50%{transform:scale(1);opacity:.65}}

/* Mobile: prioritize content over decorative chrome. */
@media(max-width:760px){
  .nav-inner{height:68px;width:calc(100% - 16px);padding-right:48px}
  .brand img{width:44px;height:44px}
  .brand span{font-size:12px;letter-spacing:-.015em}
  .theme-toggle{top:9px;right:8px;width:40px;height:40px}
  .search-trigger{width:40px;height:40px;padding:0;display:grid;place-items:center}
  .search-trigger span{display:none}
  .nav nav.open{
    top:68px;left:8px;right:8px;
    border:1px solid var(--border-tech);
    animation:mobileMenuIn .3s cubic-bezier(.16,1,.3,1) both;
  }
  .hero{
    width:calc(100% - 24px);
    min-height:auto;
    padding-bottom:24px;
  }
  .hero-copy{padding:40px 0 0}
  .hero h1{
    font-size:clamp(54px,17.5vw,78px);
    line-height:.9;
    margin:18px 0 24px;
    max-width:100%;
  }
  .hero-copy>p{font-size:15px;max-width:100%}
  .hero-actions{grid-template-columns:1fr 1fr}
  .hero-art{
    min-height:310px;
    margin-top:4px;
  }
  .hero-art:before{width:320px}
  .logo-core{
    width:175px;
    box-shadow:0 0 0 1px color-mix(in srgb,var(--accent-gold) 20%,transparent),
               0 0 0 10px color-mix(in srgb,var(--accent-gold) 4%,transparent),
               0 20px 50px color-mix(in srgb,var(--accent-gold) 10%,transparent);
  }
  .logo-core span{bottom:-23px;font-size:8px}
  .o1{width:255px;height:255px}
  .o2{width:315px;height:190px}
  .o3{width:225px;height:310px}
  .orbit{opacity:.25}
  :root[data-theme="dark"] .orbit{opacity:.34}
  .chip1{top:7%;left:1%}
  .chip2{right:1%;bottom:7%}
  .float-chip{padding:7px 9px}
  .section{width:calc(100% - 24px);padding:60px 0}
  .page{padding-top:26px;padding-bottom:94px}
  .section-head h2{font-size:clamp(38px,12vw,55px)}
  .club-card{grid-template-columns:58px minmax(0,1fr);gap:13px;padding:17px;min-height:0}
  .club-logo{width:58px;height:58px;border-radius:16px}
  .club-card h3{font-size:20px;margin:7px 0}
  .club-card p{font-size:13px;line-height:1.55}
  .card{border-radius:19px}
  .event-poster{height:205px}
  .featured-image{min-height:205px}
  .announcement{width:calc(100% - 24px)}
  .filters,.event-toolbar{grid-template-columns:1fr;gap:8px}
  .filters input,.filters select,.event-toolbar input,.event-toolbar select{min-height:50px}
  .mobile-dock{
    position:fixed;left:8px;right:8px;bottom:max(8px,env(safe-area-inset-bottom));
    z-index:95;display:grid!important;grid-template-columns:repeat(4,1fr);
    padding:7px;border:1px solid var(--border-tech);border-radius:18px;
    backdrop-filter:blur(20px);
  }
  .mobile-dock button{
    min-height:52px;border:0;background:transparent;color:var(--text-muted);
    border-radius:13px;font-size:10px;font-weight:700;
    display:grid;place-items:center;gap:2px;
    transition:background .25s,color .25s,transform .25s;
  }
  .mobile-dock button span{font-size:16px;line-height:1}
  .mobile-dock button.active{color:var(--text-primary);background:color-mix(in srgb,var(--accent-red) 9%,var(--bg-card))}
  .mobile-dock button:active{transform:scale(.94)}
  .loading-logo img{width:98px;height:98px}
}
@keyframes mobileMenuIn{from{opacity:0;transform:translateY(-8px) scale(.98)}to{opacity:1;transform:none}}
@media(min-width:761px){.mobile-dock{display:none!important}}
@media(prefers-reduced-motion:reduce){
  .loading:before,.loading-logo,.loading-logo span{animation:none!important}
}

/* =========================================================
   JYC HOME REFINEMENT — compact hero, richer first viewport
   ========================================================= */
.hero{
  min-height:clamp(610px,76svh,780px);
  align-items:center;
  padding:24px 0 34px;
}
