.hero-art{min-height:500px}
.logo-core{width:min(300px,25vw);box-shadow:0 0 0 16px color-mix(in srgb,var(--accent-gold) 3%,transparent),0 0 0 42px color-mix(in srgb,var(--accent-gold) 1.5%,transparent),0 25px 70px color-mix(in srgb,var(--text-primary) 7%,transparent)}
.orbit{opacity:.34}
:root[data-theme="light"] .orbit{display:none}
:root[data-theme="light"] .hero-art:before{content:"";position:absolute;width:390px;height:390px;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--accent-gold) 10%,transparent),transparent 68%);filter:blur(8px);pointer-events:none}
