  :root[data-theme="light"] .hero-art:before{width:270px;height:270px}
}

/* =========================================================
   JYC FINAL VISUAL SYSTEM — SKY / ORBIT / EDITORIAL
   Uses only the approved JYC palette.
   ========================================================= */
:root{
  --surface-soft:rgba(255,255,255,.72);
  --ring-opacity:.34;
  --hero-wash:radial-gradient(circle at 76% 45%,rgba(191,156,111,.14),transparent 34%),radial-gradient(circle at 20% 0%,rgba(191,156,111,.08),transparent 28%);
}
:root[data-theme=dark]{
  --surface-soft:rgba(24,22,29,.72);
  --ring-opacity:.20;
  --hero-wash:radial-gradient(circle at 74% 42%,rgba(210,180,140,.10),transparent 32%),radial-gradient(circle at 15% 10%,rgba(201,42,42,.06),transparent 28%);
}
body{background-image:var(--hero-wash);background-attachment:fixed}
.nav{box-shadow:0 8px 35px rgba(26,25,29,.035)}
:root[data-theme=dark] .nav{box-shadow:0 8px 40px rgba(0,0,0,.18)}
.hero{min-height:clamp(650px,calc(100vh - 96px),860px);padding:36px 0 72px;overflow:visible}
.hero-copy{padding:48px 0}
.hero h1{font-size:clamp(64px,8.5vw,132px);line-height:.84;max-width:690px;margin:30px 0 28px}
.hero-copy>p{max-width:650px;font-size:clamp(17px,1.6vw,20px)}
.hero-art{min-height:560px}
.logo-core{width:min(350px,34vw);box-shadow:0 0 0 22px color-mix(in srgb,var(--accent-gold) 5%,transparent),0 0 0 60px color-mix(in srgb,var(--accent-gold) 3%,transparent),0 28px 80px rgba(26,25,29,.10)}
.orbit{border-color:color-mix(in srgb,var(--accent-gold) 34%,transparent)}
:root[data-theme=dark] .hero-art:before{
  content:"";position:absolute;inset:4% 3% 8%;border-radius:50%;
  background:radial-gradient(circle at 50% 50%,transparent 0 35%,rgba(210,180,140,.018) 52%,transparent 70%);
  box-shadow:inset 0 0 100px rgba(0,0,0,.14);
}
.sky-stars{position:absolute;inset:5% 6%;pointer-events:none;opacity:0;transition:opacity .6s var(--ease)}
:root[data-theme=dark] .sky-stars{opacity:.75}
.sky-stars:before,.sky-stars:after{content:"";position:absolute;width:3px;height:3px;border-radius:50%;background:var(--accent-gold);box-shadow:
  58px 34px 0 0 var(--accent-gold), 142px 88px 0 -1px var(--accent-gold),
  224px 30px 0 -1px var(--accent-gold), 318px 104px 0 0 var(--accent-gold),
  408px 48px 0 -1px var(--accent-gold), 480px 142px 0 0 var(--accent-gold),
  90px 210px 0 -1px var(--accent-gold), 176px 310px 0 0 var(--accent-gold),
  282px 250px 0 -1px var(--accent-gold), 382px 334px 0 0 var(--accent-gold),
  510px 290px 0 -1px var(--accent-gold), 36px 392px 0 -1px var(--accent-gold),
  140px 446px 0 0 var(--accent-gold), 350px 430px 0 -1px var(--accent-gold);
  animation:twinkle 4.5s ease-in-out infinite alternate;
}
.sky-stars:after{transform:translate(16px,12px) scale(.65);opacity:.65;animation-delay:1.8s}
@keyframes twinkle{from{opacity:.35;transform:scale(.8)}to{opacity:1;transform:scale(1.12)}}
:root[data-theme=dark] .orbit{border-color:color-mix(in srgb,var(--accent-gold) 23%,transparent)}
:root[data-theme=light] .orbit{border-color:color-mix(in srgb,var(--accent-gold) 34%,transparent)}
.hero-quick{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-width:720px;margin-top:46px;border-top:1px solid var(--border-tech)}
.hero-quick button{border:0;border-right:1px solid var(--border-tech);background:transparent;text-align:left;padding:17px 18px 8px 0;color:var(--text-primary);transition:transform .35s var(--ease),opacity .35s}
.hero-quick button:last-child{border-right:0;padding-left:18px}
.hero-quick button:hover{transform:translateY(-3px)}
.hero-quick button span{display:block;color:var(--accent-red);font:700 10px 'Segoe UI',system-ui,sans-serif;letter-spacing:.18em;margin-bottom:9px}
.hero-quick button strong{display:block;font:700 15px 'Segoe UI',system-ui,sans-serif}
.hero-quick button em{display:block;font-style:normal;color:var(--text-muted);font-size:12px;margin-top:5px}
.section{padding:86px 0}
.section-head{margin-bottom:34px}
.section-head h2{font-size:clamp(38px,5.2vw,68px)}
.card,.featured,.principles>div,.number-list>div,.editor-card,.admin-row{transition:transform .35s var(--ease),box-shadow .35s var(--ease),border-color .35s}
.card:hover,.featured:hover{transform:translateY(-5px)}
.dark-band{position:relative;overflow:hidden}
.dark-band:before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 80% 20%,color-mix(in srgb,var(--accent-gold) 6%,transparent),transparent 28%)}
