}
.app,.nav,footer{position:relative;z-index:1}


/* =========================================================
   JYC FINAL PERFORMANCE + LIGHT THEME POLISH
   ========================================================= */
:root[data-theme="light"] .orbit{display:block!important;opacity:.42!important;border-color:color-mix(in srgb,var(--accent-gold) 42%,transparent)!important}
:root[data-theme="light"] .hero-art:before{background:radial-gradient(circle,color-mix(in srgb,var(--accent-gold) 13%,transparent),transparent 68%);filter:blur(3px)}
:root[data-theme="light"] .logo-core{background:color-mix(in srgb,var(--bg-card) 84%,transparent);box-shadow:0 0 0 1px color-mix(in srgb,var(--accent-gold) 34%,transparent),0 0 0 12px color-mix(in srgb,var(--accent-gold) 6%,transparent),0 24px 70px rgba(26,25,29,.10)}
:root[data-theme="light"] .nav{background:color-mix(in srgb,var(--bg-card) 88%,transparent);backdrop-filter:blur(18px)}
:root[data-theme="light"] .card,:root[data-theme="light"] .featured,:root[data-theme="light"] .editor-card,:root[data-theme="light"] .contact-card{box-shadow:0 18px 50px rgba(26,25,29,.075)}
:root[data-theme="light"] .card:hover,:root[data-theme="light"] .featured:hover,:root[data-theme="light"] .contact-card:hover{box-shadow:0 28px 70px rgba(26,25,29,.12)}
:root[data-theme="dark"] .hero-art:after{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 48%,transparent 0 22%,rgba(210,180,140,.025) 48%,transparent 70%);mix-blend-mode:screen}
.setup-box{margin:14px 0;padding:16px 18px;border:1px solid color-mix(in srgb,var(--accent-gold) 45%,transparent);border-radius:16px;background:color-mix(in srgb,var(--accent-gold) 8%,var(--bg-card));display:grid;gap:6px}
.setup-box strong{color:var(--text-primary)}
.setup-box p{margin:0;color:var(--text-muted);line-height:1.55}
.setup-box code{display:block;overflow:auto;padding:9px 11px;border-radius:10px;background:var(--bg-main);color:var(--accent-red);font:600 12px ui-monospace,SFMono-Regular,Consolas,monospace}
/* Prevent the decorative field from ever reducing content contrast. */
.hero-art,.hero-copy,.section,.admin-main{isolation:isolate}
