  :root[data-theme="light"] .orbit{opacity:.25!important}
  .hero-art{overflow:hidden;border-radius:28px}
  .hero-art:after{opacity:.5}
  .setup-box{font-size:13px}
}

/* =========================================================
   JYC MICRO-INTERACTIONS — save controls + scroll progress
   ========================================================= */
.scroll-progress{position:fixed;top:0;left:0;right:0;height:2px;z-index:2000;pointer-events:none;background:transparent}
.scroll-progress i{display:block;height:100%;background:var(--accent-red);box-shadow:0 0 10px color-mix(in srgb,var(--accent-red) 30%,transparent);transition:width .12s linear}
.card-topline{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}
.save-btn{border:1px solid var(--border-tech);background:color-mix(in srgb,var(--bg-card) 82%,transparent);color:var(--text-muted);border-radius:999px;padding:6px 9px;font:700 9px 'Segoe UI',system-ui,sans-serif;letter-spacing:.09em;text-transform:uppercase;cursor:pointer;white-space:nowrap;transition:transform .25s var(--ease),background .25s,border-color .25s,color .25s}
.save-btn:hover{transform:translateY(-1px);border-color:var(--accent-gold);color:var(--text-primary)}
.save-btn.saved{background:color-mix(in srgb,var(--accent-gold) 12%,var(--bg-card));border-color:color-mix(in srgb,var(--accent-gold) 55%,var(--border-tech));color:var(--accent-red)}
.poster-save{position:absolute;right:12px;bottom:12px;z-index:3;background:rgba(15,14,17,.76);backdrop-filter:blur(10px);color:#fff8e1;border-color:rgba(210,180,140,.38)}
.event-poster{position:relative}
