ncement-panel h2{font:600 clamp(32px,5vw,65px) 'Segoe UI',system-ui,sans-serif;letter-spacing:-.05em;max-width:900px}.fest-app-active{background:var(--bg-main)}.fest-app-active .nav{background:color-mix(in srgb,var(--bg-card) 92%,transparent);border-bottom-color:var(--accent-gold)}.fest-app-active .nav nav button.active:after{background:var(--accent-gold)}.fest-app-active .app{position:relative}.fest-app-active .app:before{content:"";position:fixed;inset:96px 0 auto;height:1px;background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);opacity:.45;pointer-events:none;z-index:20}.fest-app-active .section{scroll-margin-top:140px}.fest-app-active .card:hover{box-shadow:0 30px 80px color-mix(in srgb,var(--accent-gold) 8%,transparent)}@keyframes pulse{0%,100%{transform:scale(1);opacity:.8}50%{transform:scale(1.45);opacity:1}}
