/* =========================================================
   V6.2 POLISH — SEARCH / LIGHT MODE / ACCESSIBILITY
   ========================================================= */
.search-trigger{display:inline-flex;align-items:center;gap:8px;padding:10px 13px;margin-right:0;min-height:42px}
.search-trigger kbd{font:600 9px 'Segoe UI',system-ui,sans-serif;letter-spacing:.08em;color:var(--text-muted);border:1px solid var(--border-tech);border-radius:6px;padding:3px 5px;background:color-mix(in srgb,var(--bg-main) 35%,transparent)}
.search-overlay{z-index:5000;padding:clamp(78px,10vh,110px) 20px 30px}
.search-modal{width:min(900px,100%);padding:26px;max-height:min(760px,calc(100dvh - 108px));border-radius:30px;position:relative}
.search-subtitle{display:block;margin-top:6px;color:var(--text-muted);font-size:13px}
.search-close{display:inline-flex;align-items:center;gap:7px;padding:9px 12px;border-radius:12px;font-weight:700}
.search-close b{font-size:18px;line-height:1;font-weight:500;color:var(--text-muted)}
.search-input-wrap{position:relative;display:flex;align-items:center;margin-top:20px}
.search-input-wrap>span{position:absolute;left:17px;color:var(--accent-red);font-size:21px;z-index:1}
.search-input-wrap input{padding-left:48px!important;padding-right:75px!important;font-size:17px;min-height:58px}
.search-input-wrap>kbd{position:absolute;right:42px;font:600 9px 'Segoe UI',system-ui,sans-serif;color:var(--text-muted);border:1px solid var(--border-tech);border-radius:6px;padding:4px 6px}
.search-clear{position:absolute;right:10px;border:0;background:transparent;color:var(--text-muted);font-size:23px;width:34px;height:34px;border-radius:50%}
.search-clear:hover{background:var(--bg-main);color:var(--text-primary)}
.search-meta{display:flex;justify-content:space-between;gap:15px;align-items:center;padding:13px 2px 8px;color:var(--text-muted);font-size:11px}
.search-shortcuts{display:flex;align-items:center;gap:5px}
.search-meta kbd,.search-empty kbd{font:600 9px 'Segoe UI',system-ui,sans-serif;border:1px solid var(--border-tech);border-bottom-width:2px;border-radius:6px;padding:4px 6px;color:var(--text-primary);background:color-mix(in srgb,var(--bg-main) 40%,transparent)}
.search-list{margin-top:4px;max-height:calc(100dvh - 310px);padding-right:3px}
.search-list button{grid-template-columns:76px 1fr 1fr 25px;background:color-mix(in srgb,var(--bg-main) 22%,transparent);border-color:transparent}
.search-list button:hover{background:color-mix(in srgb,var(--accent-gold) 9%,var(--bg-card));border-color:var(--border-tech);transform:translateX(3px)}
.search-list button>b{color:var(--accent-red);font-size:16px}
.search-empty{text-align:center;padding:55px 20px 45px;border:1px dashed var(--border-tech);border-radius:20px;background:color-mix(in srgb,var(--bg-main) 25%,transparent)}
.search-empty-icon{display:grid;place-items:center;width:58px;height:58px;margin:0 auto 17px;border:1px solid var(--border-tech);border-radius:50%;color:var(--accent-red);font-size:25px}
.search-empty strong{font:700 22px 'Segoe UI',system-ui,sans-serif}
.search-empty p{max-width:470px;margin:8px auto 18px;color:var(--text-muted);line-height:1.6}
.search-empty>div{display:flex;justify-content:center;gap:7px}

:root[data-theme="light"] body{background:var(--bg-main);}
:root[data-theme="light"] .nav{background:rgba(255,255,255,.84);border-bottom-color:rgba(191,156,111,.42);box-shadow:0 8px 30px rgba(26,25,29,.045)}
:root[data-theme="light"] .card,
