/* =========================================================
   JYC V9 FINAL POLISH — layout reliability + editorial hierarchy
   ========================================================= */
html,body,#root{min-height:100%;overflow-x:hidden}

/* Admin sidebar: independently scrollable, never clipped by the page */
.admin-shell{grid-template-columns:276px minmax(0,1fr);align-items:stretch}
.admin-side{position:sticky;top:0;height:100dvh;min-height:0;overflow:hidden;padding:22px 16px 16px}
.admin-side-scroll{display:block!important;flex:1 1 auto;min-height:0;overflow-y:auto;overflow-x:hidden;padding:4px 4px 14px 0;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--accent-red) transparent}
.admin-nav-group{margin:14px 0}
.admin-nav-group>span{padding-left:9px;opacity:.8}
.admin-nav-group button{min-height:38px;width:100%;min-width:0}
.admin-nav-group button em{display:block;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.admin-side .logout{flex:0 0 auto}
.admin-main{min-width:0;overflow-x:clip}
.admin-top{position:relative;z-index:2}
.admin-top h1{font-size:clamp(42px,4.5vw,62px)}
.setup-box{border:1px solid var(--border-tech)!important;background:var(--bg-main)!important;border-radius:18px!important;padding:18px!important}
.setup-box code{display:block;overflow:auto;white-space:nowrap;margin-top:8px}

/* Homepage: stronger first viewport, less empty canvas */
.home .hero{min-height:590px;height:auto;padding:42px 0 34px}
.home .hero-copy{padding:20px 0}
.home .hero h1{font-size:clamp(68px,8vw,126px);line-height:.86;max-width:820px}
.home .hero-art{min-height:480px}
.home .hero-quick{margin-top:28px}
.home .hero-quick button{min-height:84px}
.home .home-layout .section{padding-top:62px;padding-bottom:62px}
.home .section-head h2{max-width:760px}
.pulse-strip{margin:0 auto;max-width:1400px;width:calc(100% - 64px);padding:14px 0;border-top:1px solid var(--border-tech);border-bottom:1px solid var(--border-tech);display:flex;align-items:center;gap:24px}
.pulse-items{display:flex;gap:8px;flex-wrap:wrap}
.pulse-items span{border:1px solid var(--border-tech);border-radius:999px;padding:8px 11px;background:var(--bg-card);font-size:11px;color:var(--text-muted)}
.impact-strip{width:min(1400px,calc(100% - 64px));margin:0 auto;padding:38px 0;display:grid;grid-template-columns:1.5fr repeat(3,.7fr);gap:0;border-bottom:1px solid var(--border-tech)}
.impact-heading{padding-right:30px}
.impact-heading h2,.impact-empty h2{font:700 clamp(30px,3.4vw,50px)/1 'Segoe UI',system-ui,sans-serif;letter-spacing:-.045em;margin:8px 0 10px}
.impact-heading p,.impact-empty p{color:var(--text-muted);line-height:1.55;max-width:620px}
.impact-stat{padding:10px 22px;border-left:1px solid var(--border-tech);display:flex;flex-direction:column;justify-content:center;gap:5px}
.impact-stat strong{font:700 clamp(34px,4vw,56px)/.9 'Segoe UI',system-ui,sans-serif}
.impact-stat span{font-size:10px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.13em}
.impact-empty{display:flex;align-items:center;justify-content:space-between;gap:30px}
.impact-empty-mark{font:700 11px 'Segoe UI',system-ui,sans-serif;letter-spacing:.22em;color:var(--accent-red);white-space:nowrap}

/* Events: editorial heading, not billboard typography */
.events-hero{grid-template-columns:minmax(0,1fr) auto;gap:34px;margin-bottom:24px}
.events-hero h1{font-size:clamp(42px,5.2vw,76px);line-height:.94;max-width:780px;margin:10px 0 14px}
.events-hero p{font-size:16px;line-height:1.6;max-width:720px}
.events-metrics>div{min-width:94px;padding:12px 13px}
.events-metrics strong{font-size:27px}
.events-metrics span{font-size:10px}
.events-page{padding-top:44px}
.events-toolbar-premium{box-shadow:0 12px 35px color-mix(in srgb,var(--text-primary) 4%,transparent)}

/* Consistent focus treatment */
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--accent-gold);outline-offset:3px}

@media(max-width:1100px){
 .home .hero h1{font-size:clamp(60px,8vw,100px)}
 .impact-strip{grid-template-columns:1fr repeat(3,.6fr)}
}
@media(max-width:900px){
 .admin-shell{grid-template-columns:1fr}
 .admin-side{display:none}
 .impact-strip{grid-template-columns:1fr 1fr 1fr;gap:0}
 .impact-heading{grid-column:1/-1;padding:0 0 18px}
 .impact-stat{padding:10px 14px}
 .events-hero{grid-template-columns:1fr;gap:14px}
}
@media(max-width:760px){
 .home .hero{min-height:auto;padding:22px 0 20px}
 .home .hero-copy{padding:8px 0}
 .home .hero h1{font-size:clamp(48px,13vw,66px);line-height:.9}
 .home .hero-art{min-height:250px;height:250px}
 .home .home-layout .section{padding-top:46px;padding-bottom:46px}
 .pulse-strip{width:calc(100% - 28px);padding:12px 0;gap:12px;display:block}
 .pulse-items{margin-top:8px}
 .impact-strip{width:calc(100% - 28px);padding:30px 0;grid-template-columns:repeat(3,1fr)}
 .impact-heading{grid-column:1/-1}
 .impact-heading h2,.impact-empty h2{font-size:30px}
 .impact-stat{padding:8px 10px}
 .impact-stat strong{font-size:30px}
 .impact-stat span{font-size:8px;line-height:1.3}
 .impact-empty{display:block}
 .impact-empty-mark{display:block;margin-top:18px}
 .events-page{padding-top:30px}
 .events-hero h1{font-size:clamp(36px,10vw,50px);max-width:600px}
 .events-hero p{font-size:13px}
}
@media(prefers-reduced-motion:reduce){.pulse-strip,.impact-strip,.home .hero{animation:none!important}}

/* =========================================================
   JYC V9.2 — responsive editorial cleanup
   ========================================================= */
.compact-page-head{display:flex;justify-content:space-between;align-items:flex-end;gap:28px;margin-bottom:24px}
.compact-page-head h1{font:700 clamp(42px,5.5vw,72px)/.94 'Segoe UI',system-ui,sans-serif;letter-spacing:-.065em;margin:10px 0 12px}
.compact-page-head p{margin:0;color:var(--text-muted);font-size:15px;line-height:1.55;max-width:650px}
.page-stat-row{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}
.page-stat-row span{border:1px solid var(--border-tech);background:var(--bg-card);border-radius:999px;padding:8px 11px;color:var(--text-muted);font-size:10px;white-space:nowrap}
.page-stat-row b{color:var(--text-primary);font:700 14px 'Segoe UI',system-ui,sans-serif;margin-right:4px}
.discover-panel-compact{padding:12px 14px!important;margin-bottom:12px}
.discover-panel-compact .discover{margin-bottom:10px}
.club-search-row{display:grid;grid-template-columns:minmax(0,1fr) 190px 190px;gap:8px;align-items:center}
.club-search{display:flex;align-items:center;gap:9px;border:1px solid var(--border-tech);background:var(--bg-card);border-radius:13px;padding:0 12px;color:var(--text-muted)}
.club-search input{width:100%;border:0!important;background:none!important;color:var(--text-primary);padding:12px 0!important;outline:none}
.club-search>button,.event-search>button{border:0;background:none;color:var(--text-muted);font-size:20px;padding:4px}
.results-line{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:10px 0 14px;color:var(--text-muted);font:700 10px 'Segoe UI',system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase}
.results-line button{border:0;background:none;color:var(--accent-red);font:700 10px 'Segoe UI',system-ui,sans-serif}
.events-page-head{margin-bottom:18px}
.events-page .events-toolbar-premium{display:grid;grid-template-columns:minmax(0,1fr) 180px 180px;gap:8px;padding:10px}
.events-page .event-search{min-width:0}
.events-page .event-search input{width:100%}
.events-page .seg{margin:0;display:grid;grid-template-columns:1fr 1fr;gap:6px}
.events-page .seg button{border:1px solid var(--border-tech);background:transparent;color:var(--text-muted);border-radius:11px;padding:9px 10px}
.events-page .seg button.active{background:var(--text-primary);color:var(--bg-main)}
.events-page .event-scope-tabs{margin:12px 0 16px}
.events-page .event-card-premium .event-poster{min-height:200px}
.events-page .event-card-premium .card-body h3{font-size:22px}

/* Admin command palette — replace browser-default/raw button appearance */
.command-trigger{display:inline-flex;align-items:center;gap:9px}
.command-trigger kbd,.admin-command-search kbd{font:700 9px 'Segoe UI',system-ui,sans-serif;letter-spacing:.08em;border:1px solid var(--border-tech);border-radius:6px;padding:3px 6px;color:var(--text-muted);background:var(--bg-main)}
.admin-command-overlay{position:fixed;inset:0;z-index:5000;background:rgba(8,7,10,.64);backdrop-filter:blur(12px);display:grid;place-items:start center;padding:11vh 18px 30px}
.admin-command{width:min(680px,100%);max-height:min(72vh,720px);overflow:hidden;border:1px solid var(--border-tech);border-radius:22px;background:var(--bg-card);box-shadow:0 35px 100px rgba(0,0,0,.42);animation:adminCommandIn .2s ease both}
.admin-command-head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:20px 20px 12px}
.admin-command-head h3{font:700 32px/1 'Segoe UI',system-ui,sans-serif;letter-spacing:-.04em;margin:7px 0 4px}
.admin-command-head p{margin:0;color:var(--text-muted);font-size:12px}
.admin-command-head .icon-btn{white-space:nowrap;padding:8px 10px}
.admin-command-search{margin:0 20px 10px;display:flex;align-items:center;gap:10px;border:1px solid var(--border-tech);border-radius:13px;background:var(--bg-main);padding:0 12px}
.admin-command-search>span{color:var(--accent-red);font-size:19px}
.admin-command-search input{width:100%;border:0!important;outline:none!important;background:none!important;color:var(--text-primary);padding:13px 0!important;box-shadow:none!important}
.admin-command-list{padding:4px 10px 12px;max-height:48vh;overflow:auto}
.admin-command-list>button{width:100%;display:grid;grid-template-columns:34px minmax(0,1fr) 20px;align-items:center;gap:10px;text-align:left;border:1px solid transparent;background:transparent;color:var(--text-primary);border-radius:14px;padding:10px 11px;cursor:pointer}
.admin-command-list>button:hover,.admin-command-list>button:focus-visible{background:var(--bg-main);border-color:var(--border-tech);outline:none}
