/* ===== mobile-polish.css ===== */
/* JYC V6.5 — Mobile UI V2: compact app-style mobile experience */
html{scroll-behavior:smooth;scrollbar-width:thin;scrollbar-color:var(--accent-red) transparent}
*,*::before,*::after{box-sizing:border-box}
body{overflow-x:hidden;-webkit-tap-highlight-color:transparent;scrollbar-width:thin;scrollbar-color:var(--accent-red) transparent}
body::-webkit-scrollbar{width:5px}
body::-webkit-scrollbar-track{background:transparent}
body::-webkit-scrollbar-thumb{background:var(--accent-red);border-radius:99px}
button,a,input,textarea,select{-webkit-tap-highlight-color:transparent}
button{touch-action:manipulation}
img{max-width:100%}

.nav,.nav-inner,.search-trigger,.hamb,.mobile-nav-scrim,.theme-toggle,.btn,.card,.featured,.principles>div,.club-card-visual,.event-card,.gallery-item,.contact-card,.quick-grid button,.admin-side,.admin-row,.search-modal,.overlay,.mobile-dock{transition:background-color .22s ease,border-color .22s ease,color .22s ease,box-shadow .22s ease,transform .22s cubic-bezier(.2,.7,.2,1),opacity .22s ease}

/* Header: always available */
.nav{position:sticky!important;top:0!important;z-index:900!important;width:100%;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
.nav-inner{min-height:64px!important;width:min(1240px,calc(100% - 18px));margin:auto;display:flex;align-items:center;gap:7px}
