.brand img{width:38px!important;height:38px!important;flex:0 0 38px!important;object-fit:contain}
.brand span{font-size:11px!important;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hamb,.search-trigger{flex:0 0 42px;width:42px!important;min-width:42px!important;height:42px!important;padding:0!important;display:inline-flex!important;align-items:center;justify-content:center}
.search-trigger span,.search-trigger kbd{display:none!important}

/* Menu: avoids theme control overlap */
.nav-inner>nav.open{position:fixed!important;left:8px!important;right:8px!important;top:122px!important;z-index:910!important;width:auto!important;max-height:calc(100dvh - 140px);overflow-y:auto;overscroll-behavior:contain;display:flex!important;flex-direction:column!important;gap:3px!important;padding:10px!important;border:1px solid var(--border-tech);border-radius:20px;background:var(--bg-card);box-shadow:0 24px 80px rgba(0,0,0,.3);animation:jycMenuIn .2s ease both;scrollbar-width:thin;scrollbar-color:var(--accent-red) transparent}
.nav-inner>nav.open::-webkit-scrollbar{width:4px}.nav-inner>nav.open::-webkit-scrollbar-thumb{background:var(--accent-red);border-radius:99px}
.nav-inner>nav.open button{width:100%;min-height:48px;padding:0 14px;border-radius:12px;text-align:left}
.nav-inner>nav.open .admin-nav{margin-top:5px;border-top:1px solid var(--border-tech);border-radius:12px}
.mobile-nav-scrim{position:fixed!important;inset:64px 0 0!important;z-index:905!important;border:0!important;background:rgba(0,0,0,.38)!important;backdrop-filter:blur(3px)}
@keyframes jycMenuIn{from{opacity:0;transform:translateY(-8px) scale(.98)}to{opacity:1;transform:none}}
