/* Mode button: always visible */
.theme-toggle{position:fixed!important;top:74px!important;right:10px!important;z-index:1000!important;width:42px!important;height:42px!important;border-radius:50%!important;box-shadow:0 8px 28px rgba(0,0,0,.14)}

/* Mobile bottom navigation — app-like */
.mobile-dock{display:none}

/* Search */
.search-overlay{position:fixed!important;inset:0!important;z-index:1200!important;padding:70px 9px 10px!important;display:flex!important;align-items:flex-start!important;justify-content:center!important;background:rgba(0,0,0,.44)!important;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.search-modal{width:min(700px,100%)!important;max-height:calc(100dvh - 82px);overflow:auto;border-radius:22px!important;animation:jycSearchIn .22s cubic-bezier(.2,.8,.2,1) both}
@keyframes jycSearchIn{from{opacity:0;transform:translateY(-14px) scale(.98)}to{opacity:1;transform:none}}

/* Compact hero — no viewport-sized gaps */
.hero,.hero-art,.hero-copy,.home-layout,.section,.page{min-height:0!important}
.hero{height:auto!important;padding-top:32px!important;padding-bottom:22px!important}
