.events-metrics>div{min-width:0!important;padding:11px 6px!important}.event-toolbar{display:flex!important;flex-direction:column!important;gap:7px!important}.event-search{width:100%!important}.event-toolbar select{width:100%!important;min-height:44px}.seg{width:100%!important;display:grid!important;grid-template-columns:1fr 1fr}.seg button{min-height:42px}.event-scope-tabs{display:flex!important;overflow-x:auto;scrollbar-width:thin;scrollbar-color:var(--accent-red) transparent;gap:5px!important;padding-bottom:4px}.event-scope-tabs button{flex:0 0 auto;min-height:40px}

/* Club detail */
.club-detail-hero{min-height:0!important;display:flex!important;flex-direction:column-reverse!important;gap:15px;padding:17px!important}.detail-logo-wrap{align-self:center}.detail-logo{width:112px!important;height:112px!important}.club-hero-copy h1{font-size:clamp(32px,9.5vw,50px)!important;line-height:.98}.club-detail-nav{position:sticky;top:64px;z-index:500;overflow-x:auto;display:flex!important;gap:6px!important;padding:7px!important;scrollbar-width:none}.club-detail-nav::-webkit-scrollbar{display:none}.club-detail-nav a{flex:0 0 auto;white-space:nowrap;min-height:36px;display:flex;align-items:center;padding:0 11px;border:1px solid var(--border-tech);border-radius:999px}.club-detail-layout{display:flex!important;flex-direction:column!important;gap:12px!important}.club-side-panel{order:-1!important}.leadership-grid,.join-grid{grid-template-columns:1fr!important}.club-section-card{padding:15px!important}.club-section-card h2{font-size:24px!important}

/* Gallery */
.gallery-filter{display:flex!important;overflow-x:auto;gap:5px!important;scrollbar-width:none}.gallery-filter::-webkit-scrollbar{display:none}.gallery-filter button{flex:0 0 auto;min-height:38px}.gallery-grid{grid-template-columns:repeat(2,1fr)!important;gap:6px!important}.gallery-item{min-height:0!important}.gallery-item img{aspect-ratio:1/1;object-fit:cover}
