/* Admin */
.admin-shell{min-height:100dvh!important;display:block!important}.admin-side{position:sticky!important;top:0!important;z-index:850!important;width:100%!important;height:auto!important;min-height:0!important;padding:8px!important;border-right:0!important;border-bottom:1px solid var(--border-tech);background:var(--bg-card);backdrop-filter:blur(16px)}
.admin-brand img{width:34px!important;height:34px!important}.admin-side nav{display:flex!important;flex-direction:row!important;overflow-x:auto!important;gap:5px!important;padding:4px 0 5px!important;scrollbar-width:thin;scrollbar-color:var(--accent-red) transparent}.admin-side nav button{flex:0 0 auto!important;min-height:37px!important;padding:0 11px!important;border:1px solid var(--border-tech)!important;border-radius:999px!important;white-space:nowrap;font-size:10.5px!important}.admin-side nav button.active{background:var(--accent-red)!important;border-color:var(--accent-red)!important;color:#fff!important}.admin-side .nav-dot,.admin-side .logout{display:none!important}.admin-main{width:100%!important;min-width:0!important;padding:0!important}.admin-top{display:flex!important;flex-direction:column!important;gap:10px!important;padding:19px 12px 7px!important}.admin-top h1{font-size:clamp(28px,8.5vw,42px)!important}.admin-top-actions{display:grid!important;grid-template-columns:1fr 1fr!important;gap:6px!important}.admin-content{width:100%!important;padding:13px 12px 82px!important}.admin-stats{grid-template-columns:repeat(2,1fr)!important;gap:7px!important}.admin-stats>div{min-height:92px!important;padding:12px!important}.quick-grid{grid-template-columns:1fr!important;gap:8px!important}.quick-grid button{min-height:110px!important;padding:14px!important}.form-grid{grid-template-columns:1fr!important}.editor-card,.welcome-card{padding:14px!important;border-radius:15px!important}.form-actions{display:grid!important;grid-template-columns:1fr 1fr!important;gap:6px!important}.form-actions .btn{width:100%!important}.admin-row{display:grid!important;grid-template-columns:auto minmax(0,1fr)!important;gap:8px!important;padding:11px!important;border:1px solid var(--border-tech);border-radius:14px;margin-bottom:7px}.admin-row .row-main{min-width:0}.admin-row .row-main strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.admin-row>.smallbtn{grid-column:1/-1}.club-editor-tabs{overflow-x:auto;scrollbar-width:none}

