   Loaded last so it intentionally resolves legacy patch conflicts.
   ========================================================= */

/* ---------- Global hierarchy ---------- */
:root{
  --v10-content-max:1280px;
  --v10-page-gutter:clamp(16px,3.5vw,48px);
  --v10-radius:20px;
  --v10-fast:180ms;
  --v10-med:420ms;
}
html{scroll-padding-top:78px}
body{
  font-size:15px;
  line-height:1.55;
  overflow-x:hidden;
}
button,a,input,textarea,select{font-size:inherit}
.section,.hero,.nav-inner,.announcement{max-width:var(--v10-content-max)}
.section{padding-block:76px}
.page{padding-top:34px}
.section-head{max-width:760px;margin-bottom:30px}
.section-head h2{
  font-size:clamp(32px,5vw,60px)!important;
  line-height:1!important;
  letter-spacing:-.045em!important;
}
.section-head p,.hero-copy>p{font-size:16px;line-height:1.65}
.eyebrow{font-size:10px;letter-spacing:.18em}
.btn{min-height:44px;padding:11px 16px;border-radius:12px;font-size:13px}
.text-link{font-size:13px}
.tag,.pin-badge{font-size:9px}

/* ---------- Header: compact and stable ---------- */
.nav-inner{height:76px}
.brand img{width:50px;height:50px}
.brand span{font-size:15px}
.nav nav{gap:2px}
.nav nav button{padding:10px 11px;font-size:13px}
.search-trigger{min-height:42px;padding:8px 12px;font-size:12px}
.theme-toggle{width:46px;height:46px}

/* ---------- Hero: editorial, not oversized ---------- */
.hero{
  min-height:calc(100svh - 76px);
  gap:20px;
}
.hero-copy{padding:42px 0}
.hero h1{
  font-size:clamp(54px,8.5vw,118px)!important;
  line-height:.86!important;
  letter-spacing:-.075em!important;
  margin:24px 0 26px!important;
}
.hero h4{font-size:14px;letter-spacing:.18em;margin-bottom:17px}
.hero-rule{width:96px;height:3px;margin-bottom:24px}
.hero-actions{margin-top:24px}
.hero-quick{margin-top:34px}
.hero-quick button{padding-top:13px}
.hero-quick button strong{font-size:14px}
.hero-quick button em{font-size:11px}

/* ---------- Orbit system: more depth, still quiet ---------- */
.hero-art{
  min-height:520px;
  overflow:visible;
  isolation:isolate;
}
.hero-art:after{
  content:"";
  position:absolute;
  width:min(520px,70vw);
  aspect-ratio:1;
  border-radius:50%;
  border:1px solid color-mix(in srgb,var(--accent-red) 10%,transparent);
  box-shadow:
    0 0 0 32px color-mix(in srgb,var(--accent-gold) 3%,transparent),
    0 0 90px color-mix(in srgb,var(--accent-gold) 6%,transparent);
  animation:orbitBreath 8s ease-in-out infinite;
  pointer-events:none;
  z-index:-1;
}
.orbit{
  border-width:1px!important;
  opacity:.55;
  animation:orbitDrift 26s linear infinite!important;
}
.o1{width:540px!important;height:540px!important}
.o2{width:680px!important;height:410px!important;animation-duration:34s!important}
.o3{width:430px!important;height:650px!important;animation-duration:42s!important}
.o2{transform:rotate(28deg)}
.o3{transform:rotate(-54deg)}
.o1:before,.o2:before,.o3:before{
  content:"";
  position:absolute;
  width:7px;height:7px;border-radius:50%;
  background:var(--accent-gold);
  box-shadow:0 0 14px color-mix(in srgb,var(--accent-gold) 50%,transparent);
}
.o1:before{left:17%;top:8%}
.o2:before{right:13%;top:25%;background:var(--accent-red)}
.o3:before{left:21%;bottom:12%}
.logo-core{
  width:min(290px,30vw)!important;
  background:color-mix(in srgb,var(--bg-card) 78%,transparent)!important;
  backdrop-filter:blur(5px);
  animation:logoFloat 7s ease-in-out infinite!important;
}
.logo-core img{width:68%;height:68%}
.float-chip{font-size:9px;padding:9px 12px}
.chip1{top:15%;left:4%}
.chip2{right:4%;bottom:16%}

@keyframes orbitDrift{
  0%{transform:rotate(0deg) scale(1)}
  50%{transform:rotate(180deg) scale(1.015)}
  100%{transform:rotate(360deg) scale(1)}
}
@keyframes orbitBreath{
  0%,100%{opacity:.45;transform:scale(.98)}
  50%{opacity:.75;transform:scale(1.025)}
}
@keyframes logoFloat{
  0%,100%{transform:translateY(0) rotate(0deg)}
  50%{transform:translateY(-7px) rotate(.5deg)}
}

/* ---------- Ambient section ornaments ---------- */
.home-layout>.section,
.home-layout>.dark-band{position:relative;isolation:isolate}
.home-layout>.section:not(.cta):after{
  content:"";
  position:absolute;
  width:360px;height:180px;
  right:-170px;top:18%;
  border:1px solid color-mix(in srgb,var(--accent-gold) 12%,transparent);
  border-radius:50%;
  transform:rotate(-18deg);
  pointer-events:none;
  opacity:.55;
  animation:sectionOrbit 16s linear infinite;
}
.home-layout>.dark-band:after{
  content:"";
  position:absolute;
  width:460px;height:220px;
  right:-210px;bottom:-90px;
  border:1px solid color-mix(in srgb,var(--accent-red) 9%,transparent);
  border-radius:50%;
  transform:rotate(24deg);
  pointer-events:none;
  animation:sectionOrbit 20s linear infinite reverse;
}
.cta{position:relative;isolation:isolate;overflow:hidden}
.cta:before{
  content:"";
  position:absolute;
  width:420px;height:180px;
  right:-160px;top:-40px;
  border:1px solid color-mix(in srgb,var(--accent-gold) 13%,transparent);
  border-radius:50%;
  transform:rotate(-22deg);
  animation:sectionOrbit 18s linear infinite;
  pointer-events:none;
}
@keyframes sectionOrbit{
  to{transform:rotate(338deg)}
}

/* ---------- Content cards ---------- */
.card,.featured,.contact-card,.gallery-item,.quick-grid button,.editor-card{
  box-shadow:0 10px 34px color-mix(in srgb,var(--text-primary) 5%,transparent);
}
.card:hover,.featured:hover,.contact-card:hover,.gallery-item:hover{
  box-shadow:0 18px 48px color-mix(in srgb,var(--text-primary) 8%,transparent);
}
.card h3{font-size:21px}
.card p{font-size:14px;line-height:1.6}
.card-body{padding:18px}

/* ---------- Event cards ---------- */
.event-grid-premium{grid-template-columns:repeat(3,minmax(0,1fr))}
.event-card-premium .event-poster{
