  display:flex;gap:6px;z-index:2;
}
.save-btn{
  min-height:34px!important;
  border:1px solid var(--border-tech)!important;
  background:color-mix(in srgb,var(--bg-card) 92%,transparent)!important;
  color:var(--text-primary)!important;
