}
.save-btn.saved{background:var(--accent-red)!important;color:#fff!important;border-color:var(--accent-red)!important}
.event-card-meta{display:grid;gap:5px;margin:14px 0;color:var(--text-muted);font-size:11px}
.event-card-meta span:first-child{color:var(--text-primary);font-weight:600}

/* ---------- Pages ---------- */
.compact-page-head{
  display:flex;justify-content:space-between;align-items:end;gap:25px;
  margin-bottom:28px;
}
.compact-page-head h1,.feature-hero h1{
  font:700 clamp(38px,6vw,72px)/.94 'Space Grotesk';
  letter-spacing:-.06em;
  margin:10px 0 14px;
}
.compact-page-head p,.feature-hero p{color:var(--text-muted);max-width:650px;font-size:15px}
.page-stat-row{display:flex;gap:8px;flex-wrap:wrap}
.page-stat-row span{
  border:1px solid var(--border-tech);background:var(--bg-card);
  border-radius:999px;padding:8px 11px;color:var(--text-muted);font-size:10px;
}
.page-stat-row b{color:var(--text-primary);font:700 13px 'Space Grotesk'}
.events-live-strip{
  display:flex;align-items:center;gap:12px;
