  background:var(--bg-card);padding:13px 15px;border-radius:15px;margin-bottom:14px;
}
.events-live-strip>div{display:grid;gap:2px;min-width:0;flex:1}
.events-live-strip small{color:var(--accent-red);font:700 9px 'Space Grotesk';letter-spacing:.13em}
.events-live-strip strong{font:700 15px 'Space Grotesk'}
.events-live-strip span{font-size:11px;color:var(--text-muted)}
.event-toolbar{
  background:color-mix(in srgb,var(--bg-card) 55%,transparent);
  padding:7px;border:1px solid var(--border-tech);border-radius:17px;
}
.event-toolbar input,.event-toolbar select{min-height:42px;padding:10px 12px}

/* ---------- Club cards ---------- */
.clubs-grid-premium{grid-template-columns:repeat(3,minmax(0,1fr))}
.club-card-premium{display:block;padding:0;overflow:hidden}
.club-card-visual{
  min-height:220px;aspect-ratio:16/10;
  position:relative;background-size:cover;background-position:center;
  background-color:var(--bg-main);
}
.club-card-visual:after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 48%,color-mix(in srgb,var(--bg-main) 62%,transparent));
