/* ---------- Feature pages / calendar / My JYC ---------- */
.feature-hero{max-width:820px;margin-bottom:30px}
.feature-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.feature-card{border:1px solid var(--border-tech);background:var(--bg-card);border-radius:18px;padding:20px}
