/* ---------- Contact / footer ---------- */
.contact-card{padding:24px}
.contact-card h3{font-size:25px}
footer{padding-block:40px}
.footer-links{gap:13px;font-size:12px}

/* ---------- Search: polished, mobile-first sheet ---------- */
.search-overlay{padding:82px 16px 20px;align-items:start}
