  background:var(--bg-main);
}
.search-input-wrap input{
  min-width:0;flex:1;border:0!important;background:transparent!important;
  box-shadow:none!important;padding:10px 0!important;font-size:16px;
}
.search-input-wrap kbd{font-size:9px;color:var(--text-muted)}
.search-clear{border:0;background:none;color:var(--text-muted);font-size:20px}
.search-suggestions{display:flex;gap:6px;align-items:center;overflow:auto;padding:12px 0 3px}
.search-suggestions>span{font:700 9px 'Space Grotesk';color:var(--text-muted);letter-spacing:.13em;flex:0 0 auto}
.search-suggestions button{
  flex:0 0 auto;border:1px solid var(--border-tech);background:var(--bg-card);
  color:var(--text-primary);border-radius:999px;padding:8px 10px;font-size:10px;
}
.search-meta{display:flex;justify-content:space-between;gap:10px;margin:12px 0 7px;color:var(--text-muted);font-size:10px}
.search-list{max-height:52vh;gap:4px}
.search-list button{
