}
.search-list strong{font-size:13px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.search-list span{font-size:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.search-footer{font-size:8px;margin-top:10px}


.search-recent{
  display:flex;align-items:center;gap:6px;overflow:auto;
