/* ===== v13-0-9-ui.css ===== */
/* JYC V13.0.9 — identity refresh + viewport-safe navigation + glass search.
   This file is intentionally last in the cascade. */

:root{
  --jyc-red:#c92a2a;
  --jyc-gold:#d2b48c;
  --jyc-cream:#fff8e1;
  --jyc-dark:#0f0e11;
  --jyc-card:#18161d;
  --jyc-glass:color-mix(in srgb,var(--bg-card) 76%,transparent);
}

/* The reference composition: strong left copy, restrained orbital mark, compact stats. */
.hero{
  width:min(1440px,calc(100% - 56px))!important;
  min-height:clamp(570px,calc(100vh - 96px),760px)!important;
  grid-template-columns:minmax(0,1.04fr) minmax(390px,.96fr)!important;
  gap:20px!important;
  padding:38px 0 24px!important;
}
.hero-copy{padding:20px 0!important;max-width:800px!important;z-index:2}
.hero h1{font-size:clamp(68px,7.2vw,122px)!important;line-height:.84!important;letter-spacing:-.085em!important;max-width:720px!important;margin:30px 0 27px!important}
.hero-rule{width:102px!important;height:3px!important;margin-bottom:24px!important}
.hero h4{font-size:15px!important;letter-spacing:.23em!important;margin-bottom:18px!important}
.hero-copy>p{font-size:17px!important;line-height:1.58!important;max-width:650px!important}
.hero-actions{margin-top:25px!important}
.hero-actions .btn{min-width:175px!important;border-radius:999px!important;padding:13px 22px!important}
.hero-stats{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;max-width:640px!important;margin-top:24px!important;border-top:1px solid var(--border-tech)!important;padding-top:15px!important}
.hero-stats>div{min-width:0;padding:0 14px;border-right:1px solid var(--border-tech);display:grid;gap:2px}
.hero-stats>div:first-child{padding-left:0}.hero-stats>div:last-child{border-right:0}
.hero-stats strong{font:700 20px/1 'Space Grotesk'!important;letter-spacing:-.04em!important}
.hero-stats span{font-size:9px!important;color:var(--text-muted)!important;letter-spacing:.06em!important;text-transform:uppercase}
.hero-quick{margin-top:22px!important;border-top:1px solid var(--border-tech)!important;max-width:840px!important}
.hero-quick button{min-height:68px!important}
.hero-art{min-height:520px!important;overflow:visible!important}
.hero-art:before{content:"";position:absolute;inset:8% 4%;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--accent-red) 7%,transparent) 0%,transparent 58%);pointer-events:none}
.logo-core{width:clamp(260px,28vw,360px)!important;background:color-mix(in srgb,var(--bg-card) 72%,transparent)!important;box-shadow:0 0 0 20px color-mix(in srgb,var(--accent-gold) 3%,transparent),0 28px 100px color-mix(in srgb,var(--accent-red) 8%,transparent)!important}
.logo-core img{width:73%!important;height:73%!important;filter:drop-shadow(0 10px 25px color-mix(in srgb,var(--accent-gold) 12%,transparent))}
.orbit{opacity:.72!important}.o1{width:510px!important;height:510px!important}.o2{width:620px!important;height:390px!important}.o3{width:430px!important;height:610px!important}
.float-chip{font-size:8px!important;padding:8px 11px!important;letter-spacing:.16em!important}

/* Portal-mounted mobile navigation: fixed to the viewport, never to the header. */
.mobile-dock{display:none!important}
@media(max-width:700px){
  body{padding-bottom:88px!important}
  .mobile-dock{
    display:grid!important;position:fixed!important;left:max(7px,env(safe-area-inset-left))!important;right:max(7px,env(safe-area-inset-right))!important;bottom:max(7px,env(safe-area-inset-bottom))!important;top:auto!important;width:auto!important;height:auto!important;
    grid-template-columns:repeat(5,minmax(0,1fr))!important;gap:3px!important;padding:5px!important;z-index:3000!important;
    border:1px solid color-mix(in srgb,var(--accent-gold) 36%,var(--border-tech))!important;border-radius:22px!important;
    background:color-mix(in srgb,var(--bg-card) 82%,transparent)!important;backdrop-filter:blur(24px) saturate(130%)!important;-webkit-backdrop-filter:blur(24px) saturate(130%)!important;
    box-shadow:0 18px 60px rgba(0,0,0,.28),inset 0 1px 0 color-mix(in srgb,#fff 12%,transparent)!important;
  }
  .mobile-dock:before{content:"";position:absolute;left:13%;right:13%;top:0;height:1px;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent-gold) 60%,transparent),transparent);opacity:.8}
  .mobile-dock button{min-height:52px!important;border:0!important;border-radius:16px!important;background:transparent!important;color:var(--text-muted)!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:3px!important;padding:4px 2px!important;font-size:9px!important;font-weight:750!important;transition:transform .2s ease,background .2s ease,color .2s ease!important}
