  .hero{width:calc(100% - 24px)!important;min-height:0!important;grid-template-columns:1fr!important;gap:6px!important;padding:28px 0 16px!important}
  .hero-copy{padding:10px 0!important}.hero h1{font-size:clamp(44px,13vw,64px)!important;line-height:.86!important;margin:20px 0 22px!important;max-width:100%!important}
  .hero-copy>p{font-size:14px!important;line-height:1.58!important}.hero-rule{width:82px!important;margin-bottom:18px!important}.hero h4{font-size:12px!important;margin-bottom:14px!important}
  .hero-actions{display:grid!important;grid-template-columns:1fr 1fr!important;gap:8px!important;margin-top:20px!important}.hero-actions .btn{min-width:0!important;width:100%!important;padding:12px 10px!important;font-size:12px!important}
  .hero-stats{max-width:none!important;margin-top:18px!important;padding-top:13px!important}.hero-stats>div{padding:0 7px!important}.hero-stats strong{font-size:17px!important}.hero-stats span{font-size:7px!important}
  .hero-quick{margin-top:14px!important}.hero-quick button{min-height:62px!important}
  .hero-art{order:2!important;height:245px!important;min-height:245px!important;margin-top:0!important}.logo-core{width:185px!important}.o1{width:235px!important;height:235px!important}.o2{width:285px!important;height:175px!important}.o3{width:190px!important;height:270px!important}.float-chip{font-size:7px!important;padding:7px 9px!important}.chip1{left:2%!important;top:10%!important}.chip2{right:2%!important;bottom:10%!important}
}

