.search-input-wrap input{font-size:21px!important;background:transparent!important}.search-input-wrap>span{font-size:20px!important;color:var(--accent-red)!important}
.search-suggestions{margin-top:14px!important;gap:7px!important}.search-suggestions button,.search-recent button{border:1px solid var(--border-tech)!important;background:color-mix(in srgb,var(--bg-main) 35%,transparent)!important;color:var(--text-primary)!important;border-radius:999px!important;padding:9px 12px!important;font-size:10px!important}
