}

/* Reference-like hero: compact top chrome, strong copy, logo as the visual anchor. */
.hero{position:relative!important;isolation:isolate!important}
.hero-copy{align-self:center!important}
.hero-art{display:grid!important;place-items:center!important}
.hero-art .logo-core{z-index:3!important}
.logo-core{border:1px solid color-mix(in srgb,var(--accent-gold) 30%,transparent)!important}
.logo-core:before{content:"";position:absolute;inset:9%;border:1px solid color-mix(in srgb,var(--accent-gold) 22%,transparent);border-radius:50%;pointer-events:none}
.logo-core:after{content:"";position:absolute;inset:-18px;border:1px solid color-mix(in srgb,var(--accent-red) 12%,transparent);border-radius:50%;pointer-events:none;animation:referencePulse 7s ease-in-out infinite}
@keyframes referencePulse{0%,100%{transform:scale(.98);opacity:.4}50%{transform:scale(1.02);opacity:.8}}

