.activity-card button{margin-top:auto;padding-top:18px;border:0;background:none;color:var(--text-primary);font:700 10px 'DM Sans';cursor:pointer}
.activity-empty{padding:32px;border:1px dashed var(--border-tech);border-radius:20px;display:grid;gap:6px;background:color-mix(in srgb,var(--bg-card) 70%,transparent)}
.activity-empty strong{font-size:20px}.activity-empty p{margin:0;color:var(--text-muted);font-size:12px}
.past-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:20px}
.past-card{min-height:170px;text-align:left;padding:20px;border:1px solid var(--border-tech);border-radius:20px;background:color-mix(in srgb,var(--bg-card) 90%,transparent);display:grid;grid-template-columns:32px 1fr 20px;gap:12px;color:var(--text-primary);cursor:pointer;transition:transform .24s ease,border-color .24s ease}
.past-card:hover{transform:translateY(-3px);border-color:color-mix(in srgb,var(--accent-gold) 55%,var(--border-tech))}.past-card small{color:var(--text-muted);font-size:9px}.past-card h3{font-size:19px;margin:10px 0 7px}.past-card p{font-size:11px;color:var(--text-muted);line-height:1.45;margin:0}.past-card>b{justify-self:end}

/* Footer is now a real navigation surface rather than only two links. */
.jyc-footer{margin-top:24px!important;padding:46px max(24px,5vw) 22px!important;border-top:1px solid var(--border-tech)!important;background:color-mix(in srgb,var(--bg-card) 55%,var(--bg-main))!important}
.footer-top{max-width:1440px;margin:auto;display:grid;grid-template-columns:1.5fr 1fr .65fr;gap:40px}.footer-brand{display:flex;gap:16px;align-items:flex-start}.footer-logo-lockup{position:relative;flex:0 0 auto}.footer-logo-lockup img{width:66px;height:66px;border-radius:50%;border:1px solid var(--border-tech);padding:4px}.footer-logo-lockup span{display:none}.footer-brand strong{display:block;font-size:16px}.footer-brand span{display:block;margin-top:3px;font:700 8px 'Space Grotesk';letter-spacing:.16em;color:var(--accent-red)}.footer-brand p{max-width:430px;color:var(--text-muted);font-size:11px;line-height:1.5;margin:12px 0 0}.footer-nav>div{display:grid;grid-template-columns:repeat(2,1fr);gap:5px 18px;margin-top:12px}.footer-nav button,.footer-connect a{border:0;background:none;color:var(--text-muted);text-align:left;font-size:11px;padding:4px 0;cursor:pointer;text-decoration:none}.footer-nav button:hover,.footer-connect a:hover{color:var(--text-primary)}.footer-connect{display:grid;align-content:start;gap:5px}.footer-connect .eyebrow{margin-bottom:7px}.footer-bottom{max-width:1440px;margin:34px auto 0;padding-top:14px;border-top:1px solid var(--border-tech);display:flex;justify-content:space-between;color:var(--text-muted);font:700 8px 'Space Grotesk';letter-spacing:.12em}.footer-bottom span{color:var(--accent-red)}

/* Search: command surface feels like the site, not a generic modal. */
.search-overlay{background:rgba(8,7,10,.56)!important;backdrop-filter:blur(20px) saturate(120%)!important;-webkit-backdrop-filter:blur(20px) saturate(120%)!important}
.search-modal{border-radius:26px!important;background:color-mix(in srgb,var(--bg-card) 73%,transparent)!important;box-shadow:0 30px 100px rgba(0,0,0,.34),inset 0 1px 0 rgba(255,255,255,.07)!important}
