.search-input-wrap:focus-within{border-color:var(--accent-red)!important;box-shadow:0 0 0 4px color-mix(in srgb,var(--accent-red) 8%,transparent)!important}
.search-input-wrap input:focus{outline:none!important;box-shadow:none!important}
