/* Admin: role identity + guide as a useful workspace header, not a billboard. */
.admin-side{border-right:1px solid var(--border-tech)!important}
.admin-brand{margin-bottom:6px!important}.admin-brand img{box-shadow:0 0 0 5px color-mix(in srgb,var(--accent-gold) 5%,transparent)!important}
