.admin-guide:after{content:"";position:absolute;right:-80px;top:-80px;width:180px;height:180px;border:1px solid color-mix(in srgb,var(--accent-gold) 14%,transparent);border-radius:50%;pointer-events:none}
.admin-guide-head{padding:17px!important}.admin-guide-steps{padding:0 17px 17px!important}
.admin-command-overlay{backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important;background:rgba(7,6,9,.62)!important}

