.fest-logo-wrap{position:relative!important}.fest-logo-wrap:after{content:"";position:absolute;inset:-12px;border:1px solid color-mix(in srgb,var(--accent-gold) 25%,transparent);border-radius:50%;animation:referencePulse 7s ease-in-out infinite}
.fest-now-card,.fest-next-card{border-radius:22px!important}.fest-tabs{border:1px solid var(--border-tech)!important;border-radius:18px!important;background:color-mix(in srgb,var(--bg-card) 74%,transparent)!important;backdrop-filter:blur(16px)!important;-webkit-backdrop-filter:blur(16px)!important}

/* Mobile: no cramped grids, no horizontal page overflow, thumb-friendly controls. */
@media(max-width:900px){.activity-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.past-grid{grid-template-columns:1fr 1fr}.footer-top{grid-template-columns:1fr 1fr;gap:28px}.footer-brand{grid-column:1/-1}}
@media(max-width:700px){
