@media(max-width:380px){.activity-card,.past-card{padding:16px}.footer-brand p{font-size:10px}.footer-nav>div{grid-template-columns:1fr 1fr}}

@media(prefers-reduced-motion:reduce){.logo-core:after,.fest-logo-wrap:after,.referencePulse{animation:none!important}.activity-card,.past-card{transition:none!important}}


