  .theme-toggle{top:76px!important;right:10px!important;width:42px!important;height:42px!important;z-index:4800!important;background:color-mix(in srgb,var(--bg-card) 76%,transparent)!important;backdrop-filter:blur(18px)!important;-webkit-backdrop-filter:blur(18px)!important}

