  .search-empty{min-height:260px!important;padding:32px 16px!important}.search-empty p{font-size:13px!important;line-height:1.55!important}

  /* Keep page content above the fixed dock and away from phone edges. */
  .page{padding-top:28px!important;padding-bottom:24px!important}
  .section{width:calc(100% - 28px)!important}
}

