/* V17 reliability UI: accessible confirmations and richer feedback without adding a new visual language. */
.confirm-overlay{position:fixed;inset:0;z-index:6000;display:grid;place-items:center;padding:20px;background:rgba(8,7,10,.66);backdrop-filter:blur(14px);animation:v17FadeIn .18s ease both}
.confirm-dialog{width:min(500px,100%);border:1px solid var(--border-tech);border-radius:24px;background:var(--bg-card);box-shadow:0 30px 90px rgba(0,0,0,.45);padding:28px;animation:v17DialogIn .22s var(--ease) both}
.confirm-dialog h2{font:700 clamp(28px,5vw,40px)/1 'Space Grotesk';letter-spacing:-.045em;margin:9px 0 12px}
.confirm-dialog p{margin:0;color:var(--text-muted);line-height:1.65;font-size:14px;max-width:60ch}
.confirm-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:24px;flex-wrap:wrap}
.toast{display:flex;align-items:center;gap:9px;max-width:min(440px,calc(100vw - 32px));border:1px solid color-mix(in srgb,var(--text-primary) 15%,transparent);padding:12px 16px!important;line-height:1.35}
.toast span{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font:800 11px 'Space Grotesk';background:var(--accent-red);color:#fff;flex:0 0 auto}
.toast-error{background:var(--accent-red);color:#fff;border-color:transparent}
.toast-error span{background:#fff;color:var(--accent-red)}
@keyframes v17FadeIn{from{opacity:0}to{opacity:1}}
@keyframes v17DialogIn{from{opacity:0;transform:translateY(8px) scale(.985)}to{opacity:1;transform:none}}
@media(max-width:600px){.confirm-dialog{padding:22px;border-radius:20px}.confirm-actions{display:grid;grid-template-columns:1fr}.confirm-actions .btn{width:100%}.toast{right:16px;bottom:84px}}
@media(prefers-reduced-motion:reduce){.confirm-overlay,.confirm-dialog{animation:none}}


/* ===== v17-4-seo.css ===== */
/* V17.4 discoverability surfaces: quiet, content-first styling. */
.seo-topic-panel{margin:2rem 0 2.5rem;padding:clamp(1.25rem,3vw,2.25rem);border:1px solid var(--line,rgba(0,0,0,.12));border-radius:24px;background:linear-gradient(135deg,rgba(180,24,34,.06),rgba(180,24,34,.015));position:relative;overflow:hidden}
.seo-topic-panel:after{content:"";position:absolute;width:180px;height:180px;border-radius:50%;right:-70px;top:-90px;border:1px solid rgba(180,24,34,.16);box-shadow:0 0 0 22px rgba(180,24,34,.025),0 0 0 44px rgba(180,24,34,.018)}
.seo-topic-panel h2{max-width:760px;margin:.35rem 0 .65rem;font-size:clamp(1.5rem,3vw,2.3rem);letter-spacing:-.03em}
.seo-topic-panel p{max-width:760px;color:var(--muted,#6d6860);line-height:1.7;margin-bottom:1.1rem}
.fests-page .compact-page-head{align-items:flex-end}
@media (max-width:700px){.seo-topic-panel{border-radius:18px}.seo-topic-panel:after{width:120px;height:120px;right:-55px;top:-55px}}
@media (prefers-reduced-motion:reduce){.seo-topic-panel:after{display:none}}

/* V18 final product polish */
.visible-breadcrumbs{display:flex;align-items:center;gap:.55rem;max-width:1180px;margin:0 auto 1.1rem;padding:0 0;color:var(--muted,#716d65);font-size:.78rem;letter-spacing:.06em;text-transform:uppercase}
.visible-breadcrumbs a{color:inherit;text-decoration:none;border-bottom:1px solid transparent;transition:border-color .2s,color .2s}
.visible-breadcrumbs a:hover,.visible-breadcrumbs a:focus-visible{color:var(--text-primary);border-color:currentColor}
.visible-breadcrumbs span[aria-current="page"]{color:var(--text-primary);font-weight:700}
.seo-topic-links{display:flex;flex-wrap:wrap;gap:.65rem}
.seo-topic-links button{appearance:none;border:1px solid var(--line,rgba(0,0,0,.14));background:var(--bg-card,rgba(255,255,255,.5));color:var(--text-primary);border-radius:999px;padding:.7rem 1rem;font:inherit;font-weight:700;cursor:pointer;transition:transform .2s,border-color .2s,background .2s}
.seo-topic-links button:hover{transform:translateY(-2px);border-color:rgba(180,24,34,.35);background:var(--bg-primary,#fff)}
@media (max-width:900px){.visible-breadcrumbs{padding:0 1rem}}
@media (max-width:600px){.visible-breadcrumbs{font-size:.68rem;gap:.4rem;margin-bottom:.8rem;overflow:auto;white-space:nowrap}.seo-topic-links{gap:.5rem}.seo-topic-links button{padding:.62rem .82rem;font-size:.82rem}}


/* ===== v18-3-final-ui.css ===== */
/* JYC V18.3 — final UI simplification and interaction polish */

/* Brand: cleaner, more intentional JYC mark */
.brand-mark,.footer-logo-lockup{display:grid;place-items:center;position:relative;flex:0 0 auto}
.brand-mark{width:58px;height:58px;border-radius:50%;padding:3px;background:linear-gradient(145deg,color-mix(in srgb,var(--accent-gold) 88%,transparent),var(--bg-card));border:1px solid color-mix(in srgb,var(--accent-gold) 55%,var(--border-tech));box-shadow:0 0 0 5px color-mix(in srgb,var(--accent-gold) 5%,transparent),0 12px 35px color-mix(in srgb,var(--accent-red) 10%,transparent)}
.brand-mark img{width:100%!important;height:100%!important;border-radius:50%;display:block;object-fit:cover}
.brand:hover .brand-mark{border-color:var(--accent-red);box-shadow:0 0 0 6px color-mix(in srgb,var(--accent-red) 8%,transparent),0 15px 42px color-mix(in srgb,var(--accent-red) 12%,transparent)}

/* Desktop navigation is intentionally focused: More holds the utility layer. */
@media(min-width:1051px){
 .nav-inner{padding-right:0;gap:18px}
 .nav nav{margin-left:auto;margin-right:0}
 .nav nav button{padding:11px 13px}
 .nav-more-trigger{display:inline-flex!important;align-items:center;gap:4px}
 .theme-toggle{position:static;margin-left:4px;width:50px;height:50px;flex:0 0 auto}
 .search-trigger{margin-left:2px;min-width:145px;justify-content:center;cursor:pointer!important;pointer-events:auto!important}
}

/* More is a centered command panel on desktop, not a bottom sheet. */
.more-sheet-overlay{align-items:center!important;justify-content:center!important;padding:28px!important;cursor:default;pointer-events:auto}
.more-sheet{width:min(760px,calc(100vw - 56px))!important;max-height:min(82vh,760px);overflow:auto;margin:0!important;border-radius:30px!important;padding:18px 22px 22px!important;box-shadow:0 35px 120px rgba(0,0,0,.42),0 0 0 1px color-mix(in srgb,var(--accent-gold) 8%,transparent)!important}
.more-sheet .sheet-grabber{display:none}
.more-sheet-grid{grid-template-columns:repeat(3,1fr)!important}
.more-sheet-grid button,.more-sheet-link,.more-sheet-staff button{cursor:pointer!important;pointer-events:auto!important;transition:transform .25s var(--ease),border-color .25s,background .25s}
.more-sheet-grid button:hover,.more-sheet-link:hover,.more-sheet-staff button:hover{transform:translateY(-2px);border-color:var(--accent-gold);background:color-mix(in srgb,var(--bg-main) 84%,var(--accent-gold) 5%)}
.more-sheet-staff{border-top:1px solid var(--border-tech);margin-top:18px;padding-top:16px;display:grid;gap:8px}
.more-sheet-staff button{display:grid;gap:4px;text-align:left;border:1px solid color-mix(in srgb,var(--accent-red) 35%,var(--border-tech));background:color-mix(in srgb,var(--accent-red) 6%,var(--bg-main));color:var(--text-primary);border-radius:16px;padding:14px 16px}
.more-sheet-staff span{color:var(--text-muted);font-size:11px}

/* Search: always interactive, with a clearly clickable input and admin route. */
.search-overlay,.search-modal,.search-input-wrap,.search-input-wrap input{pointer-events:auto!important}
.search-overlay{cursor:default}
.search-input-wrap{cursor:text!important}
.search-input-wrap input{cursor:text!important;caret-color:var(--accent-red)!important;pointer-events:auto!important}
.search-clear,.search-close,.search-suggestions button,.search-recent button,.search-admin-tools button,.search-list button{cursor:pointer!important;pointer-events:auto!important}
.search-admin-tools{display:grid;gap:8px;margin-top:16px;padding-top:16px;border-top:1px solid var(--border-tech)}
.search-admin-tools>span{color:var(--accent-red);font:700 10px 'Space Grotesk';letter-spacing:.18em}
.search-admin-tools button{width:100%;display:grid;grid-template-columns:1fr auto;gap:3px;text-align:left;border:1px solid color-mix(in srgb,var(--accent-red) 28%,var(--border-tech));background:color-mix(in srgb,var(--accent-red) 5%,var(--bg-main));color:var(--text-primary);border-radius:14px;padding:13px 15px}
.search-admin-tools button small{grid-column:1;color:var(--text-muted)}
.search-admin-tools button strong{grid-column:2;grid-row:1/3;align-self:center;color:var(--accent-red)}

/* Phoenix: tighter stage, sharper bird, no dead air after the visual. */
.hero{min-height:clamp(620px,calc(100vh - 96px),760px)!important;padding-bottom:28px!important}
.hero-art{min-height:500px!important;height:500px}
.phoenix-3d-stage{width:min(640px,100%);height:500px!important;position:relative;display:grid;place-items:center;isolation:isolate;cursor:default}
.phoenix-3d-core{position:absolute;inset:0;display:grid;place-items:center;pointer-events:none}
.phoenix-artwork{width:min(510px,78%);display:grid;place-items:center;filter:drop-shadow(0 0 24px color-mix(in srgb,var(--accent-red) 24%,transparent)) drop-shadow(0 20px 45px rgba(0,0,0,.28));transition:filter .35s var(--ease),transform .35s var(--ease)}
.phoenix-artwork img{width:100%;height:auto;max-height:410px;object-fit:contain;image-rendering:auto;opacity:.96}
.phoenix-3d-core.is-focused .phoenix-artwork{filter:drop-shadow(0 0 34px color-mix(in srgb,var(--accent-red) 35%,transparent)) drop-shadow(0 24px 52px rgba(0,0,0,.32))}
.phoenix-node{cursor:pointer!important;pointer-events:auto!important;z-index:8;transition:transform .25s var(--ease),border-color .25s,background .25s}
.phoenix-node:hover,.phoenix-node.active{transform:translateY(-3px) scale(1.03);border-color:var(--accent-gold)!important;background:color-mix(in srgb,var(--bg-card) 90%,var(--accent-red) 8%)!important}
.phoenix-route-hint{z-index:6;pointer-events:none}
.reference-side-note{z-index:7}

/* Remove the large empty editorial area created by the old home layout. */
.home-layout{min-height:0!important}
.home .cta{width:min(760px,calc(100% - 32px));margin:24px auto 56px!important;padding:64px 28px!important;text-align:center;border:1px solid var(--border-tech);border-radius:28px;background:color-mix(in srgb,var(--bg-card) 82%,transparent);box-shadow:0 24px 70px rgba(0,0,0,.14)}
.home .cta h2{max-width:620px;margin:12px auto 14px;font-size:clamp(38px,5vw,64px)!important;line-height:.98}
.home .cta p{max-width:560px;margin:0 auto 24px;color:var(--text-muted);line-height:1.65}
.home .cta .btn{margin:auto}

/* My JYC is now the home for the agenda. */
.my-jyc-agenda-panel{border:1px solid var(--border-tech);background:var(--bg-card);border-radius:24px;padding:24px;margin:24px 0;box-shadow:0 18px 55px rgba(0,0,0,.08)}
.my-jyc-agenda-list{display:grid;gap:8px;margin-top:14px}
.my-jyc-agenda-list button{display:grid;grid-template-columns:120px 1fr auto;gap:12px;align-items:center;text-align:left;border:1px solid var(--border-tech);background:var(--bg-main);color:var(--text-primary);border-radius:14px;padding:13px 15px;cursor:pointer;transition:.25s var(--ease)}
.my-jyc-agenda-list button:hover{border-color:var(--accent-gold);transform:translateX(3px)}
.my-jyc-agenda-list span,.my-jyc-agenda-list small{color:var(--text-muted);font-size:11px}
.my-jyc-agenda-list strong{font:600 15px 'Space Grotesk'}

/* Guide: practical student-tool layer. */
.guide-tools-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}
.guide-tool-card{border:1px solid var(--border-tech);background:var(--bg-card);border-radius:22px;padding:24px;display:flex;flex-direction:column;min-height:250px}
.guide-tool-card h2{font:700 28px 'Space Grotesk';margin:10px 0}
.guide-tool-card p{color:var(--text-muted);line-height:1.65;flex:1}
.guide-tool-card a{display:inline-flex;align-self:flex-start;border:1px solid var(--border-tech);border-radius:999px;padding:10px 13px;font-weight:700;cursor:pointer;transition:.25s var(--ease)}
.guide-tool-card a:hover{border-color:var(--accent-gold);transform:translateY(-2px)}
