/* ===== v13-4-reference.css ===== */
/* V13.4 reference UI — intentionally loaded last so the visual system wins over legacy patches. */
:root{
  --jyc-red:#ff2934;
  --jyc-red-deep:#c71925;
  --jyc-cream:#fff6df;
  --jyc-ink:#08090b;
  --jyc-line:color-mix(in srgb,var(--accent-gold) 24%,var(--border-tech));
  --jyc-radius:20px;
}
html{scroll-behavior:smooth}
body{overflow-x:hidden}
button,a,input,select,textarea{font-family:inherit}

/* Brand: the reference uses the red phoenix mark as the primary identity, not a circular badge. */
.brand img,.admin-brand img,.footer-logo-lockup img,.quote-card img,.loading-logo img,.detail-logo img,.club-logo img,.fest-logo-wrap img{object-fit:contain;object-position:center}
.brand img{width:39px!important;height:39px!important;padding:0!important;border-radius:0!important;background:transparent!important;filter:drop-shadow(0 7px 13px color-mix(in srgb,var(--accent-red) 18%,transparent))}
.brand{gap:11px!important}
.brand span{font-size:12px!important;letter-spacing:.01em!important}

/* Desktop reference header: compact, pill-like, calm and content-first. */
.nav{height:72px!important;position:sticky!important;top:0!important;z-index:1500!important;background:color-mix(in srgb,var(--bg-main) 88%,transparent)!important;border-bottom:1px solid color-mix(in srgb,var(--accent-gold) 17%,transparent)!important;backdrop-filter:blur(22px) saturate(130%)!important;-webkit-backdrop-filter:blur(22px) saturate(130%)!important}
.nav-inner{height:72px!important;min-height:72px!important;width:min(1380px,calc(100% - 42px))!important;gap:12px!important}
.nav nav{margin-left:auto!important;gap:1px!important}
.nav nav button{font-size:11px!important;padding:10px 11px!important;border-radius:999px!important;color:var(--text-muted)!important}
.nav nav button:hover{color:var(--text-primary)!important;background:color-mix(in srgb,var(--bg-card) 55%,transparent)!important}
.nav nav button.active{color:var(--accent-red)!important;background:transparent!important}
.nav nav button.active:after{height:2px!important;width:24px!important;left:50%!important;transform:translateX(-50%)!important;bottom:4px!important;border-radius:10px!important;background:var(--accent-red)!important}
.admin-nav{margin-left:4px!important;color:var(--accent-red)!important}
.search-trigger{width:140px!important;min-width:140px!important;height:40px!important;border-radius:999px!important;border:1px solid var(--jyc-line)!important;background:color-mix(in srgb,var(--bg-card) 62%,transparent)!important;color:var(--text-muted)!important;justify-content:flex-start!important;padding:0 12px!important;font-size:11px!important;gap:7px!important}
.search-trigger span{display:inline!important}.search-trigger kbd{display:none!important}
.theme-toggle{position:static!important;width:40px!important;height:40px!important;flex:0 0 40px!important;border-radius:50%!important;border:1px solid var(--jyc-line)!important;background:color-mix(in srgb,var(--bg-card) 64%,transparent)!important;box-shadow:none!important}
.hamb{display:none!important}

/* Hero: match the supplied desktop composition without turning it into a poster. */
.hero{width:min(1380px,calc(100% - 42px))!important;margin:0 auto!important;min-height:calc(100dvh - 72px)!important;grid-template-columns:minmax(0,1.05fr) minmax(420px,.95fr)!important;gap:14px!important;padding:58px 0 34px!important}
.hero-copy{padding:18px 0 0!important;max-width:700px!important}
.hero-copy h1{font-size:clamp(58px,7.4vw,108px)!important;line-height:.88!important;letter-spacing:-.065em!important;max-width:760px!important}
.hero-copy .eyebrow{font-size:10px!important;letter-spacing:.22em!important;color:var(--accent-red)!important}
.hero-rule{width:100px!important;height:3px!important;margin:25px 0 22px!important;background:var(--accent-red)!important}
.hero-copy h4{font-size:15px!important;letter-spacing:.23em!important;margin:0 0 20px!important}
.hero-copy>p{max-width:650px!important;font-size:17px!important;line-height:1.55!important;color:var(--text-muted)!important}
.hero-actions{margin-top:25px!important;display:flex!important;gap:10px!important;max-width:610px!important}
.hero-actions .btn{min-height:48px!important;border-radius:999px!important;padding:0 24px!important}
.hero-actions .btn:first-child{box-shadow:0 10px 32px color-mix(in srgb,var(--accent-red) 18%,transparent)!important}
.hero-stats{max-width:620px!important;margin-top:34px!important;border-top:1px solid var(--jyc-line)!important;padding-top:16px!important}
.hero-stats>div{padding:0 18px!important;border-right:1px solid var(--jyc-line)!important}
.hero-stats>div:first-child{padding-left:0!important}
.hero-stats strong{font-size:22px!important}
.hero-stats span{font-size:9px!important;letter-spacing:.13em!important}
.hero-quick{display:none!important}
.hero-art{min-height:590px!important;height:100%!important;background:transparent!important;border:0!important;overflow:visible!important;position:relative!important}
.hero-art:before{width:590px!important;height:590px!important;opacity:.9!important;background:radial-gradient(circle,color-mix(in srgb,var(--accent-red) 13%,transparent),transparent 65%)!important}
.logo-core{width:330px!important;height:330px!important;border:0!important;background:transparent!important;box-shadow:none!important;position:absolute!important;left:50%!important;top:50%!important;transform:translate(-50%,-50%)!important;animation:referenceLogoFloat 7s ease-in-out infinite!important}
.logo-core:before{content:"";position:absolute;inset:-42px;border:1px solid color-mix(in srgb,var(--accent-red) 28%,transparent);border-radius:50%;animation:referenceOrbit 24s linear infinite}
.logo-core:after{content:"";position:absolute;inset:-85px;border:1px solid color-mix(in srgb,var(--accent-gold) 12%,transparent);border-radius:50%;transform:rotate(-18deg);animation:referenceOrbit 34s linear infinite reverse}
.logo-core img{width:77%!important;height:77%!important;filter:drop-shadow(0 0 20px color-mix(in srgb,var(--accent-red) 30%,transparent)) drop-shadow(0 22px 38px color-mix(in srgb,var(--accent-red) 12%,transparent))!important}
.logo-core span{bottom:-42px!important;color:var(--accent-red)!important;font-size:9px!important;letter-spacing:.3em!important}
.orbit{opacity:.28!important;border-color:color-mix(in srgb,var(--accent-red) 32%,transparent)!important}
.o1{width:570px!important;height:570px!important}.o2{width:690px!important;height:360px!important}.o3{width:460px!important;height:690px!important}
.float-chip{border-color:var(--jyc-line)!important;background:color-mix(in srgb,var(--bg-card) 66%,transparent)!important;backdrop-filter:blur(10px)!important;font-size:8px!important}

/* Light mode: warm cream reference, never pure white glare. */
:root[data-theme="light"] body{background:#f7f1e4!important}
:root[data-theme="light"] .nav{background:rgba(249,244,234,.9)!important}
:root[data-theme="light"] .hero{background:transparent!important}
:root[data-theme="light"] .hero-art:before{background:radial-gradient(circle,rgba(255,220,139,.35),transparent 65%)!important}
