:root[data-theme="light"] .orbit{border-color:rgba(196,126,40,.24)!important}
:root[data-theme="light"] .mobile-dock{background:rgba(255,250,240,.9)!important;border-color:rgba(175,132,69,.3)!important}

/* Dark mode: deep black, red phoenix, low-noise atmosphere. */
:root[data-theme="dark"] body{background:#08090b!important}
:root[data-theme="dark"] .hero:after{content:"";position:absolute;left:50%;right:0;top:72px;height:1px;background:linear-gradient(90deg,transparent,rgba(255,40,50,.24),transparent);pointer-events:none}
:root[data-theme="dark"] .nav{background:rgba(8,9,11,.88)!important}

