/* ===== v13-5-reference-match.css ===== */
/* V13.5 — reference match pass
   Goal: reproduce the supplied JIIT Youth Club composition more closely while
   preserving the existing CMS/data model and responsive behavior. */
:root{
  --jyc-reference-red:#ff2634;
  --jyc-reference-red-dark:#c91422;
  --jyc-reference-cream:#f8f0df;
  --jyc-reference-black:#07090b;
  --jyc-reference-muted:#a9a7aa;
  --jyc-reference-line:rgba(255,255,255,.16);
}

/* ---------- shared chrome ---------- */
.nav-inner{width:min(1330px,calc(100% - 40px))!important}
.brand img{
  width:38px!important;height:38px!important;padding:7px!important;
  border-radius:50%!important;
  background:var(--jyc-reference-cream)!important;
  border:1px solid rgba(255,255,255,.5)!important;
  filter:drop-shadow(0 4px 12px rgba(255,38,52,.16))!important;
}
.brand span{font-size:11px!important;font-weight:700!important;letter-spacing:.01em!important}
.nav{box-shadow:0 8px 28px rgba(0,0,0,.08)!important}
.nav nav button{font-size:10px!important;letter-spacing:-.01em!important}
.search-trigger{height:38px!important;min-width:150px!important;width:150px!important}
.theme-toggle{width:38px!important;height:38px!important;flex-basis:38px!important}

/* ---------- hero: desktop reference composition ---------- */
.hero{
  width:min(1330px,calc(100% - 40px))!important;
  min-height:650px!important;
  height:calc(100svh - 72px)!important;
  max-height:720px!important;
  grid-template-columns:minmax(0,.98fr) minmax(510px,1.02fr)!important;
  gap:0!important;
  padding:26px 0 20px!important;
  align-items:center!important;
}
.hero-copy{padding:20px 0 0!important;max-width:650px!important;z-index:3}
.hero-copy .eyebrow{font-size:10px!important;letter-spacing:.20em!important;font-weight:800!important}
.hero-copy h1{
  font-size:clamp(62px,6.3vw,94px)!important;
  line-height:.86!important;
  letter-spacing:-.068em!important;
  margin:18px 0 10px!important;
  max-width:720px!important;
}
.hero-rule{width:72px!important;height:2px!important;margin:0 0 16px!important}
.hero-copy h4{font-size:13px!important;letter-spacing:.34em!important;margin:0 0 16px!important}
.hero-copy>p{font-size:14px!important;line-height:1.55!important;max-width:570px!important}
.hero-actions{margin-top:20px!important;gap:9px!important}
.hero-actions .btn{min-height:43px!important;padding:0 21px!important;font-size:11px!important}
.hero-stats{max-width:575px!important;margin-top:28px!important;padding-top:13px!important;border-top:1px solid var(--jyc-line)!important}
.hero-stats>div{padding:0 17px!important}
.hero-stats strong{font-size:19px!important;line-height:1!important}
.hero-stats span{font-size:8px!important;letter-spacing:.10em!important;text-transform:uppercase!important}

.hero-art{
  min-height:600px!important;height:100%!important;overflow:visible!important;
  isolation:isolate!important;
}
.hero-art:before{
  width:570px!important;height:570px!important;
  background:
    radial-gradient(circle at 50% 50%,rgba(255,40,52,.24),transparent 49%),
    radial-gradient(circle at 50% 50%,rgba(255,210,150,.08),transparent 67%)!important;
  filter:blur(.2px)!important;
}
/* Network-like points/lines behind the phoenix, using CSS only. */
.hero-art:after{
  content:""!important;position:absolute!important;inset:5% 3%!important;z-index:-1!important;
  background:
    radial-gradient(circle at 16% 22%,rgba(255,48,62,.95) 0 2px,transparent 3px),
    radial-gradient(circle at 73% 14%,rgba(255,48,62,.95) 0 2px,transparent 3px),
    radial-gradient(circle at 86% 40%,rgba(255,48,62,.85) 0 2px,transparent 3px),
    radial-gradient(circle at 24% 71%,rgba(255,48,62,.75) 0 2px,transparent 3px),
    radial-gradient(circle at 63% 83%,rgba(255,48,62,.8) 0 2px,transparent 3px),
    radial-gradient(circle at 48% 36%,rgba(255,255,255,.7) 0 1px,transparent 2px),
    repeating-radial-gradient(ellipse at 52% 50%,transparent 0 74px,rgba(255,38,52,.16) 75px 76px,transparent 77px 104px);
  opacity:.95!important;pointer-events:none!important;
  -webkit-mask-image:radial-gradient(circle at center,#000 0 58%,transparent 87%);
  mask-image:radial-gradient(circle at center,#000 0 58%,transparent 87%);
}
.logo-core{
  width:300px!important;height:300px!important;
  left:50%!important;top:50%!important;
  background:transparent!important;border:0!important;box-shadow:none!important;
  z-index:3!important;
}
.logo-core:before{inset:-48px!important;border-color:rgba(255,39,52,.42)!important}
.logo-core:after{inset:-92px!important;border-color:rgba(255,192,116,.18)!important}
.logo-core img{
  width:82%!important;height:82%!important;
  filter:drop-shadow(0 0 18px rgba(255,39,52,.42)) drop-shadow(0 18px 38px rgba(255,39,52,.18))!important;
}
.logo-core span{bottom:-37px!important;font-size:8px!important;letter-spacing:.34em!important}
.orbit{opacity:.45!important;border-color:rgba(255,44,55,.38)!important}
.o1{width:520px!important;height:520px!important}
.o2{width:670px!important;height:340px!important}
.o3{width:440px!important;height:650px!important}
.float-chip{font-size:8px!important;letter-spacing:.13em!important;padding:8px 11px!important;background:rgba(8,9,11,.52)!important}
.chip1{top:17%!important;left:5%!important}
.chip2{right:3%!important;bottom:15%!important}

/* New right-side reference annotation. */
.hero-art .reference-side-note{
  position:absolute;right:-2px;top:39%;z-index:5;
  display:grid;gap:7px;width:128px;padding-left:12px;
  border-left:2px solid var(--jyc-reference-red);
  font:700 8px/1.45 'Space Grotesk',sans-serif;
  letter-spacing:.05em;text-transform:uppercase;color:var(--text-primary);
}
.hero-art .reference-side-note span{display:block}
.hero-art .reference-campus-badge{
  position:absolute;right:1%;bottom:11%;z-index:5;
  padding:7px 11px;border:1px solid var(--jyc-line);border-radius:999px;
  background:color-mix(in srgb,var(--bg-card) 72%,transparent);
  font:700 8px 'Space Grotesk';letter-spacing:.08em;
}

/* ---------- What's Next: match the compact horizontal reference strip ---------- */
.home-events{width:min(1330px,calc(100% - 40px))!important;padding:0 0 32px!important;margin:0 auto!important}
.home-events .section-head{display:flex!important;align-items:flex-end!important;justify-content:space-between!important;gap:20px!important;margin:0 0 13px!important;max-width:none!important}
