/* ===== v13-6-open-source-ui.css ===== */
/* V13.6 — reference fidelity + open-source UI patterns
   Inspired by the composition and interaction principles of shadcn/ui,
   Radix primitives and Motion. No third-party runtime dependency is required. */
:root{
  --jyc-red:#ff1f32;
  --jyc-red-soft:rgba(255,31,50,.12);
  --jyc-ink:#07090b;
  --jyc-cream:#faf3e5;
  --jyc-border:color-mix(in srgb,var(--border-tech) 88%,transparent);
  --jyc-shadow:0 20px 70px rgba(0,0,0,.12);
}

/* predictable focus + selection states */
:where(button,a,input,select,textarea):focus-visible{
  outline:2px solid var(--jyc-red)!important;
  outline-offset:3px!important;
}
::selection{background:var(--jyc-red);color:#fff}
html{scroll-behavior:smooth}
body{overflow-x:hidden}

/* ---------- exact reference desktop shell ---------- */
.nav-inner{width:min(1180px,calc(100% - 42px))!important;gap:8px!important}
.nav{height:70px!important}
.brand{gap:9px!important}
.brand img{width:36px!important;height:36px!important;padding:6px!important}
.brand span{font-size:10px!important;letter-spacing:.02em!important;white-space:nowrap}
.nav nav{gap:0!important}
.nav nav button{padding:9px 10px!important;font-size:9px!important}
.search-trigger{width:146px!important;min-width:146px!important;height:36px!important;border-radius:999px!important;font-size:10px!important}
.search-trigger kbd{font-size:7px!important}
.theme-toggle{width:36px!important;height:36px!important}

/* ---------- hero ---------- */
.hero{
  width:min(1180px,calc(100% - 42px))!important;
  min-height:565px!important;
  height:calc(100svh - 70px)!important;
  max-height:650px!important;
  grid-template-columns:minmax(0,46%) minmax(0,54%)!important;
  padding:22px 0 8px!important;
}
.hero-copy{max-width:570px!important;padding-top:0!important}
.hero-copy .eyebrow{color:var(--accent-red)!important;font-size:9px!important;letter-spacing:.17em!important}
.hero-copy h1{font-size:clamp(52px,5.1vw,78px)!important;line-height:.9!important;letter-spacing:-.065em!important;margin:15px 0 8px!important}
.hero-rule{width:52px!important;height:2px!important;margin:0 0 12px!important;background:var(--jyc-red)!important}
