.hero-art{min-height:540px!important;height:100%!important;transform:translateX(2%)!important}
.hero-art:before{width:500px!important;height:500px!important;background:radial-gradient(circle,rgba(255,31,50,.2),transparent 58%)!important}
.hero-art:after{
  inset:3% 0!important;
  background:
   radial-gradient(circle at 18% 19%,#ff3044 0 2px,transparent 3px),
   radial-gradient(circle at 74% 13%,#ff3044 0 2px,transparent 3px),
   radial-gradient(circle at 86% 48%,#ff3044 0 2px,transparent 3px),
   radial-gradient(circle at 30% 77%,#ff3044 0 2px,transparent 3px),
   radial-gradient(circle at 64% 85%,#ff3044 0 2px,transparent 3px),
   repeating-radial-gradient(ellipse at 51% 50%,transparent 0 66px,rgba(255,31,50,.16) 67px 68px,transparent 69px 102px)!important;
  opacity:.95!important;
}
.logo-core{width:270px!important;height:270px!important}
