.o1{width:470px!important;height:470px!important}
.o2{width:600px!important;height:305px!important}
.o3{width:390px!important;height:560px!important}
.hero-art .reference-side-note{right:0!important;top:37%!important;width:105px!important;font-size:7px!important;gap:6px!important}
.hero-art .reference-campus-badge{right:2%!important;bottom:10%!important;font-size:7px!important}
.float-chip{font-size:7px!important;padding:7px 9px!important}

/* ---------- What's Next: three reference cards ---------- */
.home-events{width:min(1180px,calc(100% - 42px))!important;padding:0 0 30px!important}
.reference-section-head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:13px}
.reference-section-head .eyebrow{display:none}
.reference-section-head h2{font-size:24px!important;line-height:1!important;letter-spacing:-.045em!important;margin:0 0 3px!important}
.reference-section-head p{font-size:10px!important;color:var(--text-muted)!important;margin:0!important}
.reference-view-all{border:1px solid var(--jyc-border);background:transparent;color:var(--text-primary);border-radius:999px;padding:9px 14px;font:700 9px 'Space Grotesk';white-space:nowrap}
.reference-view-all:hover{border-color:var(--jyc-red);color:var(--jyc-red)}
.reference-event-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}
.reference-event-grid .event-card-premium{
  display:grid!important;grid-template-columns:84px minmax(0,1fr)!important;
  min-height:88px!important;height:88px!important;border-radius:11px!important;
  border:1px solid var(--jyc-border)!important;background:color-mix(in srgb,var(--bg-card) 55%,transparent)!important;
