.reference-event-grid .event-poster:after{background:linear-gradient(180deg,transparent 35%,rgba(0,0,0,.38))!important}
.reference-event-grid .event-poster>span:first-child{font-size:7px!important;top:7px!important;left:7px!important;padding:4px 5px!important;border-radius:5px!important}
.reference-event-grid .event-card-tools{display:none!important}
.reference-event-grid .event-number{display:none!important}
.reference-event-grid .card-body{padding:10px 11px!important;display:flex!important;flex-direction:column!important;justify-content:center!important;min-width:0!important}
.reference-event-grid .card-topline{font-size:7px!important;margin-bottom:3px!important}
.reference-event-grid .card-body h3{font:700 12px/1.1 'Space Grotesk'!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;margin:0 0 4px!important}
.reference-event-grid .card-body p{display:none!important}
.reference-event-grid .event-card-meta{display:none!important}
.reference-event-grid .card-body .text-link{font-size:8px!important;color:var(--text-muted)!important}

/* ---------- public feature pages ---------- */
.section.page{width:min(1180px,calc(100% - 42px))!important}
.compact-page-head{border-bottom:1px solid var(--jyc-border)!important;padding-bottom:22px!important;margin-bottom:18px!important}
.compact-page-head h1{letter-spacing:-.055em!important}
.discover-panel{border:1px solid var(--jyc-border)!important;background:color-mix(in srgb,var(--bg-card) 65%,transparent)!important;border-radius:18px!important;box-shadow:none!important}
.club-grid-premium{gap:12px!important}
.club-card-premium,.event-card-premium{border-radius:16px!important;border-color:var(--jyc-border)!important;box-shadow:0 10px 35px rgba(0,0,0,.07)!important}
.club-card-premium:hover,.event-card-premium:hover{border-color:color-mix(in srgb,var(--jyc-red) 35%,var(--jyc-border))!important}
.club-card-visual,.event-card-premium .event-poster{border-radius:0!important}
.gallery-item{border-radius:13px!important;overflow:hidden!important}
.gallery-item img{transition:transform .35s ease,filter .35s ease!important}
