.team-card,.contact-card,.feature-card{border-color:var(--jyc-border)!important;box-shadow:0 10px 35px rgba(0,0,0,.06)!important}

/* ---------- admin: shadcn-style grouped sidebar + command surface ---------- */
.admin-shell{grid-template-columns:258px minmax(0,1fr)!important}
.admin-side{width:258px!important;min-width:258px!important;padding:13px 10px 12px!important;background:linear-gradient(180deg,color-mix(in srgb,var(--bg-card) 96%,transparent),var(--bg-main))!important}
.admin-brand{padding:9px!important;border-radius:13px!important}
.admin-user{margin:7px 3px 12px!important;padding:10px!important;border-radius:13px!important;background:color-mix(in srgb,var(--bg-card) 70%,transparent)!important;border:1px solid var(--jyc-border)!important}
.admin-nav-group{margin:8px 0!important}
.admin-nav-group>span{font-size:7px!important;letter-spacing:.14em!important;opacity:.55!important;padding:4px 10px!important}
.admin-nav-group button{min-height:36px!important;border-radius:9px!important;padding:7px 9px!important}
.admin-nav-group button:hover{background:color-mix(in srgb,var(--jyc-red) 7%,transparent)!important}
.admin-nav-group button.active{background:linear-gradient(90deg,color-mix(in srgb,var(--jyc-red) 18%,transparent),transparent)!important;color:var(--jyc-red)!important}
.admin-nav-icon{font-size:14px!important}
.admin-main{min-width:0!important}
.admin-top{padding:14px 22px!important;min-height:76px!important}
