.admin-content{padding:18px 22px 40px!important}
.admin-guide{border-radius:15px!important;box-shadow:0 10px 40px rgba(0,0,0,.08)!important}
.admin-command-overlay{backdrop-filter:blur(8px)!important;background:rgba(0,0,0,.38)!important}
.admin-command{width:min(620px,calc(100% - 28px))!important;border-radius:18px!important;box-shadow:0 30px 100px rgba(0,0,0,.42)!important;border:1px solid var(--jyc-border)!important}
.admin-command-search{border-radius:11px!important}
.admin-command-list button{border-radius:10px!important;margin:2px 0!important}

/* ---------- More sheet follows open-source Sheet/Drawer conventions ---------- */
.more-sheet-overlay{backdrop-filter:blur(6px)!important;-webkit-backdrop-filter:blur(6px)!important}
.more-sheet{border-left:1px solid var(--jyc-border)!important}
.more-sheet-grid button{transition:background .18s ease,transform .18s ease!important}
.more-sheet-grid button:hover{transform:translateX(2px)!important;background:color-mix(in srgb,var(--jyc-red) 8%,var(--bg-card))!important}

/* ---------- footer reference band ---------- */
.footer-reference-features{width:min(1180px,calc(100% - 42px))!important;margin:0 auto!important;padding:15px 0!important;background:transparent!important;border-top:0!important;border-bottom:0!important}
.footer-reference-features span{font-size:8px!important;letter-spacing:.1em!important}
.jyc-footer{border-top:1px solid var(--jyc-border)!important}
.footer-top{width:min(1180px,calc(100% - 42px))!important}
.footer-bottom{width:min(1180px,calc(100% - 42px))!important}

/* ---------- light/dark exact surfaces ---------- */
:root[data-theme="light"] body{background:var(--jyc-cream)!important}
:root[data-theme="light"] .hero,
:root[data-theme="light"] .home-events{background:transparent!important}
:root[data-theme="light"] .hero-art:before{background:radial-gradient(circle,rgba(255,31,50,.12),transparent 59%)!important}
:root[data-theme="light"] .reference-event-grid .event-card-premium{background:rgba(255,252,245,.62)!important}
:root[data-theme="light"] .admin-side{background:#fbf5e9!important}
:root[data-theme="dark"] .reference-event-grid .event-card-premium{background:rgba(8,10,12,.58)!important}

/* ---------- mobile: reference phone composition ---------- */
