/* ===== v13-8-orbit-product.css ===== */
/* V13.8 — animated reference atmosphere + product polish
   Uses open-source UI interaction principles without adding a runtime dependency. */

/* The supplied reference uses a living orbital system. Make every ring visibly travel. */
.hero-art .orbit{
  transform-origin:50% 50%;
  will-change:transform;
  border-style:solid!important;
  box-shadow:0 0 28px rgba(255,31,50,.035);
}
.hero-art .orbit::after{
  content:"";
  position:absolute;
  width:7px;
  height:7px;
  left:50%;
  top:-4px;
  margin-left:-3.5px;
  border-radius:50%;
  background:var(--jyc-red);
  box-shadow:0 0 0 4px rgba(255,31,50,.09),0 0 18px rgba(255,31,50,.65);
}
.hero-art .o1{animation:jycOrbitTravelA 18s linear infinite!important}
.hero-art .o2{animation:jycOrbitTravelB 25s linear infinite!important}
.hero-art .o3{animation:jycOrbitTravelC 32s linear infinite!important}
.hero-art .o2::after{width:5px;height:5px;top:auto;bottom:-3px;left:21%;box-shadow:0 0 0 3px rgba(255,31,50,.08),0 0 14px rgba(255,31,50,.55)}
.hero-art .o3::after{width:6px;height:6px;top:27%;left:auto;right:-3px;box-shadow:0 0 0 3px rgba(255,31,50,.08),0 0 15px rgba(255,31,50,.55)}
@keyframes jycOrbitTravelA{from{transform:rotate(-20deg)}to{transform:rotate(340deg)}}
@keyframes jycOrbitTravelB{from{transform:rotate(26deg)}to{transform:rotate(-334deg)}}
@keyframes jycOrbitTravelC{from{transform:rotate(-34deg)}to{transform:rotate(326deg)}}

/* Fine-grain star motion makes the hero feel less like a static poster. */
.hero-art .sky-stars{animation:jycStarDrift 16s ease-in-out infinite alternate}
@keyframes jycStarDrift{from{transform:translate3d(-4px,-3px,0);opacity:.72}to{transform:translate3d(5px,4px,0);opacity:1}}
.hero-art:after{animation:jycNetworkDrift 22s ease-in-out infinite alternate!important}
@keyframes jycNetworkDrift{from{transform:scale(1) rotate(-1deg);opacity:.72}to{transform:scale(1.018) rotate(1.2deg);opacity:1}}

/* Pointer depth on capable devices. Values are populated by the Home component. */
@media (hover:hover) and (pointer:fine){
  .home .hero-art .logo-core{transition:transform .18s ease-out!important}
  .home .hero-art .orbit{transition:filter .2s ease-out}
  .home .hero-art:hover .orbit{filter:drop-shadow(0 0 10px rgba(255,31,50,.06))}
}

/* Next-moment countdown: compact enough to sit between the pulse and reference sections. */
.next-moment-strip{
  width:min(1180px,calc(100% - 42px));
  margin:0 auto 18px;
  display:grid;
  grid-template-columns:minmax(0,1fr) auto auto;
  gap:16px;
  align-items:center;
  padding:12px 14px;
  border:1px solid var(--jyc-border);
  border-radius:14px;
  background:linear-gradient(90deg,color-mix(in srgb,var(--jyc-red) 7%,var(--bg-card)),color-mix(in srgb,var(--bg-card) 82%,transparent));
  box-shadow:0 12px 38px rgba(0,0,0,.06);
}
.next-moment-copy{min-width:0;display:flex;align-items:center;gap:10px}
.next-moment-live{width:7px;height:7px;flex:0 0 7px;border-radius:50%;background:var(--jyc-red);box-shadow:0 0 0 5px color-mix(in srgb,var(--jyc-red) 10%,transparent),0 0 16px color-mix(in srgb,var(--jyc-red) 38%,transparent);animation:jycLiveDot 1.6s ease-in-out infinite}
@keyframes jycLiveDot{50%{transform:scale(.72);opacity:.55}}
.next-moment-copy strong{display:block;font:700 10px 'Space Grotesk';letter-spacing:.08em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.next-moment-copy span{display:block;color:var(--text-muted);font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.next-moment-countdown{display:flex;gap:6px}
.next-moment-countdown b{min-width:34px;padding:6px 7px;text-align:center;border:1px solid var(--jyc-border);border-radius:8px;background:color-mix(in srgb,var(--bg-card) 75%,transparent);font:700 11px 'Space Grotesk'}
.next-moment-countdown small{display:block;margin-top:1px;color:var(--text-muted);font-size:6px;letter-spacing:.08em;text-transform:uppercase}
.next-moment-action{border:1px solid var(--jyc-border);background:transparent;color:var(--text-primary);border-radius:999px;padding:7px 11px;font:700 8px 'Space Grotesk';cursor:pointer;white-space:nowrap;transition:.2s ease}
.next-moment-action:hover{border-color:var(--jyc-red);color:var(--jyc-red);transform:translateY(-1px)}

/* Share control follows accessible dialog/share patterns: small, predictable, keyboard reachable. */
.share-btn{border:1px solid var(--jyc-border);background:transparent;color:var(--text-primary);border-radius:999px;padding:10px 13px;font:700 9px 'Space Grotesk';cursor:pointer;transition:.2s ease}
