.share-btn.copied{border-color:#35b86f;color:#35b86f}

/* Slightly stronger reference framing for page headers and cards. */
.compact-page-head,.reference-section-head{letter-spacing:-.01em}
.reference-section-head h2,.compact-page-head h1{max-width:720px}

@media(max-width:700px){
  .next-moment-strip{width:calc(100% - 22px);grid-template-columns:1fr auto;margin-bottom:12px;padding:10px}
  .next-moment-countdown{grid-column:1/-1;order:3}
  .next-moment-action{justify-self:end}
  .next-moment-countdown b{min-width:31px}
  .share-btn{padding:8px 11px;font-size:8px}
}

@media(prefers-reduced-motion:reduce){
  .hero-art .orbit,.hero-art .sky-stars,.hero-art:after,.next-moment-live{animation:none!important}
  .home .hero-art .logo-core{transition:none!important}
