/* ===== v14-6-ui-overhaul.css ===== */
/* JYC V14.6 — reference-matched visual system + navigation + hero correction. */
:root{
  --jyc-red:#e21d2b;
  --jyc-red-deep:#a91620;
  --jyc-gold:#c9a86a;
  --jyc-cream:#f4ead6;
  --jyc-ink:#090a0c;
  --jyc-glass:rgba(18,17,20,.72);
}

/* Navigation: six primary destinations + one predictable More menu. */
.nav{z-index:120!important;isolation:isolate}
.nav-inner{height:78px!important;width:min(1460px,calc(100% - 40px))!important;padding-right:0!important;gap:14px!important}
.brand{min-width:190px!important}
.brand img{width:48px!important;height:48px!important;padding:2px!important;background:var(--bg-card)!important;border:1px solid color-mix(in srgb,var(--accent-gold) 45%,var(--border-tech))!important;box-shadow:0 8px 24px color-mix(in srgb,var(--accent-gold) 10%,transparent)!important}
.brand span{font-size:14px!important;letter-spacing:.06em!important;text-transform:uppercase!important;white-space:nowrap!important}
.nav nav{gap:3px!important}
.nav nav button{padding:9px 12px!important;font-size:12px!important;letter-spacing:.02em!important}
.nav nav button.active{color:var(--text-primary)!important;background:color-mix(in srgb,var(--accent-red) 7%,transparent)!important}
.nav-more-trigger span{font-size:12px;display:inline-block;transition:transform .25s ease}.nav-more-trigger.active span{transform:rotate(180deg)}
.search-trigger{min-height:40px!important;padding:9px 12px!important;white-space:nowrap!important}

/* The More sheet is now a desktop popover too. */
.more-sheet-overlay{z-index:160!important;align-items:flex-start!important;padding:82px 20px 24px!important;background:transparent!important;backdrop-filter:none!important}
.more-sheet-overlay:before{content:"";position:fixed;inset:0;background:rgba(0,0,0,.18);backdrop-filter:blur(3px);z-index:-1}
.more-sheet{width:min(760px,calc(100vw - 32px))!important;margin-left:auto;margin-right:max(20px,calc((100vw - 1460px)/2))!important;border-radius:24px!important;border:1px solid color-mix(in srgb,var(--accent-gold) 30%,var(--border-tech))!important;box-shadow:0 30px 100px rgba(0,0,0,.28)!important;max-height:min(78vh,720px)!important;overflow:auto!important;background:color-mix(in srgb,var(--bg-card) 96%,transparent)!important;backdrop-filter:blur(26px)!important}
.more-sheet-head{padding:22px 22px 12px!important}.more-sheet-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important;padding:8px 22px 20px!important}.more-sheet-grid button,.more-sheet-link{min-height:74px!important;border-radius:16px!important;transition:transform .25s ease,border-color .25s ease,background .25s ease!important}.more-sheet-grid button:hover,.more-sheet-link:hover{transform:translateY(-2px)!important;border-color:var(--accent-gold)!important;background:color-mix(in srgb,var(--accent-gold) 7%,var(--bg-main))!important}

/* Hero is intentionally asymmetric: story on the left, brand mark on the right. */
.hero{min-height:clamp(650px,calc(100svh - 78px),900px)!important;width:min(1460px,calc(100% - 40px))!important;grid-template-columns:minmax(0,1.02fr) minmax(430px,.98fr)!important;gap:34px!important;overflow:clip!important}
.hero-copy{padding:54px 0 68px!important;max-width:700px!important}
.hero .eyebrow{font-size:10px!important;letter-spacing:.24em!important}
.hero h1{font-size:clamp(68px,8vw,126px)!important;line-height:.86!important;max-width:690px!important;margin:27px 0 22px!important;text-wrap:balance!important}
.hero h4{font-size:13px!important;letter-spacing:.28em!important;color:var(--text-primary)!important}
.hero-copy>p{font-size:16px!important;line-height:1.65!important;max-width:600px!important}
.hero-actions{margin-top:25px!important}
.hero-actions .btn{min-height:48px!important;border-radius:999px!important;padding:0 18px!important}
.hero-art{min-height:560px!important;overflow:visible!important;contain:layout paint!important}

/* Fix the reference logo: use the phoenix artwork as a contained mark and crop the baked-in title text. */
.phoenix-3d-stage{inset:4% 0 0!important;overflow:visible!important}
.phoenix-3d-core{width:min(470px,72%)!important;aspect-ratio:1!important}
.phoenix-artwork{position:relative;width:92%;height:74%;overflow:hidden;display:grid;place-items:center;z-index:4;filter:drop-shadow(0 24px 38px color-mix(in srgb,var(--accent-red) 18%,transparent))}
.phoenix-artwork img{width:100%!important;height:auto!important;max-height:none!important;object-fit:contain!important;transform:translateY(-8.5%)!important;animation:phoenixBreath 6s ease-in-out infinite!important}
.phoenix-halo{inset:5%!important;background:radial-gradient(circle,color-mix(in srgb,var(--accent-red) 12%,transparent),transparent 68%)!important;filter:blur(18px)!important}
.phoenix-ring-label{bottom:-2%!important;font-size:8px!important;letter-spacing:.28em!important;text-shadow:0 4px 16px color-mix(in srgb,var(--accent-red) 20%,transparent)!important}
.phoenix-orbit.orbit-a{width:72%!important;height:31%!important}
.phoenix-orbit.orbit-b{width:40%!important;height:82%!important}
.phoenix-orbit.orbit-c{width:92%!important;height:50%!important}
.phoenix-node{padding:9px 13px!important;background:color-mix(in srgb,var(--bg-card) 86%,transparent)!important;border-color:color-mix(in srgb,var(--accent-gold) 28%,var(--border-tech))!important;box-shadow:0 12px 35px rgba(0,0,0,.08)!important}

/* Reference floating chips become a deliberate information layer, not decoration. */
.float-chip,.reference-campus-badge{padding:9px 13px!important;border-radius:999px!important;font-size:9px!important;background:color-mix(in srgb,var(--bg-card) 84%,transparent)!important;border-color:color-mix(in srgb,var(--accent-gold) 34%,var(--border-tech))!important;box-shadow:0 12px 34px rgba(0,0,0,.12)!important;backdrop-filter:blur(14px)!important}
.chip1{top:10%!important;left:2%!important}.chip2{right:1%!important;bottom:11%!important}
.reference-campus-badge{position:absolute!important;left:50%!important;bottom:4%!important;transform:translateX(-50%) translateZ(50px)!important;color:var(--accent-red)!important;font:700 9px 'Space Grotesk'!important;letter-spacing:.24em!important}
.reference-side-note{right:-1%!important;top:30%!important;display:grid!important;gap:9px!important;padding-left:13px!important;border-left:2px solid var(--accent-red)!important;color:var(--text-primary)!important;font:700 9px 'Space Grotesk'!important;letter-spacing:.02em!important}

.hero-context-rail{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-top:22px;padding-top:13px;border-top:1px solid var(--border-tech);color:var(--text-muted);font:700 9px 'Space Grotesk';letter-spacing:.12em}
.hero-context-rail span{display:inline-flex;align-items:center;gap:7px}.hero-context-rail i{width:6px;height:6px;border-radius:50%;background:var(--accent-red);box-shadow:0 0 0 5px color-mix(in srgb,var(--accent-red) 10%,transparent)}
.hero-context-rail span:last-child{color:var(--accent-red)}
.hero-quick{margin-top:28px!important}

/* Stronger editorial rhythm and less "AI template" feeling. */
.section{padding:92px 0!important}
.section-head h2{max-width:850px!important}
.section-head p{max-width:680px!important}
.card,.featured,.contact-card,.principles>div,.number-list>div{border-radius:20px!important}
.card:hover,.featured:hover{transform:translateY(-6px)!important}

/* Utility surfaces: make filters/search feel like a product, not form controls. */
input,select,textarea{border-radius:14px!important}
.search-trigger kbd{border:1px solid var(--border-tech);border-radius:6px;padding:2px 5px;font-size:8px;color:var(--text-muted)}

/* Accessibility + touch targets. */
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent-red)!important;outline-offset:3px!important}
.skip-link{z-index:500!important}

/* Mobile: bottom nav stays five items, top nav becomes a compact utility bar. */
@media(max-width:760px){
  .nav-inner{height:64px!important;width:calc(100% - 20px)!important;padding:0 0 0 0!important}
  .brand{min-width:0!important;max-width:calc(100% - 100px)!important}.brand img{width:40px!important;height:40px!important}.brand span{font-size:11px!important;letter-spacing:.04em!important;overflow:hidden;text-overflow:ellipsis}
  .nav nav{top:64px!important}.nav-more-trigger{display:none!important}
