/* ===== v14-7-final-ui.css ===== */
/* JYC V14.7 — final senior feedback, navigation, admin and mobile QA pass. */
:root{
  --jyc-red:#e21d2b;
  --jyc-gold:#c9a86a;
  --jyc-cream:#f4ead6;
}

/* ---------- Brand mark: use the clean phoenix, not the text baked into the circular logo. ---------- */
.brand-mark,.admin-brand-mark,.login-mark,.loading-mark{display:grid;place-items:center;flex:0 0 auto;border:1px solid color-mix(in srgb,var(--accent-gold) 45%,var(--border-tech));background:var(--bg-card);box-shadow:0 8px 28px color-mix(in srgb,var(--accent-gold) 10%,transparent);overflow:hidden}
.brand-mark{width:48px;height:48px;border-radius:50%;padding:8px}
.brand-mark img{width:100%!important;height:100%!important;padding:0!important;border:0!important;background:transparent!important;box-shadow:none!important;object-fit:contain}
.admin-brand-mark{width:44px;height:44px;border-radius:13px;padding:7px}
.admin-brand-mark img{width:100%;height:100%;object-fit:contain}
.login-mark{width:94px;height:94px;border-radius:28px;padding:17px;margin-bottom:18px}
.login-mark img{width:100%;height:100%;object-fit:contain}
.loading-mark{width:112px;height:112px;border-radius:50%;padding:19px;margin-bottom:16px;box-shadow:0 0 0 10px color-mix(in srgb,var(--accent-gold) 4%,transparent),0 22px 70px color-mix(in srgb,var(--accent-red) 16%,transparent)}
.loading-mark img{width:100%;height:100%;object-fit:contain}

/* ---------- Header utility row: theme stays in the header on every viewport. ---------- */
.mobile-theme-float{display:none!important}
.nav-inner>.theme-toggle{display:grid!important;position:static!important;order:2!important;width:44px!important;height:44px!important;flex:0 0 44px!important;margin-left:auto!important;box-shadow:none!important}
.nav-inner>.hamb{order:3!important}
.nav-inner>nav{order:4!important}
.nav-inner>.search-trigger{order:5!important}
@media(min-width:761px){.nav-inner>.theme-toggle{margin-left:auto!important}.nav-inner>nav{margin-left:0!important}}
@media(max-width:760px){
  .nav-inner{gap:7px!important}
  .brand{max-width:none!important;flex:1 1 auto!important;min-width:0!important}
  .brand-mark{width:40px;height:40px;padding:7px}
  .brand span{font-size:10px!important}
  .nav-inner>.theme-toggle{width:38px!important;height:38px!important;flex-basis:38px!important;margin-left:0!important}
  .nav-inner>.hamb{display:flex!important;order:4!important}
  .nav-inner>.search-trigger{order:5!important}
}

/* ---------- More menu: it must sit above the fixed mobile dock. ---------- */
.more-sheet-overlay{z-index:1300!important;padding-bottom:calc(104px + env(safe-area-inset-bottom))!important}
.more-sheet{z-index:1301!important}
@media(max-width:760px){
  .more-sheet-overlay{padding:70px 10px calc(106px + env(safe-area-inset-bottom))!important}
