}

/* ---------- Search/filter controls: pill-first and collision-proof. ---------- */
.club-search,.event-search,.team-search-field{min-height:46px!important;border-radius:999px!important;padding:0 15px!important}
.club-search input,.event-search input,.team-search-field input{min-width:0!important}
.team-toolbar{display:grid!important;grid-template-columns:minmax(0,1fr) auto!important;gap:12px!important;align-items:center!important}
.team-search-field{min-width:0!important}
.team-filter-row{display:flex;align-items:center;gap:8px;min-width:0}
.filter-label{font:700 9px 'Space Grotesk';letter-spacing:.14em;color:var(--text-muted);white-space:nowrap}
.team-toolbar .gallery-filter{display:flex!important;flex-wrap:nowrap!important;gap:6px!important;overflow-x:auto!important;scrollbar-width:none!important;margin:0!important;padding:2px!important}
.team-toolbar .gallery-filter::-webkit-scrollbar{display:none}
.team-toolbar .gallery-filter button{border-radius:999px!important;white-space:nowrap!important;padding:9px 13px!important;min-height:38px!important}
.team-toolbar .gallery-filter button.active{background:var(--accent-red)!important;color:#fff!important;border-color:var(--accent-red)!important}
@media(max-width:900px){.team-toolbar{grid-template-columns:1fr!important}.team-filter-row{overflow:hidden}.filter-label{display:none}}
@media(max-width:760px){.team-toolbar{padding:9px!important;gap:9px!important}.team-search-field{width:100%!important}.team-toolbar .gallery-filter button{min-height:38px!important;font-size:10px!important}}

/* ---------- Editorial empty states: no giant isolated translucent box. ---------- */
.page>.state,.section>.state,.dark-band>.state{background:transparent!important;border:0!important;border-top:1px solid var(--border-tech)!important;border-bottom:1px solid var(--border-tech)!important;border-radius:0!important;box-shadow:none!important;max-width:none!important;margin:28px 0!important;padding:70px 10px!important}
.page>.state .state-orbit,.section>.state .state-orbit,.dark-band>.state .state-orbit{opacity:.25!important}
.page>.state h1,.section>.state h1,.dark-band>.state h1{max-width:680px;margin-left:auto;margin-right:auto}
.page>.state p,.section>.state p,.dark-band>.state p{max-width:600px;margin-left:auto;margin-right:auto}

/* ---------- Section rhythm: thin editorial dividers rather than card-after-card stacking. ---------- */
.home .section:not(.hero){position:relative}
.home .home-layout>.section:before{content:"";display:block;width:100%;height:1px;background:linear-gradient(90deg,transparent,var(--border-tech) 12%,var(--border-tech) 88%,transparent);margin-bottom:72px;opacity:.8}
@media(max-width:760px){.home .home-layout>.section:before{margin-bottom:40px}.page>.state,.section>.state,.dark-band>.state{padding:52px 8px!important}}

/* ---------- Dynamic counters: zero means zero, not fake "0+". ---------- */
.hero-stats .stat-suffix{margin-left:1px;color:var(--accent-gold)}

/* ---------- Loading / reload experience ---------- */
.loading{background:radial-gradient(circle at 50% 44%,color-mix(in srgb,var(--accent-red) 8%,transparent),transparent 30%),var(--bg-main)!important}
.loading-grid{position:absolute;inset:0;opacity:.18;background-image:linear-gradient(var(--border-tech) 1px,transparent 1px),linear-gradient(90deg,var(--border-tech) 1px,transparent 1px);background-size:42px 42px;mask-image:radial-gradient(circle at center,#000 0%,transparent 68%)}
.loading-kicker{font:700 9px 'Space Grotesk';letter-spacing:.24em;color:var(--accent-red);margin-bottom:12px;text-align:center}
.loading-kicker i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--accent-red);box-shadow:0 0 0 5px color-mix(in srgb,var(--accent-red) 10%,transparent);margin-right:6px}
.loading-status{display:flex;justify-content:space-between;gap:18px;width:min(300px,80vw);margin-top:10px;color:var(--text-muted);font:700 8px 'Space Grotesk';letter-spacing:.12em}
.loading-status span:last-child{text-align:right}

/* ---------- Admin: product-style shell, collapsible desktop rail, stronger mobile header. ---------- */
.admin-shell{grid-template-columns:276px minmax(0,1fr)!important;transition:grid-template-columns .28s ease}
.admin-shell.admin-sidebar-collapsed{grid-template-columns:82px minmax(0,1fr)!important}
.admin-side{border-right:1px solid var(--border-tech)!important;background:color-mix(in srgb,var(--bg-card) 86%,transparent)!important;backdrop-filter:blur(22px)!important}
.admin-brand-row{display:flex;align-items:center;gap:8px;margin-bottom:12px}
.admin-brand-row .admin-brand{min-width:0;flex:1}
.admin-collapse{width:34px;height:34px;border:1px solid var(--border-tech);border-radius:10px;background:var(--bg-main);color:var(--text-muted);cursor:pointer}
.admin-collapse:hover{border-color:var(--accent-gold);color:var(--text-primary)}
.admin-sidebar-collapsed .admin-brand-row .admin-brand{justify-content:center}
.admin-sidebar-collapsed .admin-brand-row .admin-brand>div,.admin-sidebar-collapsed .admin-user>div,.admin-sidebar-collapsed .admin-nav-group>span,.admin-sidebar-collapsed .admin-nav-label,.admin-sidebar-collapsed .admin-nav-group button em{display:none!important}
.admin-sidebar-collapsed .admin-side .back-link{justify-content:center;font-size:0}
.admin-sidebar-collapsed .admin-side .logout{font-size:0}
.admin-sidebar-collapsed .admin-side .logout:after{content:'↪';font-size:16px}
.admin-sidebar-collapsed .admin-nav-group button{justify-content:center!important;padding:9px!important}
.admin-sidebar-collapsed .admin-nav-icon{margin:0!important}
.admin-top{position:sticky!important;top:0!important;background:color-mix(in srgb,var(--bg-main) 90%,transparent)!important;backdrop-filter:blur(18px)!important;padding-top:14px!important;padding-bottom:16px!important;border-bottom:1px solid var(--border-tech)!important;margin-bottom:20px}
.admin-breadcrumb{display:flex;align-items:center;gap:7px;color:var(--text-muted);font:700 9px 'Space Grotesk';letter-spacing:.08em;text-transform:uppercase;margin-bottom:9px}
.admin-breadcrumb strong{color:var(--text-primary)}
.admin-welcome-card,.health-mini,.attention-panel,.quick-actions-panel,.workspace-cards{border-radius:22px!important}
.admin-welcome-card{background:linear-gradient(135deg,color-mix(in srgb,var(--accent-red) 7%,var(--bg-card)),var(--bg-card))!important}
.admin-actions{gap:7px!important}
.admin-actions .command-trigger{border-radius:999px!important}
.admin-command-search{border-radius:999px!important}
.admin-command-list>button{min-height:54px!important}
@media(max-width:900px){
 .admin-shell,.admin-shell.admin-sidebar-collapsed{display:block!important;min-height:100svh!important}
 .admin-side{display:none!important}
 .admin-top{position:relative!important;padding:18px 14px 14px!important;margin:0!important}
 .admin-breadcrumb{margin-bottom:8px}
 .admin-main{padding-bottom:108px!important}
}

/* ---------- Admin login ---------- */
.login-page{position:relative;min-height:100svh;display:grid;place-items:center;padding:30px 16px;overflow:hidden}
.login-kicker{position:absolute;top:26px;left:28px;font:700 9px 'Space Grotesk';letter-spacing:.18em;color:var(--accent-red)}
.login-kicker i{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--accent-red);margin-right:7px}
.login-card{border-radius:28px!important;padding:34px!important;background:color-mix(in srgb,var(--bg-card) 94%,transparent)!important;backdrop-filter:blur(24px)!important;box-shadow:0 40px 100px rgba(0,0,0,.28)!important}

/* ---------- Hero polish ---------- */
.hero-art:after{content:"";position:absolute;inset:18% 8%;pointer-events:none;background:radial-gradient(circle at var(--glow-x,50%) var(--glow-y,50%),color-mix(in srgb,var(--accent-red) 10%,transparent),transparent 42%);filter:blur(26px);opacity:.75;mix-blend-mode:screen}
.phoenix-artwork img{filter:saturate(.9) contrast(1.05) drop-shadow(0 20px 35px color-mix(in srgb,var(--accent-red) 20%,transparent))!important}

@media(prefers-reduced-motion:reduce){.admin-shell{transition:none}.hero-art:after{display:none}.loading-grid{display:none}}


/* ===== v14-8-signature-ui.css ===== */
/* JYC V14.8 — signature product polish */

/* ---------- Brand lockup ---------- */
.nav .brand {
    position: relative;
    isolation: isolate;
    gap: 11px !important
}

.nav .brand:before {
    content: "";
    position: absolute;
    left: -8px;
    top: 50%;
    width: calc(100% + 16px);
    height: 54px;
    transform: translateY(-50%);
    border: 1px solid color-mix(in srgb, var(--accent-gold) 10%, transparent);
    border-radius: 18px;
    opacity: 0;
    transition: opacity .22s ease;
    pointer-events: none
}

.nav .brand:hover:before {
    opacity: 1
}

.brand-mark {
    position: relative !important;
    width: 50px !important;
    height: 50px !important;
    padding: 9px !important;
    border-radius: 15px !important;
    background: linear-gradient(145deg, var(--bg-card), color-mix(in srgb, var(--accent-gold) 7%, var(--bg-card))) !important;
    border-color: color-mix(in srgb, var(--accent-gold) 55%, var(--border-tech)) !important;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, .12), 0 10px 30px color-mix(in srgb, var(--accent-red) 9%, transparent) !important
}

.brand-mark:before {
    content: "";
    position: absolute;
    inset: 4px;
    border: 1px solid color-mix(in srgb, var(--accent-red) 22%, transparent);
    border-radius: 11px;
    pointer-events: none
}

.brand-mark:after {
    content: "";
    position: absolute;
    width: 5px;
    height: 5px;
    right: 5px;
    top: 5px;
    border-radius: 50%;
    background: var(--accent-red);
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-red) 8%, transparent), 0 0 16px color-mix(in srgb, var(--accent-red) 35%, transparent)
}

.brand-mark img {
    position: relative;
    z-index: 2
}

.nav .brand>span:last-child {
    font-family: 'Space Grotesk', sans-serif !important;
    font-weight: 800 !important;
    letter-spacing: .08em !important
}

.nav .brand>span:last-child:after {
    content: 'SECTOR 128';
    display: block;
    margin-top: 3px;
    font-size: 7px;
    font-weight: 700;
    letter-spacing: .22em;
    color: var(--text-muted);
    opacity: .8
}

/* ---------- Hero: finished phoenix identity ---------- */
.phoenix-3d-stage {
    isolation: isolate !important
}

.phoenix-3d-stage:before {
    content: "";
    position: absolute;
    inset: 7% 10% 10%;
    border: 1px solid color-mix(in srgb, var(--accent-gold) 12%, transparent);
    border-radius: 50%;
    transform: rotate(-9deg) scaleX(1.06);
    pointer-events: none;
    z-index: 0;
    box-shadow: 0 0 80px color-mix(in srgb, var(--accent-red) 5%, transparent)
}

.phoenix-3d-stage:after {
    content: "JYC / 128 / NOIDA";
    position: absolute;
    right: 5%;
    top: 0;
    font: 700 8px 'Space Grotesk';
    letter-spacing: .2em;
    color: var(--text-muted);
    writing-mode: vertical-rl;
    z-index: 5;
    opacity: .7
}

.phoenix-depth-back {
    border: 1px solid color-mix(in srgb, var(--accent-red) 13%, transparent) !important;
    background: radial-gradient(circle at 50% 45%, color-mix(in srgb, var(--accent-red) 12%, transparent), transparent 58%) !important;
    filter: blur(.2px) !important
}

.phoenix-3d-core {
    z-index: 4 !important
}

.phoenix-3d-core:before {
    content: "";
    position: absolute;
    width: 76%;
    aspect-ratio: 1;
    border-radius: 50%;
    border: 1px dashed color-mix(in srgb, var(--accent-gold) 28%, transparent);
    transform: rotate(18deg);
    opacity: .8;
    pointer-events: none
}

.phoenix-artwork {
    z-index: 3 !important
}

.phoenix-artwork:before {
    content: "";
    position: absolute;
    inset: 9%;
    background: radial-gradient(circle, color-mix(in srgb, var(--accent-red) 15%, transparent), transparent 66%);
    filter: blur(25px);
    opacity: .8;
    pointer-events: none
}

.phoenix-artwork img {
    position: relative;
    z-index: 2 !important
}

.phoenix-seal-wrap {
    position: absolute;
    z-index: 5;
    left: 50%;
    bottom: 4%;
    transform: translateX(-50%) translateZ(70px);
    display: flex;
    flex-direction: column;
    align-items: center
}

.phoenix-seal {
    position: relative;
    width: 92px;
    height: 92px;
    border-radius: 50%;
    padding: 10px;
    background: color-mix(in srgb, var(--bg-card) 92%, transparent);
    border: 1px solid color-mix(in srgb, var(--accent-gold) 48%, var(--border-tech));
    box-shadow: 0 18px 45px rgba(0, 0, 0, .2), inset 0 0 0 4px color-mix(in srgb, var(--accent-red) 7%, transparent);
    backdrop-filter: blur(14px);
    overflow: hidden
}

.phoenix-seal:before {
    content: "";
    position: absolute;
    inset: 6px;
    border: 1px solid color-mix(in srgb, var(--accent-red) 24%, transparent);
    border-radius: 50%
}

.phoenix-seal img {
    position: relative;
    width: 100%;
    height: 100%;
    object-fit: contain;
    filter: saturate(.9) contrast(1.03)
}

.phoenix-seal-label {
    display: block;
    margin-top: 7px;
    font: 800 7px 'Space Grotesk';
    letter-spacing: .22em;
    color: var(--text-muted);
    white-space: nowrap
}

.phoenix-ring-label {
    z-index: 6 !important;
    bottom: 1% !important;
    opacity: .9 !important
}

/* ---------- Hero status plaque ---------- */
.hero-art .next-event-plaque {
    position: absolute;
    left: 2%;
    bottom: 9%;
    z-index: 7;
    min-width: 190px;
    max-width: 240px;
    padding: 11px 13px;
    border: 1px solid var(--border-tech);
    border-radius: 15px;
    background: color-mix(in srgb, var(--bg-card) 86%, transparent);
    backdrop-filter: blur(16px);
    box-shadow: 0 16px 42px rgba(0, 0, 0, .12);
    text-align: left
}

.next-event-plaque small {
    display: block;
    font: 800 7px 'Space Grotesk';
    letter-spacing: .2em;
    color: var(--accent-red);
    margin-bottom: 5px
}

.next-event-plaque strong {
    display: block;
    font: 700 12px 'Space Grotesk';
    line-height: 1.2;
    color: var(--text-primary);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis
}

.next-event-plaque span {
    display: block;
    margin-top: 4px;
    font: 600 8px 'Space Grotesk';
    color: var(--text-muted);
    letter-spacing: .05em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis
}

/* ---------- Navigation polish ---------- */
.nav nav button,
.nav-more-trigger {
    position: relative
}

.nav nav button.active:after {
    content: "";
    position: absolute;
    left: 50%;
    bottom: -7px;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--accent-red);
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-red) 8%, transparent);
    transform: translateX(-50%)
}

.search-trigger {
    border-color: color-mix(in srgb, var(--accent-gold) 22%, var(--border-tech)) !important;
    background: color-mix(in srgb, var(--bg-card) 55%, transparent) !important
}

/* ---------- Scroll progress + quick top action ---------- */
.scroll-progress {
    width: 100% !important;
    right: auto !important;
    left: 0 !important;
    top: 0 !important;
    bottom: auto !important;
    height: 2px !important;
    z-index: 2500 !important;
    border-radius: 0 !important;
    opacity: 1 !important;
    background: transparent !important;
    overflow: hidden !important
}

.scroll-progress i {
    width: var(--scroll-progress-width, 0%) !important;
    height: 100% !important;
    min-height: 0 !important;
    background: linear-gradient(90deg, var(--accent-red), var(--accent-gold)) !important;
    box-shadow: 0 0 12px color-mix(in srgb, var(--accent-red) 35%, transparent) !important
}

/* ---------- Editorial section headers ---------- */
.home .section-head h2,
.home .reference-section-head h2 {
    max-width: 850px
}

.home .section-head:after,
.home .reference-section-head:after {
    content: "";
    display: block;
    width: 44px;
    height: 2px;
    margin-top: 18px;
    background: var(--accent-red);
    box-shadow: 14px 0 0 color-mix(in srgb, var(--accent-gold) 70%, transparent)
}

/* ---------- Empty-state upgrade ---------- */
.moments-empty,
.discover-empty {
    position: relative;
    overflow: hidden;
    border-top: 1px solid var(--border-tech);
    border-bottom: 1px solid var(--border-tech);
    background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--accent-gold) 3%, transparent), transparent) !important
}

.moments-empty:after,
.discover-empty:after {
    content: "JYC";
    position: absolute;
    right: 2%;
    bottom: -25px;
    font: 900 110px/1 'Space Grotesk';
    letter-spacing: -.08em;
    color: var(--accent-red);
    opacity: .025;
    pointer-events: none
}

/* ---------- Admin refinements ---------- */
.admin-side:before {
    content: "JYC CONTROL";
    display: block;
    font: 800 7px 'Space Grotesk';
    letter-spacing: .25em;
    color: var(--accent-red);
    margin: -2px 0 11px 2px
}

.admin-nav-group button.active {
    box-shadow: inset 3px 0 0 var(--accent-red), 0 8px 22px color-mix(in srgb, var(--accent-red) 5%, transparent) !important
}

.admin-top h1 {
    letter-spacing: -.04em !important
