/* ===== v14-9-senior-fixes.css ===== */
/* JYC V14.9 — Senior feedback + mobile stability pass
   Focus: persistent navigation, no disappearing content, cleaner logo lockups,
   rounded More sheet, and editorial empty states.
*/

/* ================================================================
   01 — REVEALS MUST NEVER DISAPPEAR AFTER THEY HAVE ENTERED VIEW
   ================================================================ */
.reveal{
  animation:none!important;
  opacity:0!important;
  transform:translate3d(0,18px,0)!important;
  transition:opacity .68s cubic-bezier(.22,1,.36,1),transform .68s cubic-bezier(.22,1,.36,1)!important;
  transition-delay:var(--reveal-delay,0ms)!important;
}
.reveal.is-visible{
  opacity:1!important;
  transform:none!important;
}
@media(prefers-reduced-motion:reduce){
  .reveal,.reveal.is-visible{opacity:1!important;transform:none!important;transition:none!important}
}

/* ================================================================
   02 — HEADER LOGO: USE THE REAL CIRCULAR JYC SEAL, NOT A BLURRY
       PHOENIX CROP
   ================================================================ */
.nav .brand{gap:10px!important}
.brand-mark{
  width:46px!important;
  height:46px!important;
  flex:0 0 46px!important;
  padding:3px!important;
  border-radius:50%!important;
  overflow:hidden!important;
  display:grid!important;
  place-items:center!important;
  background:color-mix(in srgb,var(--bg-card) 88%,transparent)!important;
  border:1px solid color-mix(in srgb,var(--accent-gold) 42%,var(--border-tech))!important;
  box-shadow:0 8px 26px color-mix(in srgb,var(--accent-red) 9%,transparent),inset 0 1px 0 rgba(255,255,255,.14)!important;
}
.brand-mark:before{
  inset:3px!important;
  border-radius:50%!important;
  border-color:color-mix(in srgb,var(--accent-gold) 18%,transparent)!important;
}
.brand-mark:after{
  width:4px!important;height:4px!important;right:5px!important;top:5px!important;
}
.brand-mark img{
  width:100%!important;height:100%!important;
  object-fit:contain!important;
  border:0!important;padding:0!important;
  background:transparent!important;
  box-shadow:none!important;
  border-radius:50%!important;
  image-rendering:auto!important;
}
.nav .brand>span:last-child:after{display:none!important}
.nav .brand>span:last-child{
  line-height:1.05!important;
}

/* Loading + admin use the same crisp circular seal */
.loading-mark img,
.admin-brand-mark img{
  object-fit:contain!important;
  border-radius:50%!important;
  image-rendering:auto!important;
}

/* ================================================================
   03 — MOBILE DOCK: ALWAYS A REAL PILL, NEVER STATIC/SQUARE
   ================================================================ */
@media(max-width:700px){
  body{
    padding-bottom:96px!important;
  }
  .mobile-dock{
    display:grid!important;
    position:fixed!important;
    top:auto!important;
    left:8px!important;
    right:8px!important;
    bottom:max(8px,env(safe-area-inset-bottom))!important;
    width:auto!important;
    height:64px!important;
    min-height:64px!important;
    max-width:none!important;
    inset-block-start:auto!important;
    inset-block-end:max(8px,env(safe-area-inset-bottom))!important;
    grid-template-columns:repeat(5,minmax(0,1fr))!important;
    gap:3px!important;
    padding:5px!important;
    border-radius:24px!important;
    overflow:hidden!important;
    visibility:visible!important;
    opacity:1!important;
    pointer-events:auto!important;
    transform:translateZ(0)!important;
    z-index:999999!important;
    background:color-mix(in srgb,var(--bg-card) 86%,transparent)!important;
    border:1px solid color-mix(in srgb,var(--accent-gold) 36%,var(--border-tech))!important;
    backdrop-filter:blur(24px) saturate(140%)!important;
    -webkit-backdrop-filter:blur(24px) saturate(140%)!important;
    box-shadow:0 18px 60px rgba(0,0,0,.34),inset 0 1px 0 color-mix(in srgb,var(--text-primary) 10%,transparent)!important;
  }
  .mobile-dock .dock-active-pill{
    display:block!important;
    position:absolute!important;
    z-index:0!important;
    top:5px!important;bottom:5px!important;left:5px!important;
    width:calc((100% - 10px)/5)!important;
    border-radius:18px!important;
    background:var(--accent-red)!important;
    box-shadow:0 8px 28px color-mix(in srgb,var(--accent-red) 30%,transparent)!important;
    transform:translateX(calc(var(--dock-index,0) * 100%))!important;
    transition:transform .45s cubic-bezier(.22,1,.36,1)!important;
  }
  .mobile-dock button{
    position:relative!important;
    z-index:1!important;
    min-height:52px!important;
    border-radius:17px!important;
    background:transparent!important;
    color:var(--text-muted)!important;
  }
  .mobile-dock button.active{
    background:transparent!important;
    color:#fff!important;
    box-shadow:none!important;
  }
  .mobile-dock button.active span{color:#fff!important}
  /* The dock may hide only while the hamburger drawer is open. */
  body.menu-open .mobile-dock{
    opacity:0!important;
    visibility:hidden!important;
    pointer-events:none!important;
    transform:translateY(12px)!important;
  }
  :root[data-theme="light"] .mobile-dock{
    background:color-mix(in srgb,#fff 88%,transparent)!important;
    box-shadow:0 18px 55px rgba(50,40,30,.16),inset 0 1px 0 rgba(255,255,255,.96)!important;
  }
}

