.resources-page{padding-top:54px!important}.resource-principles{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--border-tech);border-bottom:1px solid var(--border-tech);margin:34px 0 18px}.resource-principles span{padding:16px 14px;font:700 10px 'Space Grotesk';letter-spacing:.18em;color:var(--text-muted);text-align:center;border-right:1px solid var(--border-tech)}.resource-principles span:last-child{border-right:0;color:var(--accent-red)}.resource-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.resource-card{position:relative;min-height:280px;border:1px solid var(--border-tech);border-radius:24px;background:var(--bg-card);padding:26px;display:flex;flex-direction:column;align-items:flex-start;overflow:hidden;transition:.25s ease}.resource-card:before{content:'';position:absolute;right:-50px;top:-60px;width:180px;height:180px;border:1px solid color-mix(in srgb,var(--accent-gold) 25%,transparent);border-radius:50%;opacity:.5}.resource-card:hover{transform:translateY(-4px);border-color:color-mix(in srgb,var(--accent-gold) 55%,var(--border-tech));box-shadow:0 18px 55px rgba(0,0,0,.08)}.resource-number{font:700 12px 'Space Grotesk';color:var(--accent-red);margin-bottom:38px}.resource-card h2{font:700 clamp(25px,3vw,38px) 'Space Grotesk';margin:8px 0 10px;max-width:650px}.resource-card p{color:var(--text-muted);line-height:1.65;max-width:620px;margin:0 0 22px}.resource-card button,.resource-card a,.resource-callout button{margin-top:auto;border:1px solid var(--border-tech);border-radius:999px;padding:11px 15px;background:var(--bg-main);color:var(--text-primary);font:700 11px 'Space Grotesk';text-decoration:none;cursor:pointer}.resource-card button:hover,.resource-card a:hover,.resource-callout button:hover{border-color:var(--accent-red);color:var(--accent-red)}.resource-callout{margin-top:14px;padding:28px;border-radius:24px;background:var(--jyc-ink,#090a0c);color:#fff;display:flex;align-items:flex-end;justify-content:space-between;gap:24px}.resource-callout h2{font:700 clamp(28px,4vw,48px) 'Space Grotesk';margin:8px 0}.resource-callout p{max-width:720px;color:rgba(255,255,255,.68);line-height:1.6;margin:0}.resource-callout button{background:#fff;color:#111;border-color:#fff;white-space:nowrap}

/* Beginner guide */
.guide-page{padding-top:54px!important}.guide-hero{border:1px solid var(--border-tech);border-radius:28px;padding:clamp(28px,6vw,72px);background:radial-gradient(circle at 85% 20%,color-mix(in srgb,var(--accent-red) 12%,transparent),transparent 28%),var(--bg-card);overflow:hidden}.guide-hero h1{font:700 clamp(58px,9vw,120px) 'Space Grotesk';line-height:.88;margin:22px 0}.guide-hero p{max-width:720px;color:var(--text-muted);font-size:16px;line-height:1.7}.guide-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:25px}.guide-actions button{border:1px solid var(--accent-red);background:var(--accent-red);color:#fff;border-radius:999px;padding:13px 17px;font:700 11px 'Space Grotesk';cursor:pointer}.guide-actions button.secondary{background:transparent;color:var(--text-primary);border-color:var(--border-tech)}.guide-steps{display:grid;gap:10px;margin-top:14px}.guide-step{width:100%;display:grid;grid-template-columns:64px 1fr 24px;align-items:center;gap:18px;text-align:left;border:1px solid var(--border-tech);background:var(--bg-card);color:var(--text-primary);border-radius:20px;padding:20px 22px;cursor:pointer;transition:.25s ease}.guide-step>span{font:700 11px 'Space Grotesk';color:var(--accent-red)}.guide-step strong{font:700 23px 'Space Grotesk'}.guide-step p{margin:5px 0 0;color:var(--text-muted);line-height:1.55}.guide-step>b{font-size:20px}.guide-step:hover{transform:translateX(4px);border-color:var(--accent-red)}.guide-open-source{margin-top:14px;border-top:1px solid var(--border-tech);border-bottom:1px solid var(--border-tech);padding:32px 0;display:flex;align-items:flex-end;justify-content:space-between;gap:25px}.guide-open-source h2{font:700 clamp(28px,4vw,52px) 'Space Grotesk';margin:8px 0}.guide-open-source p{max-width:850px;color:var(--text-muted);line-height:1.65}.guide-open-source a{border:1px solid var(--border-tech);border-radius:999px;padding:11px 14px;color:var(--text-primary);text-decoration:none;font:700 10px 'Space Grotesk';white-space:nowrap}.guide-open-source a:hover{border-color:var(--accent-red);color:var(--accent-red)}

@media(max-width:760px){.more-sheet-section{padding:0 14px 14px}.more-sheet-guide{grid-template-columns:1fr 1fr!important}.more-sheet-staff{margin:4px 14px 14px}.resource-principles{grid-template-columns:1fr 1fr}.resource-principles span:nth-child(2){border-right:0}.resource-principles span:nth-child(-n+2){border-bottom:1px solid var(--border-tech)}.resource-grid{grid-template-columns:1fr}.resource-card{min-height:250px;padding:21px}.resource-callout{display:grid;padding:23px}.resource-callout button{justify-self:start}.guide-step{grid-template-columns:42px 1fr 18px;padding:17px 15px;gap:10px}.guide-step strong{font-size:19px}.guide-step p{font-size:12px}.guide-open-source{display:grid}.guide-open-source a{justify-self:start}.guide-hero h1{font-size:clamp(54px,17vw,82px)}}
@media(prefers-reduced-motion:reduce){.resource-card,.guide-step{transition:none}.resource-card:hover,.guide-step:hover{transform:none}}
.search-admin-tools{display:grid;gap:8px;margin:0 0 12px}.search-admin-tools>span{font:700 9px 'Space Grotesk';letter-spacing:.16em;color:var(--accent-red)}.search-admin-tools button{position:relative;display:grid;grid-template-columns:1fr auto;gap:3px;text-align:left;border:1px solid color-mix(in srgb,var(--accent-red) 28%,var(--border-tech));background:color-mix(in srgb,var(--accent-red) 4%,var(--bg-card));color:var(--text-primary);border-radius:14px;padding:11px 13px;cursor:pointer}.search-admin-tools button:hover{border-color:var(--accent-red)}.search-admin-tools b{font:700 11px 'Space Grotesk'}.search-admin-tools small{grid-column:1;color:var(--text-muted);font-size:10px}.search-admin-tools strong{grid-column:2;grid-row:1/3;align-self:center;color:var(--accent-red)}


/* ===== v16-2-iit-polish.css ===== */
/* JYC V16.2 — IIT-inspired utility polish: unified campus feed, richer motion, premium loading, and tactile navigation. */
:root{--jyc-ease:cubic-bezier(.16,1,.3,1);--jyc-spring:cubic-bezier(.22,1,.36,1)}
/* ---------- Global interaction language ---------- */
button,a,.card,.guide-step,.resource-card,.ecosystem-node,.moment-tile,.event-card,.club-card,.past-card{transition:transform .45s var(--jyc-ease),border-color .35s ease,box-shadow .45s ease,background-color .35s ease,color .25s ease}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent-red);outline-offset:3px}
::selection{background:var(--accent-red);color:#fff}

/* ---------- Premium loading screen ---------- */
.loading{isolation:isolate;background:radial-gradient(circle at 50% 42%,color-mix(in srgb,var(--accent-gold) 9%,var(--bg-main)),var(--bg-main) 42%);overflow:hidden}
.loading:before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 50% 50%,transparent 0 23%,color-mix(in srgb,var(--accent-red) 5%,transparent) 24%,transparent 52%);animation:loadingBreath 3.5s ease-in-out infinite}
.loading-grid{opacity:.32;background-image:linear-gradient(color-mix(in srgb,var(--text-primary) 7%,transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb,var(--text-primary) 7%,transparent) 1px,transparent 1px);background-size:44px 44px;mask-image:radial-gradient(circle at center,#000,transparent 72%);animation:loadingGrid 16s linear infinite}
.loading-orbit{border-color:color-mix(in srgb,var(--accent-gold) 42%,transparent);box-shadow:0 0 35px color-mix(in srgb,var(--accent-gold) 7%,transparent)}
.loading-orbit-a{width:min(66vw,720px);height:min(30vw,330px);animation:loadingOrbitA 12s linear infinite}
.loading-orbit-b{width:min(46vw,520px);height:min(46vw,520px);animation:loadingOrbitB 18s linear infinite}
.loading-center{width:min(620px,90vw);position:relative;z-index:2;animation:loadingCenterIn 1s var(--jyc-ease) both}
.loading-kicker{display:flex;align-items:center;justify-content:center;gap:9px;font:700 10px 'Space Grotesk';letter-spacing:.2em;color:var(--text-muted);text-transform:uppercase}
.loading-kicker i{width:7px;height:7px;border-radius:50%;background:var(--accent-red);box-shadow:0 0 0 6px color-mix(in srgb,var(--accent-red) 10%,transparent);animation:loadingDot 1.5s ease-in-out infinite}
.loading-logo{display:grid;justify-items:center;gap:8px;margin-top:22px}
.loading-logo>span:not(.loading-mark){font:700 clamp(28px,5vw,54px)/.95 'Space Grotesk';letter-spacing:-.055em}
.loading-logo strong{font:700 11px 'Space Grotesk';letter-spacing:.3em;color:var(--accent-red)}
.loading-mark{width:96px;height:96px;display:grid;place-items:center;border:1px solid var(--border-tech);border-radius:50%;background:color-mix(in srgb,var(--bg-card) 80%,transparent);box-shadow:0 0 0 14px color-mix(in srgb,var(--accent-gold) 4%,transparent),0 20px 70px color-mix(in srgb,var(--text-primary) 8%,transparent);animation:loadingMark 3s var(--jyc-spring) infinite}
.loading-mark img{width:72%;height:72%;object-fit:contain}
.loadline{width:min(420px,70vw);height:2px;background:color-mix(in srgb,var(--text-primary) 10%,transparent);margin:30px auto 12px;overflow:hidden}
.loadline i{display:block;height:100%;width:45%;background:linear-gradient(90deg,transparent,var(--accent-red),var(--accent-gold),transparent);animation:loadingLine 1.8s var(--jyc-ease) infinite}
.loading-status{display:flex;justify-content:space-between;gap:15px;color:var(--text-muted);font:700 9px 'Space Grotesk';letter-spacing:.15em}
.loading-status span:first-child{color:var(--accent-red);min-width:90px;text-align:left}
.loading-status span:last-child{text-align:right}
@keyframes loadingCenterIn{from{opacity:0;transform:translateY(18px) scale(.97)}to{opacity:1;transform:none}}
@keyframes loadingBreath{0%,100%{opacity:.5;transform:scale(.94)}50%{opacity:1;transform:scale(1.04)}}
@keyframes loadingGrid{to{background-position:44px 44px}}
@keyframes loadingOrbitA{to{transform:rotate(360deg) rotateX(62deg)}}
@keyframes loadingOrbitB{to{transform:rotate(-360deg) rotateY(62deg)}}
@keyframes loadingMark{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-7px) rotate(2deg)}}
@keyframes loadingLine{0%{transform:translateX(-130%)}100%{transform:translateX(320%)}}
@keyframes loadingDot{0%,100%{opacity:.55;transform:scale(.8)}50%{opacity:1;transform:scale(1.15)}}

/* ---------- Header: institutional utility feel ---------- */
.nav-inner{position:relative}
.nav:after{content:'';position:absolute;left:0;right:0;bottom:-1px;height:1px;background:linear-gradient(90deg,transparent,var(--accent-red),var(--accent-gold),transparent);opacity:.45;transform:scaleX(.35);transition:transform .7s var(--jyc-ease)}
.nav:hover:after{transform:scaleX(1)}
.brand{transition:transform .45s var(--jyc-ease)}
.brand:hover{transform:translateX(2px)}
.brand-mark{position:relative}
.brand-mark:after{content:'';position:absolute;inset:-5px;border:1px solid color-mix(in srgb,var(--accent-gold) 25%,transparent);border-radius:50%;opacity:0;transform:scale(.7);transition:.5s var(--jyc-ease)}
.brand:hover .brand-mark:after{opacity:1;transform:scale(1)}
.nav nav button{overflow:hidden}
.nav nav button:before{content:'';position:absolute;left:50%;bottom:0;width:0;height:1px;background:var(--accent-gold);transition:width .35s var(--jyc-ease),left .35s var(--jyc-ease)}
.nav nav button:hover:before{width:70%;left:15%}
.search-trigger{box-shadow:0 8px 25px color-mix(in srgb,var(--text-primary) 5%,transparent)}
.search-trigger:hover{box-shadow:0 12px 35px color-mix(in srgb,var(--accent-red) 10%,transparent)}

/* ---------- Hero: richer depth without adding clutter ---------- */
.hero{perspective:1200px}
.hero-copy{position:relative;z-index:2}
.hero-copy:after{content:'';position:absolute;left:-100px;top:18%;width:340px;height:340px;background:radial-gradient(circle,color-mix(in srgb,var(--accent-red) 8%,transparent),transparent 68%);filter:blur(20px);pointer-events:none;z-index:-1}
.hero-art:before{content:'';position:absolute;width:75%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--accent-gold) 8%,transparent),transparent 67%);filter:blur(18px);animation:heroAura 6s ease-in-out infinite}
.next-event-plaque{animation:plaqueFloat 5s ease-in-out infinite;backdrop-filter:blur(12px)}
.float-chip{animation:chipFloat 5s ease-in-out infinite}
.chip2{animation-delay:-2.3s}.chip1{animation-delay:-1s}
@keyframes heroAura{0%,100%{transform:scale(.94);opacity:.55}50%{transform:scale(1.08);opacity:1}}
@keyframes plaqueFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
@keyframes chipFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}

/* ---------- Phoenix nodes become obvious controls ---------- */
.phoenix-node{cursor:pointer;user-select:none;transition:transform .45s var(--jyc-spring),background-color .35s,border-color .35s,box-shadow .35s,color .35s}
.phoenix-node:hover,.phoenix-node.active{transform:translate(-50%,-50%) scale(1.08);color:var(--text-primary);border-color:var(--accent-red);box-shadow:0 12px 35px color-mix(in srgb,var(--accent-red) 12%,transparent),0 0 0 6px color-mix(in srgb,var(--accent-red) 5%,transparent)}
.phoenix-node:after{content:'↗';display:inline-block;margin-left:5px;opacity:.45;transform:translateX(-3px);transition:.3s}
.phoenix-node:hover:after,.phoenix-node.active:after{opacity:1;transform:translateX(0)}

/* ---------- IIT-inspired campus pulse/feed ---------- */
.campus-feed{width:min(1280px,calc(100% - 64px));margin:0 auto;padding:82px 0 24px}
.campus-feed-head{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:26px}
.campus-feed-head h2{font:700 clamp(38px,5vw,68px)/.95 'Space Grotesk';letter-spacing:-.055em;margin:10px 0 8px}
.campus-feed-head p{max-width:700px;color:var(--text-muted);line-height:1.6;margin:0}
.campus-feed-link{border:1px solid var(--border-tech);background:var(--bg-card);color:var(--text-primary);border-radius:999px;padding:11px 15px;font:700 10px 'Space Grotesk';white-space:nowrap}
.campus-feed-link:hover{border-color:var(--accent-red);color:var(--accent-red);transform:translateY(-2px)}
.campus-feed-grid{display:grid;grid-template-columns:1.45fr .8fr .8fr;gap:12px}
.campus-feed-card{position:relative;min-height:210px;border:1px solid var(--border-tech);background:var(--bg-card);border-radius:22px;padding:22px;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between}
.campus-feed-card:before{content:'';position:absolute;right:-70px;top:-80px;width:200px;height:200px;border:1px solid color-mix(in srgb,var(--accent-gold) 28%,transparent);border-radius:50%;transition:transform .7s var(--jyc-ease)}
.campus-feed-card:hover:before{transform:scale(1.18)}
.campus-feed-card:hover{transform:translateY(-5px);border-color:color-mix(in srgb,var(--accent-gold) 55%,var(--border-tech));box-shadow:var(--shadow)}
.campus-feed-card.feature{min-height:285px;background:linear-gradient(145deg,color-mix(in srgb,var(--accent-red) 7%,var(--bg-card)),var(--bg-card))}
.campus-feed-card .feed-kicker{font:700 9px 'Space Grotesk';letter-spacing:.18em;color:var(--accent-red)}
.campus-feed-card h3{font:700 clamp(22px,2.7vw,36px)/1 'Space Grotesk';letter-spacing:-.035em;margin:12px 0 8px;max-width:700px}
.campus-feed-card p{color:var(--text-muted);line-height:1.55;margin:0;max-width:680px}
.feed-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}
.feed-meta span{border:1px solid var(--border-tech);border-radius:999px;padding:6px 9px;color:var(--text-muted);font-size:10px}
.feed-open{align-self:flex-start;margin-top:18px;border:0;background:none;color:var(--text-primary);font:700 10px 'Space Grotesk';padding:0}
.feed-open:hover{color:var(--accent-red);transform:translateX(3px)}
.campus-feed-empty{border:1px dashed var(--border-tech);padding:34px;border-radius:22px;color:var(--text-muted)}

/* ---------- More/search feel like a campus command layer ---------- */
.more-sheet-section,.more-sheet-staff,.more-sheet-connect{animation:panelRise .55s var(--jyc-ease) both}
.more-sheet-section:nth-child(2){animation-delay:.04s}.more-sheet-section:nth-child(3){animation-delay:.08s}.more-sheet-staff{animation-delay:.12s}.more-sheet-connect{animation-delay:.16s}
@keyframes panelRise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
.search-list>button{animation:searchResultIn .45s var(--jyc-ease) var(--result-delay,0ms) both}
@keyframes searchResultIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}

/* ---------- Event cards / feed cards ---------- */
.event-card,.club-card,.discover-card,.team-card{will-change:transform}
.event-card:hover .event-poster img,.event-card:hover .event-poster{transform:scale(1.025)}
.event-poster{transition:transform .7s var(--jyc-ease)}
.event-scope-tabs button,.gallery-filter button,.discover-interest-bar button{position:relative;overflow:hidden}
.event-scope-tabs button:after,.gallery-filter button:after,.discover-interest-bar button:after{content:'';position:absolute;left:50%;bottom:0;width:0;height:2px;background:var(--accent-red);transition:width .35s var(--jyc-ease),left .35s var(--jyc-ease)}
.event-scope-tabs button:hover:after,.gallery-filter button:hover:after,.discover-interest-bar button:hover:after{width:70%;left:15%}

/* ---------- Stats and strips ---------- */
.impact-strip,.pulse-strip,.next-moment-strip{position:relative;overflow:hidden}
.impact-strip:before,.next-moment-strip:before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent-gold) 5%,transparent),transparent);transform:translateX(-100%);animation:shimmerBand 7s ease-in-out infinite}
@keyframes shimmerBand{0%,65%,100%{transform:translateX(-100%)}78%{transform:translateX(100%)}}

/* ---------- Footer ---------- */
.jyc-footer{position:relative;overflow:hidden}
.jyc-footer:before{content:'JYC';position:absolute;right:-3vw;bottom:-8vw;font:700 25vw/.7 'Space Grotesk';letter-spacing:-.09em;color:color-mix(in srgb,var(--text-primary) 3%,transparent);pointer-events:none}
.footer-reference-features span{transition:color .3s,transform .3s}
.footer-reference-features span:hover{color:var(--accent-red);transform:translateY(-2px)}

/* ---------- Mobile ---------- */
@media(max-width:900px){.campus-feed,.campus-feed-head{width:min(100% - 32px,1280px)}.campus-feed-grid{grid-template-columns:1fr 1fr}.campus-feed-card.feature{grid-column:1/-1}.campus-feed-head{align-items:flex-start;flex-direction:column}.campus-feed-link{align-self:flex-start}}
@media(max-width:620px){.campus-feed{padding:58px 0 10px}.campus-feed-grid{grid-template-columns:1fr}.campus-feed-card.feature{grid-column:auto}.campus-feed-card,.campus-feed-card.feature{min-height:205px}.loading-mark{width:76px;height:76px}.loading-status{font-size:8px}.loading-status span:last-child{max-width:170px}.loading-orbit-a{width:88vw;height:42vw}.loading-orbit-b{width:68vw;height:68vw}.phoenix-node{font-size:8px!important}.hero-copy:after{display:none}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.001ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.001ms!important}.loading-grid,.loading-orbit,.loading-mark,.loadline i{animation:none}.campus-feed-card:hover,.feed-open:hover{transform:none}}
/* Phoenix fourth route + interaction hint */
.phoenix-node.node-four{left:50%;top:91%}
.phoenix-route-hint{position:absolute;left:50%;bottom:1.5%;transform:translateX(-50%);padding:7px 11px;border:1px solid var(--border-tech);border-radius:999px;background:color-mix(in srgb,var(--bg-card) 76%,transparent);backdrop-filter:blur(8px);color:var(--text-muted);font:700 8px 'Space Grotesk';letter-spacing:.16em;white-space:nowrap;pointer-events:none;transition:.4s var(--jyc-ease)}
.phoenix-3d-core.is-focused .phoenix-halo{opacity:1;transform:scale(1.08)}
@media(max-width:620px){.phoenix-route-hint{bottom:0;font-size:7px}.phoenix-node.node-four{top:88%}}


/* ===== v16-3-platform.css ===== */
/* JYC V16.3 — functional polish, campus-feed personalization and mobile/performance QA layer. */
:root{--jyc-fast:cubic-bezier(.2,.8,.2,1)}

/* Feed controls: useful on both desktop and phone. */
.campus-feed-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.secondary-feed-link{background:transparent!important}
.campus-feed-link:focus-visible{outline:2px solid var(--accent-red);outline-offset:3px}

/* More deliberate “follow/save” language. */
.club-card .save-btn,.event-card .save-btn{min-width:66px}
.club-card .save-btn:not(.saved):after{content:' +'}
.club-detail .club-hero-actions .btn.secondary{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--accent-red) 24%,transparent)}

/* Loading: progress is controlled by React instead of a fake loop. */
.loading .loadline{position:relative}
.loading .loadline:after{content:'';position:absolute;inset:-6px -2px;box-shadow:0 0 30px color-mix(in srgb,var(--accent-red) 12%,transparent);pointer-events:none}
.loading .loadline i{width:var(--boot-progress,18%);transform:none!important;animation:bootProgress .55s var(--jyc-fast) both}
.loading-steps{display:flex;justify-content:center;gap:7px;margin-top:14px}
.loading-steps i{width:26px;height:2px;border-radius:99px;background:color-mix(in srgb,var(--text-primary) 12%,transparent);transition:background .4s var(--jyc-fast),transform .4s var(--jyc-fast)}
.loading-steps i.done{background:linear-gradient(90deg,var(--accent-red),var(--accent-gold));transform:scaleX(1.08)}
@keyframes bootProgress{from{width:0;opacity:.5}to{width:var(--boot-progress,18%);opacity:1}}

/* Avoid paying a GPU layer for every card all the time. */
.event-card,.club-card,.discover-card,.team-card{will-change:auto}
.event-card:hover,.club-card:hover,.discover-card:hover,.team-card:hover{will-change:transform}
.gallery-item img,.event-poster,.club-card-visual{backface-visibility:hidden}

/* Touch devices do not need hover tilt/shadow complexity. */
@media (hover:none){
  .tilt-card{transform:none!important}
  .event-card:hover,.club-card:hover,.discover-card:hover,.team-card:hover{transform:none;box-shadow:none}
  .campus-feed-card:hover{transform:none;box-shadow:none}
}

/* Small screens: remove expensive blur layers and make feed controls full width. */
@media(max-width:700px){
  .campus-feed-actions{width:100%;justify-content:flex-start}
  .campus-feed-link{flex:1;min-width:140px;text-align:center}
  .next-event-plaque,.reference-side-note,.float-chip{backdrop-filter:none}
  .search-modal,.more-sheet{backdrop-filter:none}
}

/* Content remains readable even if an external image is slow. */
.gallery-item img,.team-photo img,.club-logo img{background:var(--bg-card)}
img{max-width:100%}

/* Keep motion expressive, not constant, for accessibility and battery life. */
@media(prefers-reduced-motion:reduce){
  .loading .loadline i{transition:none;animation:none}
  .loading-steps i{transition:none}
  .campus-feed-card:hover,.campus-feed-link:hover{transform:none}
}


