/* ===== v18-4-product-overhaul.css ===== */
/* JYC V18.4 — product UI, phoenix, atmosphere, assistant, map and search pass */

/* Quiet atmosphere across the whole site. Light = warm dust/glints. Dark = stars + rare shooting stars. */
.site-atmosphere{position:fixed;inset:0;z-index:1;pointer-events:none;overflow:hidden;opacity:.8}
.app-frame>.site-atmosphere{z-index:0}
.site-star-field{position:absolute;inset:0}
.site-star{position:absolute;left:var(--x);top:var(--y);width:var(--s);height:var(--s);border-radius:50%;background:var(--accent-gold);opacity:.08;animation:siteTwinkle var(--d) ease-in-out infinite alternate;animation-delay:calc(var(--d) * -.45)}
.light-dust{position:absolute;inset:0;background:radial-gradient(circle at 14% 18%,color-mix(in srgb,var(--accent-gold) 5%,transparent),transparent 23%),radial-gradient(circle at 82% 66%,color-mix(in srgb,var(--accent-red) 3%,transparent),transparent 22%)}
.shooting-star{display:none;position:absolute;width:110px;height:1px;background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);opacity:.28;transform:rotate(-28deg);filter:blur(.2px)}
.shooting-one{top:18%;left:72%;animation:shootOne 8s ease-in-out infinite 1s}.shooting-two{top:43%;left:16%;animation:shootTwo 11s ease-in-out infinite 3.5s}
:root[data-theme=dark] .site-star{opacity:.42}.site-star:nth-child(3n){animation-duration:5.7s}.site-star:nth-child(5n){opacity:.25}
:root[data-theme=dark] .shooting-star{display:block}
:root[data-theme=light] .site-star{opacity:.10}.app-frame>*:not(.site-atmosphere){position:relative;z-index:2}
@keyframes siteTwinkle{from{opacity:.08;transform:scale(.7)}to{opacity:.72;transform:scale(1.2)}}
@keyframes shootOne{0%,68%,100%{opacity:0;transform:translate3d(0,0,0) rotate(-28deg)}72%{opacity:.34}84%{opacity:0;transform:translate3d(-190px,115px,0) rotate(-28deg)}}
@keyframes shootTwo{0%,73%,100%{opacity:0;transform:translate3d(0,0,0) rotate(-28deg)}77%{opacity:.25}90%{opacity:0;transform:translate3d(160px,95px,0) rotate(-28deg)}}

/* Phoenix: give the bird a calm central stage and push controls to the perimeter. */
.hero-art{isolation:isolate;overflow:visible!important}
.phoenix-3d-stage{width:min(700px,100%)!important;height:540px!important}
.phoenix-artwork{width:min(470px,68%)!important;max-width:470px;transform:translateZ(35px)}
