.phoenix-node{transform:translate(-50%,-50%)!important;padding:10px 15px!important;min-width:92px;text-align:center;font-size:9px!important;letter-spacing:.14em!important;background:color-mix(in srgb,var(--bg-card) 88%,transparent)!important;box-shadow:0 12px 30px rgba(0,0,0,.08)!important}
.phoenix-node:hover,.phoenix-node.active{transform:translate(-50%,-50%) scale(1.05)!important}
.phoenix-node.node-one{left:7%!important;top:30%!important}
.phoenix-node.node-two{right:auto!important;left:93%!important;top:30%!important}
.phoenix-node.node-three{right:auto!important;left:84%!important;bottom:auto!important;top:75%!important}
.phoenix-node.node-four{left:16%!important;top:75%!important}
.phoenix-route-hint{bottom:3%!important;font-size:8px!important;letter-spacing:.13em!important}
.float-chip{z-index:6!important;opacity:.72}
.reference-side-note{opacity:.5!important}
.next-event-plaque{max-width:260px!important;right:5%!important;top:7%!important}

/* Home is now a wayfinding experience, not a wall of orbit cards. */
.home-wayfinding{display:grid;grid-template-columns:.9fr 1.1fr;gap:30px;align-items:center;padding-top:70px;padding-bottom:70px}
.home-wayfinding h2{font:700 clamp(36px,5vw,64px)/.95 'Space Grotesk';letter-spacing:-.055em;margin:10px 0 14px}
.home-wayfinding p{color:var(--text-muted);line-height:1.7;max-width:620px}
.wayfinding-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.wayfinding-grid>a,.wayfinding-grid>button{border:1px solid var(--border-tech);background:var(--bg-card);color:var(--text-primary);border-radius:20px;padding:20px;text-align:left;display:grid;gap:6px;transition:.3s var(--ease)}
.wayfinding-grid>a:hover,.wayfinding-grid>button:hover{transform:translateY(-4px);border-color:var(--accent-gold);box-shadow:var(--shadow)}
.wayfinding-grid b{font:700 10px 'Space Grotesk';color:var(--accent-red)}
.wayfinding-grid strong{font:700 20px 'Space Grotesk'}.wayfinding-grid span{color:var(--text-muted);font-size:12px}

/* More panel: make assistant a first-class navigation utility. */
.more-sheet-grid{gap:9px!important}
.more-sheet-grid button,.more-sheet-link{min-height:74px!important;justify-content:center}
.more-sheet-grid button:focus-visible,.more-sheet-link:focus-visible,.nav-more-trigger:focus-visible,.search-trigger:focus-visible{outline:2px solid var(--accent-gold);outline-offset:3px}

/* JYC Assistant */
.assistant-overlay{position:fixed;inset:0;z-index:260;background:color-mix(in srgb,var(--bg-main) 82%,transparent);backdrop-filter:blur(20px);display:grid;place-items:center;padding:24px}
