.assistant-modal header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.assistant-modal h2{font:700 clamp(34px,5vw,52px)/.95 'Space Grotesk';margin:8px 0}.assistant-modal header p{margin:0;color:var(--text-muted);font-size:13px}
.assistant-chips{display:flex;gap:7px;overflow:auto;scrollbar-width:none}.assistant-chips button{white-space:nowrap;border:1px solid var(--border-tech);background:transparent;color:var(--text-muted);padding:9px 12px;border-radius:999px;cursor:pointer}.assistant-chips button:hover{color:var(--text-primary);border-color:var(--accent-gold)}
