.assistant-input{display:grid;grid-template-columns:1fr auto;gap:8px}.assistant-input input{width:100%;border:1px solid var(--border-tech);background:var(--bg-main);color:var(--text-primary);border-radius:15px;padding:14px 16px;outline:none}.assistant-input input:focus{border-color:var(--accent-gold);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent-gold) 9%,transparent)}.assistant-input .btn{min-width:90px}.assistant-note{color:var(--text-muted);font-size:10px}

/* Campus map: more useful than a raw iframe — event routing, quick places and clear hierarchy. */
.campus-map-page .compact-page-head{margin-bottom:20px}
.campus-map-toolbar{display:grid;grid-template-columns:1fr minmax(260px,.55fr);gap:10px;align-items:center}.campus-switch{display:flex;gap:7px;flex-wrap:wrap}.campus-switch button{border:1px solid var(--border-tech);background:var(--bg-card);color:var(--text-muted);border-radius:999px;padding:11px 15px;cursor:pointer}.campus-switch button.active{background:var(--accent-red);border-color:var(--accent-red);color:#fff}.map-search input{cursor:text!important}
.campus-map-layout{margin-top:14px!important}.campus-map-frame{position:relative;min-height:510px;margin:0!important;box-shadow:0 20px 60px rgba(0,0,0,.08)}.campus-map-frame iframe{filter:saturate(.82) contrast(1.02)}
.map-overlay-card{position:absolute;left:14px;bottom:14px;max-width:310px;display:grid;gap:5px;padding:14px 16px;border:1px solid var(--border-tech);border-radius:17px;background:color-mix(in srgb,var(--bg-card) 90%,transparent);backdrop-filter:blur(14px);box-shadow:var(--shadow)}.map-overlay-card strong{font:700 20px 'Space Grotesk'}.map-overlay-card small{color:var(--text-muted);line-height:1.45}.map-overlay-card div{display:flex;gap:12px;margin-top:4px}.map-overlay-card a{font-size:11px;font-weight:700;color:var(--accent-red)}
.campus-location-highlight{border:1px solid var(--border-tech)!important;background:linear-gradient(145deg,color-mix(in srgb,var(--accent-gold) 5%,var(--bg-card)),var(--bg-card))!important}.campus-location-highlight h2{font:700 36px 'Space Grotesk'!important;letter-spacing:-.04em}.campus-venue-list{max-height:390px;overflow:auto}.campus-venue-list button{cursor:pointer!important}.campus-venue-list button:hover,.campus-venue-list button.active{border-color:var(--accent-gold)!important;background:color-mix(in srgb,var(--bg-main) 88%,var(--accent-gold) 5%)!important}
.campus-map-page .campus-utility-grid{margin-top:14px}.campus-map-page .campus-utility-grid article{border:1px solid var(--border-tech);border-radius:20px;padding:22px;background:var(--bg-card)}.campus-map-page .campus-utility-grid h3{font:700 23px 'Space Grotesk'}.campus-map-page .campus-utility-grid p{color:var(--text-muted);line-height:1.6}.campus-map-page .campus-utility-grid a,.campus-map-page .campus-utility-grid button{color:var(--accent-red);font-weight:700;border:0;background:none;padding:0;cursor:pointer}

