.guide-tool-card{min-height:230px!important}.guide-tool-card:nth-child(2){background:linear-gradient(145deg,color-mix(in srgb,var(--accent-gold) 5%,var(--bg-card)),var(--bg-card))}.guide-tool-card:nth-child(3){background:linear-gradient(145deg,color-mix(in srgb,var(--accent-red) 5%,var(--bg-card)),var(--bg-card))}

/* Creator identity */
.creator-card{grid-column:span 1}.creator-card-head{display:flex;align-items:center;gap:13px;margin:14px 0 8px}.creator-avatar-large{width:58px;height:58px;border-radius:18px;display:grid;place-items:center;background:linear-gradient(145deg,var(--accent-red),var(--accent-gold));color:#fff;font:800 16px 'Space Grotesk';box-shadow:0 10px 30px color-mix(in srgb,var(--accent-red) 18%,transparent)}.creator-card h3{margin:0!important}.creator-card-head p{margin:4px 0!important}.creator-email{display:inline-block;margin-top:12px;color:var(--accent-red);font-size:12px;font-weight:700}
