@media(max-width:760px){.site-atmosphere{opacity:.62}.shooting-star{display:none!important}.phoenix-3d-stage{height:360px!important}.phoenix-artwork{width:min(330px,78%)!important}.phoenix-artwork img{max-height:270px!important}.phoenix-node{min-width:78px!important;padding:8px 10px!important;font-size:7px!important}.phoenix-node.node-one{left:9%!important;top:27%!important}.phoenix-node.node-two{left:91%!important;top:27%!important}.phoenix-node.node-three{left:82%!important;top:79%!important}.phoenix-node.node-four{left:18%!important;top:79%!important}.reference-side-note,.float-chip{display:none!important}.next-event-plaque{right:50%!important;top:2%!important;transform:translateX(50%)!important;max-width:220px!important}.wayfinding-grid{grid-template-columns:1fr}.assistant-overlay{padding:10px}.assistant-modal{border-radius:22px;padding:16px;max-height:92vh}.assistant-messages{min-height:230px}.assistant-message{max-width:94%}.creator-card{grid-column:auto}.home-wayfinding{padding-top:48px;padding-bottom:48px}}
@media(prefers-reduced-motion:reduce){.site-star,.shooting-star{animation:none!important}.site-atmosphere{display:none}.phoenix-node:hover,.phoenix-node.active{transform:translate(-50%,-50%)!important}.wayfinding-grid>a:hover,.wayfinding-grid>button:hover{transform:none}}
.selected-venue-card{margin-top:8px;padding:13px;border:1px solid color-mix(in srgb,var(--accent-gold) 28%,var(--border-tech));border-radius:15px;background:color-mix(in srgb,var(--accent-gold) 4%,var(--bg-main));display:grid;gap:5px}.selected-venue-card strong{font:700 17px 'Space Grotesk'}.selected-venue-card small{color:var(--text-muted);line-height:1.45}.selected-venue-card div{display:flex;gap:12px;flex-wrap:wrap;margin-top:3px}.selected-venue-card a{font-size:10px;font-weight:700;color:var(--accent-red)}

/* V18.5 — Admin AI Copilot + editorial workspace polish */
