.admin-ai-bar>div:first-child{display:grid;gap:3px}.admin-ai-bar strong{font:700 16px 'Space Grotesk';letter-spacing:-.02em}.admin-ai-bar small{color:var(--text-muted);font-size:10px;line-height:1.4}.admin-ai-actions{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.admin-ai-actions button{border:1px solid var(--border-tech);background:var(--bg-main);color:var(--text-primary);border-radius:999px;padding:9px 12px;font:700 10px 'Space Grotesk';letter-spacing:.03em;cursor:pointer;transition:.2s}.admin-ai-actions button:first-child{border-color:color-mix(in srgb,var(--accent-gold) 45%,var(--border-tech));background:color-mix(in srgb,var(--accent-gold) 8%,var(--bg-main))}.admin-ai-actions button:hover:not(:disabled){transform:translateY(-1px);border-color:var(--accent-gold);box-shadow:var(--shadow)}.admin-ai-actions button:disabled{opacity:.5;cursor:not-allowed}
