/* ===== v19-product-finish.css ===== */
/* JYC V19 PRODUCT FINISH — motion, phoenix, cards, context, cursor and light mode. */

/* Center the SEO/search-facing hero copy instead of allowing wide layouts to hug the viewport edge. */
.seo-topic-panel{display:grid!important;justify-items:center!important;text-align:center!important;max-width:1280px;margin-left:auto!important;margin-right:auto!important;padding-left:clamp(24px,5vw,80px)!important;padding-right:clamp(24px,5vw,80px)!important}
.seo-topic-panel h2,.seo-topic-panel p{margin-left:auto!important;margin-right:auto!important;max-width:920px!important}
.seo-topic-links{justify-content:center!important}

/* Whole feed cards are interaction surfaces, not a tiny Open button. */
.campus-feed-card{position:relative;cursor:pointer;outline:none;transition:transform .45s var(--ease),border-color .35s,box-shadow .45s,background .35s!important}
.campus-feed-card:hover,.campus-feed-card:focus-visible{transform:translateY(-7px)!important;border-color:var(--accent-gold)!important;box-shadow:0 24px 70px color-mix(in srgb,var(--text-primary) 10%,transparent)!important}
.campus-feed-card:focus-visible{outline:2px solid var(--accent-gold);outline-offset:4px}
.campus-feed-card .feed-open{pointer-events:none}

/* More sheet: stronger hierarchy + context, without duplicate My JYC cards. */
.more-sheet{background:linear-gradient(145deg,color-mix(in srgb,var(--bg-card) 96%,var(--accent-gold) 4%),var(--bg-card))!important}
.more-sheet-context{margin-top:8px}
.more-context-card{display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center;padding:18px;border:1px solid var(--border-tech);border-radius:18px;background:color-mix(in srgb,var(--bg-main) 55%,var(--bg-card))}
.more-context-card b{font:700 17px 'Space Grotesk'}
.more-context-card p{margin:7px 0 0;color:var(--text-muted);line-height:1.55;font-size:12px;max-width:560px}
.more-context-card button{border:1px solid var(--border-tech);background:var(--text-primary);color:var(--bg-main);border-radius:999px;padding:10px 13px;font-weight:800;cursor:pointer}

/* Phoenix is a layered scene: primary bird + echo bird + rings + particles + directional light. */
.phoenix-3d-stage{isolation:isolate!important;overflow:visible!important}
.phoenix-energy-field{position:absolute;inset:9%;border-radius:50%;background:radial-gradient(circle at 50% 55%,color-mix(in srgb,var(--accent-red) 15%,transparent),transparent 48%),radial-gradient(circle at 50% 45%,color-mix(in srgb,var(--accent-gold) 7%,transparent),transparent 68%);filter:blur(3px);animation:phoenixEnergy 7s ease-in-out infinite alternate;pointer-events:none;z-index:0}
.phoenix-ghost-bird{position:absolute;width:min(420px,66%);aspect-ratio:626/475;display:grid;place-items:center;opacity:.12;filter:blur(.2px) drop-shadow(0 0 28px color-mix(in srgb,var(--accent-red) 22%,transparent));transform:translate3d(-42px,-34px,0) scale(.9);z-index:1;animation:phoenixGhostFloat 9s ease-in-out infinite}
.phoenix-ghost-bird img{width:100%;height:auto;object-fit:contain}
.phoenix-3d-core{z-index:4!important}
.phoenix-ring-label{position:absolute;bottom:-3%;left:50%;transform:translateX(-50%);white-space:nowrap;color:color-mix(in srgb,var(--accent-gold) 72%,var(--text-primary));font:700 8px 'Space Grotesk';letter-spacing:.28em;text-shadow:0 5px 18px color-mix(in srgb,var(--accent-red) 22%,transparent);opacity:.82}
.phoenix-orbit{z-index:2!important;opacity:.7}
.phoenix-orbit.orbit-d{position:absolute;width:58%;height:95%;border-color:color-mix(in srgb,var(--accent-red) 18%,var(--accent-gold) 10%,transparent);border-radius:50%;transform:rotate(38deg);animation:phoenixOrbitD 30s linear infinite}
.phoenix-particle{z-index:3!important;animation:phoenixParticle 5s ease-in-out infinite!important;animation-delay:calc(var(--i) * -0.22s)!important}
.phoenix-spark{position:absolute;width:3px;height:3px;border-radius:50%;background:var(--accent-gold);box-shadow:0 0 12px color-mix(in srgb,var(--accent-gold) 55%,transparent);left:calc(20% + var(--spark) * 9%);top:calc(18% + (var(--spark) % 4) * 16%);z-index:5;animation:phoenixSpark 2.6s ease-in-out infinite;animation-delay:calc(var(--spark) * .31s)}
.phoenix-streak{position:absolute;width:90px;height:1px;background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);opacity:.5;z-index:2;transform:rotate(-28deg);animation:phoenixStreak 6s ease-in-out infinite}
.streak-a{left:7%;top:24%}.streak-b{right:4%;top:63%;animation-delay:2.5s}
@keyframes phoenixEnergy{from{transform:scale(.96);opacity:.55}to{transform:scale(1.05);opacity:.9}}
@keyframes phoenixGhostFloat{0%,100%{transform:translate3d(-42px,-34px,0) scale(.9);opacity:.09}50%{transform:translate3d(-30px,-48px,0) scale(.95);opacity:.17}}
@keyframes phoenixOrbitD{from{transform:rotate(38deg)}to{transform:rotate(398deg)}}
@keyframes phoenixParticle{0%,100%{opacity:.15;transform:translate3d(0,0,0) scale(.8)}50%{opacity:.8;transform:translate3d(calc((var(--i) % 5) * 4px),-12px,0) scale(1.1)}}
@keyframes phoenixSpark{0%,100%{opacity:.12;transform:scale(.6)}50%{opacity:.95;transform:scale(1.7)}}
@keyframes phoenixStreak{0%,100%{opacity:0;transform:translateX(-30px) rotate(-28deg)}35%,65%{opacity:.55}50%{transform:translateX(30px) rotate(-28deg)}}

/* Better opening: the phoenix leads the reveal instead of rings doing all the work. */
.loading:before,.loading:after{animation:none!important}
.loading{background:radial-gradient(circle at 50% 46%,color-mix(in srgb,var(--accent-red) 9%,transparent),transparent 28%),var(--bg-main)!important}
.loading-center{animation:bootCenterIn .85s var(--ease) both}
.loading-mark{position:relative!important;overflow:visible}
.loading-mark:before{content:"";position:absolute;inset:-18px;border:1px solid color-mix(in srgb,var(--accent-gold) 28%,transparent);border-radius:50%;animation:bootBirdRing 2.4s ease-out infinite}
.loading-mark:after{content:"";position:absolute;width:120px;height:1px;left:50%;top:50%;background:linear-gradient(90deg,transparent,var(--accent-red),transparent);transform:translate(-50%,-50%);animation:bootSweep 1.8s ease-in-out infinite}
.loading-logo img,.loading-mark img{animation:bootBird .95s cubic-bezier(.16,1,.3,1) both!important}
@keyframes bootCenterIn{from{opacity:0;transform:translateY(24px) scale(.96)}to{opacity:1;transform:none}}
@keyframes bootBird{from{opacity:0;transform:scale(.55) rotate(-8deg);filter:blur(7px)}to{opacity:1;transform:none;filter:none}}
@keyframes bootBirdRing{0%{transform:scale(.72);opacity:0}35%{opacity:.65}100%{transform:scale(1.25);opacity:0}}
@keyframes bootSweep{0%,100%{opacity:0;transform:translate(-50%,-50%) scaleX(.2)}50%{opacity:.8;transform:translate(-50%,-50%) scaleX(1)}}

/* Custom cursor: restored as a calm red/gold instrument on precise pointers. */
@media (hover:hover) and (pointer:fine){
  body.jyc-custom-cursor,body.jyc-custom-cursor *{cursor:none!important}
  .jyc-cursor-dot{width:6px!important;height:6px!important;background:var(--accent-red)!important;box-shadow:0 0 15px color-mix(in srgb,var(--accent-red) 55%,transparent)!important;opacity:1!important}
  .jyc-cursor-ring{width:32px!important;height:32px!important;border-color:color-mix(in srgb,var(--accent-gold) 70%,var(--accent-red))!important;opacity:.82!important;transition:width .22s var(--ease),height .22s var(--ease),border-color .2s,background .2s,box-shadow .2s!important}
  .jyc-cursor-ring.is-hover{width:48px!important;height:48px!important;border-color:var(--accent-red)!important;background:color-mix(in srgb,var(--accent-red) 7%,transparent)!important;box-shadow:0 0 34px color-mix(in srgb,var(--accent-red) 20%,transparent)!important}
}

/* Light mode gets atmosphere, not a washed-out copy of dark mode. */
:root[data-theme="light"] body{background:radial-gradient(circle at 15% 8%,rgba(191,156,111,.14),transparent 26rem),radial-gradient(circle at 86% 18%,rgba(168,36,32,.055),transparent 25rem),linear-gradient(180deg,#f8f3e7,#f4efe4 58%,#f8f4ea)!important}
:root[data-theme="light"] body:after{opacity:.12!important;background-image:radial-gradient(circle,rgba(126,92,48,.55) 0 1px,transparent 1.5px)!important}
