.more-context-card{border:1px solid color-mix(in srgb,var(--accent-gold) 25%,var(--border-tech))!important;background:linear-gradient(135deg,color-mix(in srgb,var(--accent-gold) 5%,var(--bg-card)),var(--bg-card))!important}
.more-context-card p{max-width:620px!important;line-height:1.65!important}

/* Admin labels stay readable; the sidebar is intentionally not collapsible in the public product. */
.admin-shell{grid-template-columns:276px minmax(0,1fr)!important}
.admin-side{width:276px!important;min-width:276px!important}
.admin-brand-row{grid-template-columns:1fr!important}
.admin-nav-group button{grid-template-columns:24px minmax(0,1fr) auto!important;min-height:42px!important}
.admin-nav-label{display:block!important;min-width:0!important;width:auto!important;max-width:none!important;overflow:visible!important;text-overflow:clip!important;white-space:nowrap!important;font:700 11px/1.2 'DM Sans',sans-serif!important;letter-spacing:.01em!important}
.admin-nav-group>span{font-size:9px!important;letter-spacing:.2em!important}
.admin-brand-row .admin-collapse{display:none!important}

/* Calendar: JYC first, academic context alongside it, saved events clearly surfaced. */
.calendar-mode-tabs{display:flex!important;gap:8px!important;flex-wrap:wrap!important}
.calendar-mode-tabs button{min-height:44px!important;padding:10px 16px!important;border:1px solid var(--border-tech)!important;border-radius:999px!important;background:transparent!important;color:var(--text-muted)!important;font-weight:800!important;transition:.25s var(--ease)!important}
.calendar-mode-tabs button:hover{transform:translateY(-2px)!important;border-color:var(--accent-gold)!important}
.calendar-mode-tabs button.active{background:var(--accent-red)!important;border-color:var(--accent-red)!important;color:#fff!important;box-shadow:0 10px 25px color-mix(in srgb,var(--accent-red) 18%,transparent)!important}
.calendar-jyc-saved{border-color:color-mix(in srgb,var(--accent-red) 38%,var(--border-tech))!important;background:color-mix(in srgb,var(--accent-red) 7%,var(--bg-card))!important}
.calendar-jyc-saved::first-letter{color:var(--accent-red)!important}
.calendar-event-list{margin-top:28px;border-top:1px solid var(--border-tech)}
.calendar-list-head{display:flex;justify-content:space-between;align-items:end;gap:14px;padding:22px 0 12px}
.calendar-list-head h3{font:700 28px 'Space Grotesk';margin:6px 0 0}
.calendar-list-head>small{color:var(--text-muted)}
.calendar-event-row{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:16px 0;border-bottom:1px solid var(--border-tech)}
.calendar-event-row>div:first-child{display:grid;gap:4px}.calendar-event-row span{font:700 10px 'Space Grotesk';letter-spacing:.1em;color:var(--accent-red)}.calendar-event-row strong{font:700 20px 'Space Grotesk'}.calendar-event-row small{color:var(--text-muted)}
.calendar-event-row>div:last-child{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.calendar-event-row button{border:1px solid var(--border-tech);background:var(--bg-card);color:var(--text-primary);border-radius:999px;padding:9px 12px;font-weight:700;cursor:pointer}.calendar-event-row button:hover{border-color:var(--accent-gold);transform:translateY(-1px)}
.calendar-event-row.is-saved{padding-left:14px;border-left:3px solid var(--accent-red);background:linear-gradient(90deg,color-mix(in srgb,var(--accent-red) 4%,transparent),transparent)}

/* Map gets a compact control layer before the large map. */
.campus-map-summary{display:grid;grid-template-columns:minmax(0,1.7fr) .65fr .8fr auto;gap:10px;align-items:stretch;margin:14px 0 18px}
.campus-map-summary>div,.campus-map-summary>a{border:1px solid var(--border-tech);border-radius:18px;background:var(--bg-card);padding:15px 17px}
.campus-map-summary>div:first-child{display:grid;gap:4px}.campus-map-summary>div:first-child strong{font:700 23px 'Space Grotesk'}.campus-map-summary>div:first-child small{color:var(--text-muted)}
.campus-map-summary>div:not(:first-child){display:grid;align-content:center;gap:3px}.campus-map-summary b{font:700 24px 'Space Grotesk'}.campus-map-summary span:not(.eyebrow){color:var(--text-muted);font-size:10px}.campus-map-summary>a{display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--text-primary)}.campus-map-summary>a:hover{border-color:var(--accent-gold);transform:translateY(-2px)}
.map-search{position:relative}.map-search>button{border:0;background:none;color:var(--text-muted);cursor:pointer;font-size:20px;line-height:1;padding:0 7px}

/* Better light mode: warm paper + restrained red/gold atmosphere. */
:root[data-theme="light"] .site-atmosphere{opacity:.62!important}
:root[data-theme="light"] .bird-function-card,:root[data-theme="light"] .student-tool-card,:root[data-theme="light"] .story-link{box-shadow:0 18px 55px rgba(90,62,31,.07)!important}
:root[data-theme="light"] .bird-function-card{background:linear-gradient(145deg,rgba(255,250,239,.95),rgba(249,244,233,.92))!important}
:root[data-theme="light"] .student-tool-card{background:rgba(255,252,245,.88)!important}
:root[data-theme="light"] .onboarding-overlay{background:rgba(56,42,28,.28)!important}
:root[data-theme="light"] .onboarding-card-rich{background:rgba(255,251,242,.96)!important;box-shadow:0 30px 100px rgba(70,50,30,.18)!important}

@media(max-width:1050px){
 .bird-trio-grid{grid-template-columns:1fr 1fr}.bird-function-card:last-child{grid-column:1/-1}
 .student-tools-grid{grid-template-columns:repeat(3,1fr)}
 .student-tool-card:last-child{grid-column:auto}
 .campus-map-summary{grid-template-columns:1fr 1fr}.campus-map-summary>div:first-child{grid-column:1/-1}
}
@media(max-width:760px){
 .brand-mark.bird-mark img{width:42px!important;height:42px!important}.footer-logo-lockup.bird-mark{width:58px!important;height:58px!important}.footer-logo-lockup.bird-mark img{width:55px!important;height:55px!important}
 .onboarding-overlay{padding:10px!important}.onboarding-card-rich{width:min(100%,520px)!important;max-height:calc(100dvh - 20px)!important;padding:20px!important}.onboarding-bird{width:92px!important;height:74px!important}.onboarding-card-rich h2{font-size:31px!important}
 .bird-trio-grid{grid-template-columns:1fr}.bird-function-card:last-child{grid-column:auto}.bird-function-card{min-height:330px}.bird-function-index{margin-top:115px}.bird-function-art{width:155px;height:125px}
 .student-tools-grid{grid-template-columns:1fr 1fr}.student-tool-card{min-height:132px}.student-tool-card:last-child{grid-column:1/-1}
 .campus-map-summary{grid-template-columns:1fr 1fr}.campus-map-summary>div:first-child,.campus-map-summary>a{grid-column:1/-1}
 .calendar-event-row{display:grid;gap:12px}.calendar-event-row>div:last-child{justify-content:flex-start}
 .admin-shell{grid-template-columns:1fr!important}.admin-side{display:none!important}
}
@media(prefers-reduced-motion:reduce){.bird-function-card,.student-tool-card,.story-link,.campus-map-summary>a{transition:none!important}.onboarding-bird{animation:none!important}}


/* ===== v19.7-jyc-club.css ===== */
/* JYC 18.9.7 — CLUBHOUSE REDESIGN
   Public-facing rule: JYC is the product. Utilities never lead the experience.
   CSS-native motion only; no new dependency. */

:root{
  --jyc-red:#d92d2d;
  --jyc-red-deep:#9e2027;
  --jyc-gold:#d7b47a;
  --jyc-cream:#fff4d7;
  --jyc-night:#08090b;
  --jyc-panel:#131116;
  --jyc-line:rgba(215,180,122,.25);
  --jyc-soft:rgba(255,244,215,.66);
}

/* --- Public navigation: bird mark only, no accidental wordmark --- */
.nav .brand{width:62px!important;height:62px!important;padding:0!important;border-radius:50%!important;background:transparent!important;box-shadow:none!important;border:0!important}
.nav .brand .brand-mark{width:58px!important;height:58px!important;border:0!important;background:transparent!important;box-shadow:none!important;border-radius:0!important}
.nav .brand .brand-mark img{width:54px!important;height:54px!important;object-fit:contain!important;filter:drop-shadow(0 7px 18px rgba(217,45,45,.2))!important;transition:transform .5s cubic-bezier(.2,.8,.2,1),filter .4s!important}
.nav .brand:hover .brand-mark img{transform:translateY(-2px) rotate(-2deg) scale(1.06)!important;filter:drop-shadow(0 11px 25px rgba(217,45,45,.32))!important}

/* --- The public page should read like an editorial club site, not a dashboard --- */
.jyc-club-editorial-home{overflow:hidden;background:var(--bg-main)}
.jyc-club-editorial-home .section{position:relative}
.jyc-club-editorial-home .section:before{content:"";position:absolute;left:0;right:0;top:0;height:1px;background:linear-gradient(90deg,transparent,var(--border-tech),transparent);opacity:.65}
.jyc-club-editorial-home .section-rail{margin-bottom:42px}
.jyc-club-editorial-home .section-rail h2{max-width:900px}

/* --- Hero: one bird, three supporting flight paths; no orbit dependency --- */
.club-hero{min-height:calc(100svh - 84px)!important;grid-template-columns:minmax(0,.86fr) minmax(500px,1.14fr)!important;gap:30px!important;padding-top:clamp(64px,9vw,120px)!important;padding-bottom:60px!important;background:
 radial-gradient(circle at 82% 48%,rgba(217,45,45,.13),transparent 26%),
 radial-gradient(circle at 16% 80%,rgba(215,180,122,.07),transparent 24%),
 linear-gradient(180deg,rgba(255,255,255,.01),transparent 40%)!important}
.club-hero-copy{max-width:720px!important;align-self:center!important}
.club-hero h1{font-size:clamp(76px,9.5vw,154px)!important;line-height:.79!important;letter-spacing:-.1em!important;margin:30px 0 32px!important}
.club-hero h1 em{color:var(--jyc-red)!important;font-family:Georgia,serif!important}
.club-hero-copy>p{font-size:19px!important;max-width:600px!important}
.club-hero-signature{display:flex;align-items:center;gap:11px;margin-top:40px;color:var(--text-muted);font:800 9px/1 var(--club-display);letter-spacing:.18em}
.club-hero-signature i{width:4px;height:4px;border-radius:50%;background:var(--jyc-red);box-shadow:0 0 12px rgba(217,45,45,.6)}
.club-hero-art-redesigned{min-height:650px!important;isolation:isolate!important;transform:translate3d(var(--hero-mx,0),var(--hero-my,0),0);transition:transform .45s cubic-bezier(.2,.8,.2,1)!important}
.club-hero-art-redesigned:before{width:min(48vw,650px)!important;height:min(48vw,650px)!important;background:radial-gradient(circle,rgba(217,45,45,.18),transparent 58%)!important;filter:blur(30px)!important;animation:heroBreath 6s ease-in-out infinite!important}
.hero-bird-main,.hero-bird-shadow,.hero-bird-ghost{position:absolute;left:50%;top:47%;width:min(43vw,510px);height:min(43vw,510px);transform:translate(-50%,-50%);display:grid;place-items:center;pointer-events:none}
.hero-bird-main{z-index:4;animation:birdFloat 5.8s ease-in-out infinite}
.hero-bird-main img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 28px 38px rgba(0,0,0,.34)) drop-shadow(0 0 26px rgba(217,45,45,.25))}
.hero-bird-shadow{z-index:2;opacity:.16;transform:translate(-42%,-44%) scale(1.08);filter:blur(14px);animation:birdShadow 5.8s ease-in-out infinite}
.hero-bird-shadow img{width:100%;height:100%;object-fit:contain;filter:brightness(.2) sepia(1) saturate(6)}
.hero-bird-ghost{z-index:1;opacity:.09;transform:translate(-57%,-51%) scale(.86) rotate(-8deg);animation:birdGhost 9s ease-in-out infinite}
.hero-bird-ghost img{width:100%;height:100%;object-fit:contain;filter:blur(1px) saturate(.7)}
.phoenix-flight-line{position:absolute;z-index:3;left:8%;width:84%;height:1px;background:linear-gradient(90deg,transparent,rgba(215,180,122,.0),rgba(215,180,122,.6),rgba(217,45,45,.35),transparent);transform-origin:center;opacity:.45}
.flight-one{top:43%;transform:rotate(-16deg);animation:flightSweep 5.5s ease-in-out infinite}
.flight-two{top:55%;transform:rotate(11deg);opacity:.25;animation:flightSweep 7s ease-in-out infinite reverse}
.hero-bird-caption{position:absolute;z-index:5;left:50%;bottom:8%;transform:translateX(-50%);display:grid;gap:4px;text-align:center;pointer-events:none}
.hero-bird-caption span{font:900 9px var(--club-display);letter-spacing:.32em;color:var(--jyc-red)}
.hero-bird-caption strong{font:800 10px var(--club-display);letter-spacing:.22em;color:var(--text-primary)}
.hero-bird-node{position:absolute;z-index:7;min-width:126px;padding:13px 15px;text-align:left;border:1px solid var(--border-tech);border-radius:15px;background:color-mix(in srgb,var(--bg-card) 88%,transparent);backdrop-filter:blur(14px);color:var(--text-primary);box-shadow:0 20px 50px rgba(0,0,0,.16);cursor:pointer;transition:transform .35s cubic-bezier(.2,.8,.2,1),border-color .25s,background .25s}
.hero-bird-node:hover{transform:translateY(-6px) scale(1.02);border-color:var(--jyc-gold);background:color-mix(in srgb,var(--bg-card) 96%,transparent)}
.hero-bird-node small{display:block;color:var(--jyc-red);font:800 8px var(--club-display);letter-spacing:.2em;margin-bottom:4px}.hero-bird-node strong{display:block;font:800 17px var(--club-display)}.hero-bird-node span{display:block;margin-top:4px;color:var(--text-muted);font-size:10px}
.node-clubs{left:4%;top:28%}.node-events{right:3%;top:35%}.node-team{right:11%;bottom:17%}
.club-hero-art-redesigned .club-next-event{right:0!important;bottom:2%!important;width:260px!important;z-index:8!important}

@keyframes birdFloat{0%,100%{transform:translate(-50%,-50%) translateY(0) rotate(-1deg)}50%{transform:translate(-50%,-50%) translateY(-13px) rotate(1deg)}}
@keyframes birdShadow{0%,100%{transform:translate(-42%,-44%) scale(1.08);opacity:.14}50%{transform:translate(-42%,-40%) scale(1.02);opacity:.2}}
@keyframes birdGhost{0%,100%{transform:translate(-57%,-51%) scale(.86) rotate(-8deg);opacity:.07}50%{transform:translate(-61%,-47%) scale(.91) rotate(-3deg);opacity:.13}}
@keyframes flightSweep{0%,100%{opacity:.12;transform:scaleX(.8) rotate(-16deg)}50%{opacity:.55;transform:scaleX(1.06) rotate(-16deg)}}
@keyframes heroBreath{0%,100%{opacity:.45;transform:scale(.94)}50%{opacity:.75;transform:scale(1.04)}}

/* --- Story band --- */
.club-intro-band{align-items:center!important;padding-top:110px!important;padding-bottom:92px!important}
.club-intro-band>div:first-child{max-width:900px}
.club-intro-band h2{font-size:clamp(52px,7vw,92px)!important}
.club-intro-copy{max-width:650px;color:var(--text-muted);font-size:17px;line-height:1.7;margin:24px 0 0}
.club-story-button{min-width:250px!important}

/* --- Communities: make clubs feel like the main product --- */
.club-communities{padding-top:105px!important;padding-bottom:105px!important}
.club-showcase-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:18px!important}
.club-showcase-grid .club-card{min-height:255px!important;border-radius:24px!important;position:relative;overflow:hidden}
.club-showcase-grid .club-card:after{content:"";position:absolute;inset:auto -20% -40% 30%;height:70%;background:radial-gradient(circle,rgba(217,45,45,.12),transparent 65%);pointer-events:none}
.club-showcase-grid .club-card:hover{transform:translateY(-8px) rotateX(1deg)!important}

/* --- Three-bird system: clearly distinct roles, not duplicate cards --- */
.club-birds{padding-top:108px!important;padding-bottom:110px!important}
.bird-trio-head{max-width:850px}
.bird-trio-head h2{font-size:clamp(48px,6vw,82px)!important}
.bird-trio-grid{gap:18px!important}
.bird-function-card{min-height:420px!important;border-radius:28px!important;background:linear-gradient(150deg,color-mix(in srgb,var(--bg-card) 96%,transparent),color-mix(in srgb,var(--jyc-red) 4%,var(--bg-card)))!important}
.bird-function-card:nth-child(2){background:linear-gradient(150deg,color-mix(in srgb,var(--jyc-red) 10%,var(--bg-card)),var(--bg-card))!important}
.bird-function-card:nth-child(3){background:linear-gradient(150deg,color-mix(in srgb,var(--jyc-gold) 7%,var(--bg-card)),var(--bg-card))!important}
.bird-function-art{width:230px!important;height:180px!important;top:34px!important;right:24px!important;left:auto!important;transform:rotate(-2deg)!important}
.bird-function-card:nth-child(2) .bird-function-art{transform:rotate(5deg) scale(.9)!important}.bird-function-card:nth-child(3) .bird-function-art{transform:rotate(-6deg) scale(.84)!important}
.bird-function-card:hover .bird-function-art{transform:translate(-8px,-8px) rotate(-3deg) scale(1.05)!important}
.bird-function-card:nth-child(2):hover .bird-function-art{transform:translate(-8px,-8px) rotate(7deg) scale(.96)!important}.bird-function-card:nth-child(3):hover .bird-function-art{transform:translate(-8px,-8px) rotate(-8deg) scale(.9)!important}
.bird-function-art img{filter:drop-shadow(0 16px 26px rgba(217,45,45,.28))!important}

/* --- People + gallery are storytelling, not dashboard panels --- */
.club-team-strip,.club-gallery-strip,.club-fests-band{padding-top:104px!important;padding-bottom:104px!important}
.club-team-preview{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.club-team-preview>button{min-height:280px!important;border:1px solid var(--border-tech)!important;border-radius:24px!important;background:var(--bg-card)!important;overflow:hidden!important;text-align:left!important;padding:0!important;display:flex!important;flex-direction:column!important;justify-content:flex-end!important;transition:transform .4s,border-color .3s!important}
.club-team-preview>button:hover{transform:translateY(-7px)!important;border-color:var(--jyc-gold)!important}
.club-team-preview .team-preview-photo{height:205px!important;width:100%!important;display:grid!important;place-items:center!important;background:radial-gradient(circle at 50% 20%,rgba(217,45,45,.18),transparent 60%),#0e0e11!important}
.club-team-preview .team-preview-photo img{max-width:100%!important;max-height:100%!important;object-fit:cover!important}
.club-team-preview>button>span:last-child{padding:17px 18px 20px!important;display:grid!important;gap:5px!important}.club-team-preview strong{font-size:18px!important}.club-team-preview small{color:var(--text-muted)!important}
.club-gallery-strip .gallery-grid,.club-gallery-strip .gallery-masonry{border-radius:24px;overflow:hidden}

/* --- Closing CTA becomes a club poster, not a generic product card --- */
.club-cta{margin-top:40px!important;margin-bottom:80px!important;border:1px solid var(--jyc-line)!important;border-radius:34px!important;min-height:390px!important;overflow:hidden!important;background:radial-gradient(circle at 16% 50%,rgba(217,45,45,.2),transparent 35%),linear-gradient(120deg,#151016,#0a0a0c)!important;position:relative!important}
.club-cta-mark{width:330px!important;height:330px!important;opacity:.78!important}.club-cta-mark img{width:100%!important;height:100%!important;object-fit:contain!important;filter:drop-shadow(0 30px 40px rgba(217,45,45,.24))!important}
.club-cta h2{font-size:clamp(44px,6vw,80px)!important}

/* --- More sheet: club directory, not utility drawer --- */
.jyc-more-club-sheet{background:linear-gradient(145deg,#17131a,#0d0d10)!important;border-color:rgba(215,180,122,.32)!important}
.jyc-more-club-sheet .more-sheet-head h3{font-size:clamp(34px,5vw,52px)!important;letter-spacing:-.06em!important}
.jyc-more-club-sheet .more-sheet-grid button,.jyc-more-club-sheet .more-sheet-grid .more-sheet-link{min-height:110px!important;border-radius:20px!important;transition:transform .3s,border-color .25s,background .25s!important}
.jyc-more-club-sheet .more-sheet-grid button:hover,.jyc-more-club-sheet .more-sheet-grid .more-sheet-link:hover{transform:translateY(-4px)!important;border-color:var(--jyc-gold)!important}
.more-context-card{display:grid!important;grid-template-columns:1fr auto!important;gap:22px!important;align-items:center!important;padding:24px!important}
.more-context-card b{font-size:20px!important}.more-context-card button{white-space:nowrap!important}

/* --- Guide: club handbook, not a student-support portal --- */
.jyc-guide-page{padding-bottom:120px!important}
.guide-hero{position:relative!important;overflow:hidden!important;border:1px solid var(--border-tech)!important;border-radius:32px!important;padding:70px 60px!important;background:radial-gradient(circle at 86% 40%,rgba(217,45,45,.18),transparent 32%),linear-gradient(135deg,color-mix(in srgb,var(--bg-card) 97%,transparent),rgba(217,45,45,.03))!important}
.guide-hero-bird{position:absolute;right:6%;top:12%;width:min(33vw,350px);height:min(33vw,350px);opacity:.3;animation:guideBird 7s ease-in-out infinite;pointer-events:none}.guide-hero-bird img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 20px 30px rgba(217,45,45,.28))}.guide-hero h1{position:relative;z-index:2;max-width:900px;font-size:clamp(54px,7vw,94px)!important;line-height:.93!important;letter-spacing:-.075em!important}.guide-hero p{position:relative;z-index:2;max-width:760px!important;font-size:18px!important;line-height:1.7!important}.guide-actions{position:relative;z-index:3}
@keyframes guideBird{0%,100%{transform:translate3d(0,0,0) rotate(-2deg)}50%{transform:translate3d(-14px,-12px,0) rotate(2deg)}}
.guide-map{position:relative;display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0 18px;padding:24px 0}.guide-map-line{position:absolute;left:10%;right:10%;top:50%;height:1px;background:linear-gradient(90deg,transparent,var(--jyc-red),var(--jyc-gold),transparent);opacity:.45}.guide-map>div{position:relative;z-index:1;border:1px solid var(--border-tech);border-radius:20px;padding:22px;background:var(--bg-card);display:grid;gap:7px}.guide-map span{color:var(--jyc-red);font:800 9px var(--club-display);letter-spacing:.2em}.guide-map strong{font:800 15px var(--club-display)}.guide-map small{color:var(--text-muted)}
.guide-steps{display:grid;gap:0;border-top:1px solid var(--border-tech)}
