/* ===== v19.8-contact-nav.css ===== */
/* JYC 18.9.8 — navigation, contact and motion polish.
   Interaction patterns are inspired by open-source micro-interaction work;
   implementation is dependency-free CSS so the site stays fast and owned by JYC. */

.nav nav button{position:relative;isolation:isolate;transition:color .28s ease,transform .28s cubic-bezier(.2,.8,.2,1)}
.nav nav button::after{content:"";position:absolute;left:18%;right:18%;bottom:6px;height:2px;border-radius:999px;background:linear-gradient(90deg,var(--jyc-red),var(--jyc-gold));transform:scaleX(0);transform-origin:center;transition:transform .32s cubic-bezier(.2,.8,.2,1);opacity:.9}
.nav nav button:hover{transform:translateY(-1px)}
.nav nav button:hover::after,.nav nav button.active::after{transform:scaleX(1)}
.search-trigger{transition:transform .28s cubic-bezier(.2,.8,.2,1),box-shadow .28s ease!important}
.search-trigger:hover{transform:translateY(-2px)!important;box-shadow:0 12px 30px rgba(217,45,45,.12)!important}
.search-result-active{transform:translateX(5px)!important;box-shadow:inset 3px 0 0 var(--jyc-red),0 16px 36px rgba(0,0,0,.10)!important}
.search-list>button{transition:transform .28s cubic-bezier(.2,.8,.2,1),box-shadow .28s ease,background .28s ease!important}
.search-list>button:hover{transform:translateX(4px)}
.search-result-active strong{letter-spacing:-.01em}

/* Contact page */
.jyc-contact-page{position:relative;overflow:hidden}
.contact-hero{min-height:430px;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(260px,.75fr);gap:48px;align-items:center;padding:72px clamp(24px,5vw,76px);border:1px solid rgba(215,180,122,.24);border-radius:32px;background:radial-gradient(circle at 80% 30%,rgba(217,45,45,.16),transparent 30%),linear-gradient(135deg,rgba(255,244,215,.05),rgba(217,45,45,.03));box-shadow:0 30px 90px rgba(0,0,0,.12);position:relative}
.contact-hero::before{content:"";position:absolute;inset:12px;border:1px solid rgba(215,180,122,.10);border-radius:24px;pointer-events:none}
.contact-hero h1{font-size:clamp(48px,7vw,92px);line-height:.92;letter-spacing:-.06em;margin:14px 0 24px;max-width:850px}
.contact-hero h1 em{font-family:Georgia,serif;font-weight:500;color:var(--jyc-gold);letter-spacing:-.05em}
.contact-hero p{max-width:680px;font-size:18px;line-height:1.7;color:var(--jyc-soft)}
.contact-hero-orbit{min-height:300px;position:relative;display:grid;place-items:center}
.contact-hero-orbit span,.contact-hero-orbit i{position:absolute;border:1px solid rgba(215,180,122,.22);border-radius:50%;animation:jyc-contact-orbit 10s linear infinite}
.contact-hero-orbit span{width:230px;height:230px}
.contact-hero-orbit i{width:310px;height:310px;border-style:dashed;animation-duration:16s;animation-direction:reverse}
.contact-hero-orbit img{width:min(230px,68%);filter:drop-shadow(0 22px 36px rgba(217,45,45,.28));animation:jyc-contact-float 4.8s ease-in-out infinite;position:relative;z-index:2}
.contact-channel-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin-top:24px}
.contact-channel{position:relative;display:flex;min-height:300px;flex-direction:column;padding:30px;border-radius:26px;text-decoration:none;color:inherit;overflow:hidden;border:1px solid rgba(215,180,122,.20);background:linear-gradient(145deg,rgba(255,244,215,.06),rgba(217,45,45,.025));transition:transform .38s cubic-bezier(.2,.8,.2,1),border-color .38s ease,box-shadow .38s ease}
.contact-channel::before{content:"";position:absolute;width:170px;height:170px;right:-65px;top:-65px;border-radius:50%;background:radial-gradient(circle,rgba(217,45,45,.18),transparent 68%);transition:transform .45s ease}
.contact-channel:hover{transform:translateY(-8px);border-color:rgba(217,45,45,.42);box-shadow:0 26px 60px rgba(0,0,0,.14)}
.contact-channel:hover::before{transform:scale(1.45)}
.contact-channel-number{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;letter-spacing:.16em;color:var(--jyc-gold);margin-bottom:44px}
.contact-channel h2{font-size:clamp(25px,2.5vw,34px);letter-spacing:-.035em;margin:12px 0}
.contact-channel p{line-height:1.65;color:var(--jyc-soft);max-width:34ch}
.contact-channel strong{margin-top:auto;font-size:14px;letter-spacing:.08em;text-transform:uppercase}
.contact-channel-arrow{position:absolute;right:26px;bottom:26px;font-size:26px;transition:transform .32s ease}
.contact-channel:hover .contact-channel-arrow{transform:translate(4px,-4px)}
.contact-note{margin-top:24px;padding:30px 34px;border-radius:26px;border:1px solid rgba(215,180,122,.18);display:flex;justify-content:space-between;align-items:center;gap:24px;background:linear-gradient(90deg,rgba(217,45,45,.07),transparent)}
.contact-note h2{margin:8px 0;font-size:clamp(28px,4vw,44px);letter-spacing:-.04em}
.contact-note p{margin:0;color:var(--jyc-soft);max-width:720px;line-height:1.65}
.mode-switch{display:inline-flex;gap:4px;padding:4px;border-radius:999px;border:1px solid rgba(215,180,122,.18);background:rgba(0,0,0,.08)}
.mode-switch button{border:0;border-radius:999px;padding:10px 16px;background:transparent;color:inherit;cursor:pointer;transition:all .25s ease}
.mode-switch button.active{background:var(--jyc-red);color:#fff;box-shadow:0 8px 20px rgba(217,45,45,.22)}
.jyc-more-grid button{transition:transform .28s cubic-bezier(.2,.8,.2,1),border-color .28s ease,background .28s ease!important}
.jyc-more-grid button:hover{transform:translateY(-3px)!important}
@keyframes jyc-contact-float{0%,100%{transform:translateY(0) rotate(-1deg)}50%{transform:translateY(-12px) rotate(1deg)}}
@keyframes jyc-contact-orbit{to{transform:rotate(360deg)}}
@media (max-width:900px){.contact-hero{grid-template-columns:1fr;min-height:auto;padding:44px 26px}.contact-hero-orbit{min-height:250px}.contact-channel-grid{grid-template-columns:1fr}.contact-channel{min-height:260px}.contact-note{align-items:flex-start;flex-direction:column}}
@media (prefers-reduced-motion:reduce){.contact-hero-orbit span,.contact-hero-orbit i,.contact-hero-orbit img{animation:none}.contact-channel,.nav nav button,.search-list>button{transition:none}}


/* ===== v18.9.9-deep-polish.css ===== */
/* JYC V18.9.9 — deep UI polish
   Pattern language: open-source micro-interaction ideas (React Bits / shadcn-style
   focus, hover, spotlight and motion principles), implemented locally with CSS. */

/* ---------- GLOBAL INTERACTION QUALITY ---------- */
button,a{ -webkit-tap-highlight-color:transparent }
button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{
  outline:2px solid color-mix(in srgb,var(--jyc-gold) 78%,white);
  outline-offset:3px;
}

/* ---------- PHOENIX / BIRD SYSTEM ---------- */
.nav .brand{position:relative;overflow:visible}
.nav .brand::before{
  content:"";position:absolute;inset:7px;border-radius:50%;
  background:radial-gradient(circle,rgba(217,45,45,.16),transparent 68%);
  opacity:0;transform:scale(.72);transition:opacity .35s ease,transform .55s cubic-bezier(.2,.8,.2,1);
  pointer-events:none;
}
.nav .brand::after{
  content:"";position:absolute;width:7px;height:7px;right:4px;top:9px;border-radius:50%;
  background:var(--jyc-gold);box-shadow:0 0 14px rgba(215,180,122,.8);opacity:.7;
  animation:jycBirdBeacon 3.8s ease-in-out infinite;pointer-events:none;
}
.nav .brand:hover::before,.nav .brand:focus-visible::before{opacity:1;transform:scale(1.08)}
.nav .brand .brand-mark img{filter:drop-shadow(0 8px 18px rgba(217,45,45,.22)) drop-shadow(0 0 10px rgba(215,180,122,.06))!important}
.nav .brand:hover .brand-mark img{filter:drop-shadow(0 14px 28px rgba(217,45,45,.38)) drop-shadow(0 0 16px rgba(215,180,122,.16))!important}

.club-hero-art-redesigned::after{
  content:"";position:absolute;left:50%;top:47%;width:min(46vw,560px);height:min(46vw,560px);transform:translate(-50%,-50%);
  border:1px solid rgba(215,180,122,.12);border-radius:50%;
  box-shadow:0 0 0 20px rgba(215,180,122,.018),0 0 0 46px rgba(217,45,45,.014);
  animation:jycBirdRingBreath 7s ease-in-out infinite;pointer-events:none;z-index:0;
}
.hero-bird-main::before{
  content:"";position:absolute;inset:8%;border-radius:50%;
  background:radial-gradient(circle,rgba(217,45,45,.24),rgba(217,45,45,.08) 32%,transparent 68%);
  filter:blur(20px);opacity:.55;z-index:-1;animation:jycBirdAura 4.6s ease-in-out infinite;
}
.hero-bird-main::after{
  content:"";position:absolute;left:17%;right:17%;bottom:8%;height:10%;
  background:radial-gradient(ellipse,rgba(217,45,45,.24),transparent 68%);
  filter:blur(13px);opacity:.5;animation:jycBirdGround 5.8s ease-in-out infinite;z-index:-1;
}
.hero-bird-main img{filter:drop-shadow(0 28px 38px rgba(0,0,0,.34)) drop-shadow(0 0 22px rgba(217,45,45,.28)) drop-shadow(0 0 8px rgba(215,180,122,.08))!important;animation:jycBirdImagePulse 4.6s ease-in-out infinite}
.hero-bird-node{backdrop-filter:blur(18px) saturate(1.08);-webkit-backdrop-filter:blur(18px) saturate(1.08)}
.hero-bird-node::after{
  content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(120deg,transparent 25%,rgba(255,255,255,.08) 48%,transparent 68%);
  transform:translateX(-120%);transition:transform .65s ease;pointer-events:none;
}
.hero-bird-node:hover::after,.hero-bird-node:focus-visible::after{transform:translateX(120%)}

.bird-function-card{isolation:isolate;overflow:hidden!important}
.bird-function-card::before{
  content:"";position:absolute;width:280px;height:280px;right:-120px;top:-120px;border-radius:50%;
  background:radial-gradient(circle,rgba(217,45,45,.16),transparent 66%);opacity:.6;transition:transform .6s cubic-bezier(.2,.8,.2,1),opacity .35s ease;pointer-events:none;
}
.bird-function-card:hover::before{transform:scale(1.45);opacity:.9}
.bird-function-art{filter:drop-shadow(0 16px 26px rgba(217,45,45,.2));transition:transform .55s cubic-bezier(.2,.8,.2,1),filter .4s ease!important}
.bird-function-card:hover .bird-function-art{filter:drop-shadow(0 24px 36px rgba(217,45,45,.32)) drop-shadow(0 0 18px rgba(215,180,122,.10))}
.club-cta-mark{position:relative}
.club-cta-mark::after{content:"";position:absolute;inset:15%;border-radius:50%;background:radial-gradient(circle,rgba(217,45,45,.18),transparent 68%);filter:blur(16px);z-index:-1;animation:jycBirdAura 5s ease-in-out infinite}
.club-cta-mark img{filter:drop-shadow(0 22px 32px rgba(217,45,45,.28)) drop-shadow(0 0 12px rgba(215,180,122,.08));animation:jycBirdImagePulse 5.2s ease-in-out infinite}

/* ---------- CONTACT PAGE ---------- */
.contact-hero{overflow:hidden;isolation:isolate;background:
 radial-gradient(circle at 78% 42%,rgba(217,45,45,.17),transparent 25%),
 radial-gradient(circle at 8% 100%,rgba(215,180,122,.09),transparent 30%),
