.contact-channel{isolation:isolate;background:linear-gradient(145deg,color-mix(in srgb,var(--bg-card) 94%,transparent),color-mix(in srgb,var(--jyc-red) 5%,var(--bg-card)))!important}
.contact-channel::after{content:"";position:absolute;inset:0;border-radius:inherit;background:linear-gradient(120deg,transparent 18%,rgba(255,255,255,.065) 45%,transparent 70%);transform:translateX(-120%);transition:transform .75s ease;pointer-events:none}
.contact-channel:hover::after,.contact-channel:focus-visible::after{transform:translateX(120%)}
.contact-channel:hover{transform:translateY(-9px) scale(1.012)!important;box-shadow:0 30px 70px rgba(0,0,0,.18),0 0 0 1px rgba(215,180,122,.08)}
.contact-creator{position:relative;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:24px;margin-top:24px;padding:28px 30px;border:1px solid rgba(215,180,122,.20);border-radius:28px;background:linear-gradient(110deg,color-mix(in srgb,var(--bg-card) 96%,transparent),color-mix(in srgb,var(--jyc-gold) 4%,var(--bg-card)));overflow:hidden;isolation:isolate}
.contact-creator::before{content:"";position:absolute;width:340px;height:340px;right:-180px;top:-170px;border-radius:50%;background:radial-gradient(circle,rgba(217,45,45,.16),transparent 67%);pointer-events:none}
.contact-creator-avatar{width:82px;height:82px;border-radius:24px;display:grid;place-items:center;position:relative;overflow:hidden;border:1px solid rgba(215,180,122,.28);background:rgba(217,45,45,.06)}
.contact-creator-avatar span{font:900 17px var(--club-display);letter-spacing:.08em;color:var(--jyc-gold);z-index:2}
.contact-creator-avatar img{position:absolute;width:120px;height:120px;object-fit:contain;opacity:.14;transform:rotate(-10deg);filter:drop-shadow(0 0 14px rgba(217,45,45,.5))}
