/* ===== v18.10-best-pass.css ===== */
/* JYC V18.10 — Best-of-previous-releases UI consolidation.
   Preserve signature features, improve hierarchy, interaction and responsive behavior. */

:root{--jyc-max:1440px;--jyc-display:'Space Grotesk',system-ui,sans-serif;--jyc-serif:Georgia,'Times New Roman',serif}
html{scroll-padding-top:100px}
body{overflow-x:hidden}
button,a{ -webkit-tap-highlight-color:transparent }

/* HERO: dramatic, but never allowed to swallow the viewport. */
.jyc-club-editorial-home .club-hero{max-width:var(--jyc-max);margin:0 auto;min-height:clamp(590px,78svh,760px)!important;align-items:center!important}
.jyc-club-editorial-home .club-hero-copy{padding:34px 0 34px 3vw;position:relative;z-index:4}
.jyc-club-editorial-home .club-hero h1{font-size:clamp(62px,7.2vw,112px)!important;max-width:680px!important}
.jyc-club-editorial-home .club-hero-art-redesigned{min-height:560px!important;max-height:700px;overflow:visible}
.jyc-club-editorial-home .hero-bird-main{filter:drop-shadow(0 30px 55px rgba(217,45,45,.28));transition:transform .6s cubic-bezier(.2,.75,.2,1),filter .4s ease}
.jyc-club-editorial-home .club-hero:hover .hero-bird-main{filter:drop-shadow(0 36px 68px rgba(217,45,45,.36))}
.jyc-club-editorial-home .hero-bird-node{backdrop-filter:blur(16px);transition:transform .35s cubic-bezier(.2,.75,.2,1),border-color .25s,box-shadow .35s,background .25s}
.jyc-club-editorial-home .hero-bird-node:hover,.jyc-club-editorial-home .hero-bird-node:focus-visible{transform:translateY(-5px) scale(1.025)!important;border-color:var(--accent-gold)!important;box-shadow:0 18px 44px rgba(0,0,0,.22),0 0 0 1px rgba(215,180,122,.12)}

/* SIGNATURE PHOENIX TRIO = the 3 "boards" / doors. */
.bird-trio-grid{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px!important}
.bird-function-card{min-height:440px!important;border-radius:30px!important;overflow:hidden!important;isolation:isolate;box-shadow:0 20px 70px rgba(0,0,0,.08);transition:transform .45s cubic-bezier(.2,.75,.2,1),border-color .3s,box-shadow .45s!important}
.bird-function-card::after{content:"";position:absolute;inset:auto -25% -42% -25%;height:55%;background:radial-gradient(circle,rgba(217,45,45,.16),transparent 66%);filter:blur(18px);z-index:-1;opacity:.8;transition:transform .5s ease}
.bird-function-card:hover{transform:translateY(-10px)!important;box-shadow:0 28px 80px rgba(0,0,0,.15)!important;border-color:var(--accent-gold)!important}
.bird-function-card:hover::after{transform:translateY(-18px) scale(1.08)}
.bird-function-art{transition:transform .55s cubic-bezier(.2,.75,.2,1),filter .4s ease!important}
