.particle-1{left:8%;top:20%;--px:12px;--py:-22px}.particle-2{left:22%;top:65%;--px:-10px;--py:-12px;animation-delay:.3s}.particle-3{left:32%;top:14%;--px:15px;--py:16px;animation-delay:.7s}.particle-4{left:46%;top:80%;--px:-8px;--py:-20px;animation-delay:1.1s}.particle-5{left:58%;top:11%;--px:13px;--py:-16px;animation-delay:1.4s}.particle-6{left:68%;top:68%;--px:-13px;--py:15px;animation-delay:1.8s}.particle-7{left:80%;top:28%;--px:10px;--py:18px;animation-delay:2.1s}.particle-8{left:90%;top:58%;--px:-15px;--py:-10px;animation-delay:2.5s}.particle-9{left:15%;top:44%;--px:8px;--py:20px;animation-delay:2.9s}.particle-10{left:38%;top:47%;--px:-12px;--py:-18px;animation-delay:3.1s}.particle-11{left:63%;top:42%;--px:16px;--py:10px;animation-delay:3.5s}.particle-12{left:74%;top:82%;--px:-10px;--py:-17px;animation-delay:3.8s}
