.loading-logo span,.loading-logo strong{animation-duration:1.15s!important;animation-delay:.42s!important}
.loadline{animation-duration:1.15s!important;animation-delay:.55s!important}
.loadline i{animation-duration:1.9s!important;animation-delay:.7s!important}
.loading:before{animation-duration:4.8s!important}
.loading:after{animation-duration:4.2s!important;animation-delay:.25s!important}
.loading-flight-a,.loading-flight-b{animation-duration:5.5s!important}
.loading-orbit-a{animation-duration:5.5s!important}
.loading-orbit-b{animation-duration:6.5s!important}
@media (prefers-reduced-motion: reduce){
 .loading-logo img,.loading-logo span,.loading-logo strong,.loadline,.loadline i,.loading:before,.loading:after,.loading-flight-a,.loading-flight-b,.loading-orbit-a,.loading-orbit-b{animation-duration:.01ms!important;animation-iteration-count:1!important}
}


