  }

  to {
    opacity: .72
  }
}

/* ---------- 6. Transparent dark-band (JYC CLUBS) with hairline splits only ---------- */
.dark-band,
.home-layout>.dark-band {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important
}

.dark-band:before {
  display: none !important
}

.dark-band:after {
  display: none !important
}

.dark-band {
  border-top: 1px solid var(--border-tech) !important;
  border-bottom: 1px solid var(--border-tech) !important
}

/* ---------- 7. Transparent empty-state (no translucent card) ---------- */
.activity-empty {
  background: transparent !important;
  box-shadow: none !important
}

/* ---------- 8. Phoenix nodes: keep each button at its spot, never clipped ---------- */
.phoenix-node {
  transform: translateY(-50%) !important;
  margin: 0 !important
}

.phoenix-node:after,
.phoenix-node::after {
  content: none !important
}

.phoenix-node small,
.phoenix-node em {
  display: none !important
}

.phoenix-node span {
