}

.phoenix-node.node-one {
  left: max(10px, 2%) !important;
  right: auto !important;
  top: 30% !important;
  bottom: auto !important
}

.phoenix-node.node-two {
  right: max(10px, 3%) !important;
  left: auto !important;
  top: 30% !important;
  bottom: auto !important
}

.phoenix-node.node-three {
  right: max(10px, 8%) !important;
  left: auto !important;
  top: 75% !important;
  bottom: auto !important
}

.phoenix-node.node-four {
  left: max(10px, 3%) !important;
  right: auto !important;
  top: 75% !important;
  bottom: auto !important
}

