}

.faq-q {
  width: 100% !important;
  display: grid !important;
  grid-template-columns: 46px 1fr auto !important;
  align-items: center !important;
  gap: 16px !important;
  text-align: left !important;
  border: 0 !important;
  background: transparent !important;
  color: var(--text-primary) !important;
