    font-size: 18px !important
  }

  .faq-a {
    padding: 14px 16px 18px !important
  }
}

@keyframes jyc-fade-up {
  from {
    opacity: 0;
    transform: translateY(10px)
  }
  to {
    opacity: 1;
    transform: translateY(0)
  }
}

/* ===== v21-ui-functional.css ===== */
/* JYC V18.17 — focused UI + interaction repair
