@keyframes jyc19-bird-breathe{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-5px) scale(1.012)}}
@keyframes jyc19-orbit-a{from{transform:translate(-50%,-50%) rotate(-10deg) rotate(0deg)}to{transform:translate(-50%,-50%) rotate(-10deg) rotate(360deg)}}
@keyframes jyc19-orbit-b{from{transform:translate(-50%,-50%) rotate(26deg) rotate(0deg)}to{transform:translate(-50%,-50%) rotate(26deg) rotate(-360deg)}}
