/* ===== v18.21-human-jyc.css ===== */
/* JYC V18.21 — human-made consolidation layer.
   Goal: keep the V17 editorial density + V18 functional surface + V20 polish,
   while removing oversized SaaS/demo proportions and balancing the Phoenix system.
*/

:root{
  --jyc21-max:1240px;
  --jyc21-gutter:clamp(16px,2.2vw,28px);
  --jyc21-red:var(--accent-red);
  --jyc21-gold:var(--accent-gold);
}

/* ---------- Public shell ---------- */
.nav-inner{width:min(var(--jyc21-max),calc(100% - (var(--jyc21-gutter)*2)))!important;height:76px!important;padding-right:0!important;gap:16px!important}
.brand{gap:10px!important}.brand img,.brand-mark{width:48px!important;height:48px!important}.brand>span:last-child{font-size:13px!important;letter-spacing:.08em!important}
.nav nav{gap:2px!important}.nav nav button{padding:9px 10px!important;font-size:10px!important;letter-spacing:.1em!important}
.search-trigger{min-height:42px!important;padding:9px 13px!important;font-size:12px!important}
.theme-toggle{position:static!important;width:42px!important;height:42px!important;font-size:16px!important;box-shadow:none!important}

.section.page,.platform-page.section.page,.unified-public-page.section.page{width:min(var(--jyc21-max),calc(100% - (var(--jyc21-gutter)*2)))!important;padding:30px 0 44px!important;min-height:0!important}
.section.page>.back-link,.section.page>.breadcrumbs{margin-bottom:8px!important}
.eyebrow{font-size:8px!important;letter-spacing:.18em!important}
.page h1,.unified-public-page h1,.compact-page-head h1{font-size:clamp(34px,4.2vw,56px)!important;line-height:.98!important;letter-spacing:-.045em!important;margin:8px 0 10px!important}
.section-head{margin-bottom:20px!important}.section-head h2,.reference-section-head h2{font-size:clamp(25px,3.2vw,40px)!important;line-height:1!important;letter-spacing:-.035em!important;margin:8px 0 8px!important}
.section-head p,.reference-section-head p,.compact-page-head p{font-size:13px!important;line-height:1.55!important;max-width:680px!important}
.home .section{padding:34px 0!important}.home .section+.section{margin-top:0!important}

/* ---------- Homepage hero: compact editorial split ---------- */
.home .hero{width:min(var(--jyc21-max),calc(100% - (var(--jyc21-gutter)*2)))!important;min-height:0!important;height:auto!important;padding:30px 0 12px!important;grid-template-columns:minmax(0,1.05fr) minmax(360px,.95fr)!important;gap:14px!important;align-items:center!important}
.home .hero-copy{padding:6px 0!important;max-width:620px!important}
.home .hero h1{font-size:clamp(43px,5vw,70px)!important;line-height:.9!important;letter-spacing:-.065em!important;margin:11px 0 12px!important;max-width:660px!important}
.home .hero-copy>p{font-size:13px!important;line-height:1.55!important;max-width:560px!important}
.home .hero-rule{width:66px!important;height:2px!important;margin:8px 0 10px!important}.home .hero h4{font-size:10px!important;letter-spacing:.18em!important;margin-bottom:12px!important}
.home .hero-actions{margin-top:13px!important}.home .hero-actions .btn{min-height:40px!important;padding:9px 15px!important;font-size:12px!important}
.home .hero-stats{margin-top:10px!important}.home .hero-quick{margin-top:10px!important;max-width:560px!important}.home .hero-quick button{padding:9px 10px!important}
.home .hero-art{height:330px!important;min-height:330px!important;overflow:visible!important}.home .phoenix-3d-stage{height:330px!important;min-height:330px!important}
.home .phoenix-3d-core{width:min(300px,72%)!important;height:270px!important}.home .phoenix-artwork img{width:min(100%,290px)!important;max-height:265px!important}
.home .phoenix-door-rail{width:min(500px,92%)!important;bottom:0!important}.home .phoenix-node{width:102px!important;min-height:54px!important;padding:7px 9px!important;border-radius:12px!important}.home .phoenix-node span{font-size:8px!important}.home .phoenix-node em{font-size:7px!important}
.home .next-event-plaque{max-width:205px!important;padding:8px 10px!important}.home .float-chip,.home .reference-side-note{display:none!important}
.home .hero-context-rail{margin-top:9px!important;font-size:8px!important}

/* ---------- Phoenix: bird stays in the center, orbs feel intentional ---------- */
.home .phoenix-orbital-system{inset:50% auto auto 50%!important;width:290px!important;height:290px!important;transform:translate(-50%,-50%)!important;z-index:1!important}
.home .phoenix-orbit{left:50%!important;top:50%!important;transform:translate(-50%,-50%)!important}
.home .phoenix-orbit-a{width:220px!important;height:220px!important}.home .phoenix-orbit-b{width:275px!important;height:150px!important;transform:translate(-50%,-50%) rotate(22deg)!important}.home .phoenix-orbit-c{width:150px!important;height:275px!important;transform:translate(-50%,-50%) rotate(-22deg)!important}
.home .phoenix-orb{position:absolute!important;width:6px!important;height:6px!important;border-radius:50%!important;background:var(--accent-gold)!important;box-shadow:0 0 12px color-mix(in srgb,var(--accent-gold) 55%,transparent)!important}
.home .phoenix-orb-a{left:14%!important;top:20%!important}.home .phoenix-orb-b{right:10%!important;top:34%!important}.home .phoenix-orb-c{left:28%!important;bottom:10%!important}.home .phoenix-orb-d{right:22%!important;bottom:16%!important;width:4px!important;height:4px!important;background:var(--accent-red)!important}
.home .phoenix-calm-glow{width:220px!important;height:220px!important;opacity:.25!important;filter:blur(18px)!important}
.home .phoenix-halo{inset:11%!important;opacity:.45!important;animation:none!important}

/* ---------- Ecosystem: balanced four-point orbit ---------- */
.home .ecosystem-section{display:block!important}.home .moments-section{display:block!important}
.home .ecosystem-orbit{height:350px!important;max-width:760px!important;margin:8px auto 0!important;position:relative!important;display:grid!important;place-items:center!important}
.home .ecosystem-orbit:before{width:300px!important;height:300px!important;border-color:color-mix(in srgb,var(--accent-red) 18%,transparent)!important;animation:jyc21-spin 34s linear infinite!important}
.home .ecosystem-orbit:after{width:510px!important;height:180px!important;border-color:color-mix(in srgb,var(--accent-gold) 16%,transparent)!important;animation:jyc21-spin 42s linear infinite reverse!important}
.home .ecosystem-core{width:132px!important;height:132px!important;position:relative!important;z-index:4!important;background:radial-gradient(circle,color-mix(in srgb,var(--accent-red) 12%,transparent),transparent 68%)!important}
.home .ecosystem-core:before,.home .ecosystem-core:after{content:"";position:absolute;border:1px solid color-mix(in srgb,var(--accent-gold) 20%,transparent);border-radius:50%;pointer-events:none}
.home .ecosystem-core:before{inset:-14px}.home .ecosystem-core:after{inset:-29px;border-color:color-mix(in srgb,var(--accent-red) 12%,transparent);border-style:dashed;transform:rotate(18deg)}
.home .ecosystem-brand-lockup{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;display:grid!important;place-items:center!important;overflow:visible!important;z-index:5!important}
.home .ecosystem-brand-lockup img{display:block!important;width:94px!important;height:82px!important;max-width:none!important;max-height:none!important;object-fit:contain!important;transform:none!important;position:relative!important;z-index:2!important}
.home .ecosystem-node{width:108px!important;min-height:62px!important;padding:8px 9px!important;border-radius:13px!important;z-index:7!important}
.home .ecosystem-node strong{font-size:10px!important}.home .ecosystem-node em{font-size:7px!important}.home .ecosystem-node small{font-size:8px!important}
.home .ecosystem-node-0{left:7%!important;top:14%!important}.home .ecosystem-node-1{right:7%!important;top:14%!important}.home .ecosystem-node-2{right:7%!important;bottom:10%!important}.home .ecosystem-node-3{left:7%!important;bottom:10%!important}
@keyframes jyc21-spin{to{transform:rotate(360deg)}}

/* ---------- Empty states: useful, not giant ---------- */
.state,.moments-empty,.activity-empty,.map-empty{padding:18px!important;border-radius:14px!important}.state h3,.moments-empty h2{font-size:18px!important;line-height:1.15!important;margin:4px 0 5px!important}.state p,.moments-empty p{font-size:12px!important;line-height:1.5!important;margin:0!important}

/* ---------- Contact ---------- */
.contact-grid{gap:10px!important}.contact-card{padding:18px!important;border-radius:16px!important}.contact-card h3{font-size:17px!important;margin:8px 0 5px!important}.contact-card p{font-size:12px!important;line-height:1.45!important}
.contact-form-container{margin:24px auto 0!important;max-width:760px!important}.contact-form-card{padding:20px!important;border-radius:17px!important}.contact-form-head{margin-bottom:16px!important}.contact-form-head h3{font-size:clamp(26px,3.6vw,36px)!important;line-height:1!important;margin:5px 0 7px!important}.contact-form-head p{font-size:12px!important;line-height:1.5!important}.contact-form{gap:10px!important}.contact-form input{min-height:44px!important}.contact-form textarea{min-height:105px!important}

/* ---------- Campus map: useful map first, no giant empty columns ---------- */
.campus-map-page .compact-page-head{margin-bottom:10px!important}.campus-map-toolbar{margin-bottom:10px!important}.campus-map-summary{padding:10px 12px!important;margin-bottom:10px!important;gap:8px!important}.campus-map-layout{grid-template-columns:minmax(0,1.7fr) minmax(250px,.72fr)!important;gap:10px!important}.campus-map-frame{aspect-ratio:16/8.7!important;border-radius:16px!important;overflow:hidden!important}.campus-map-frame iframe{width:100%!important;height:100%!important;border:0!important}.map-overlay-card{max-width:210px!important;padding:12px!important;border-radius:14px!important}.map-overlay-card strong{font-size:18px!important}.map-overlay-card small{font-size:10px!important}.map-source-chip{font-size:7px!important;padding:6px 8px!important}.campus-map-side{gap:10px!important}.campus-location-highlight{padding:18px!important;border-radius:16px!important}.campus-location-highlight h2{font-size:28px!important;line-height:1!important;margin:7px 0!important}.campus-location-highlight p{font-size:11px!important;line-height:1.5!important}.campus-venue-list{min-height:0!important;max-height:430px!important;overflow:auto!important;padding:15px!important;border-radius:16px!important}.venue-list-head{margin-bottom:8px!important}.campus-utility-grid{margin-top:10px!important}.campus-utility-grid article{padding:16px!important}.platform-note{margin-top:10px!important;font-size:10px!important}
:root[data-theme=dark] .campus-map-frame iframe{filter:brightness(.58) saturate(.58) contrast(1.12) sepia(.08)!important}.map-theme-vignette{background:radial-gradient(circle at 50% 48%,transparent 28%,color-mix(in srgb,var(--bg-main) 18%,transparent) 100%)!important;mix-blend-mode:multiply!important;pointer-events:none!important}.map-source-chip{border:1px solid var(--border-tech)!important;background:color-mix(in srgb,var(--bg-card) 88%,transparent)!important;color:var(--text-muted)!important}

