/* ===== v18.23-human-final.css ===== */

/* JYC V18.23 — HUMAN / COMPACT / MOBILE-FIRST
   Final visual authority layer.
   Goal: a real student-organisation website, not a dashboard, SaaS landing page,
   animation demo, or collection of competing design systems.
*/
:root{
  --jyc23-max:1240px;
  --jyc23-gutter:clamp(14px,2.4vw,30px);
  --jyc23-radius:16px;
  --jyc23-red:var(--accent-red);
  --jyc23-gold:var(--accent-gold);
  --jyc23-line:color-mix(in srgb,var(--border-tech) 90%,transparent);
}

/* ===== Global rhythm ===== */
html{scroll-padding-top:78px}
body{overflow-x:hidden}
.section{width:min(var(--jyc23-max),calc(100% - 2*var(--jyc23-gutter)))!important;padding:42px 0!important}
.section-head,.reference-section-head{margin-bottom:18px!important;max-width:760px!important}
.section-head h2,.reference-section-head h2{
  font-size:clamp(24px,3.2vw,38px)!important;
  line-height:1.02!important;
  letter-spacing:-.045em!important;
  margin:6px 0 8px!important;
}
.section-head p,.reference-section-head p{font-size:13px!important;line-height:1.55!important;max-width:650px!important}
.eyebrow{font-size:8px!important;letter-spacing:.2em!important}
.page h1,.compact-page-head h1,.unified-public-page h1{
  font-size:clamp(30px,4.2vw,50px)!important;
  line-height:.98!important;
  letter-spacing:-.045em!important;
  margin:6px 0 10px!important;
}
.compact-page-head{padding:2px 0 8px!important;margin-bottom:14px!important}
.compact-page-head p{font-size:13px!important;line-height:1.55!important;max-width:660px!important}

/* ===== Navigation: short, centred, recognisable ===== */
.nav{height:72px!important;overflow:visible!important}
.nav-inner{
  width:min(1320px,calc(100% - 2*var(--jyc23-gutter)))!important;
  height:72px!important;
  padding:0 0 0 0!important;
  gap:14px!important;
  min-width:0!important;
  overflow:visible!important;
}
.nav-inner .brand{gap:8px!important;min-width:0!important;max-width:190px!important;overflow:visible!important}
.nav-inner .brand-mark{
  width:38px!important;height:38px!important;min-width:38px!important;min-height:38px!important;
  display:grid!important;place-items:center!important;overflow:hidden!important;
  border:1px solid color-mix(in srgb,var(--accent-gold) 35%,transparent)!important;
  background:color-mix(in srgb,var(--bg-card) 86%,transparent)!important;
  border-radius:50%!important;
}
.nav-inner .brand-mark img{
  width:29px!important;height:29px!important;max-width:29px!important;max-height:29px!important;
  object-fit:contain!important;display:block!important;
  animation:jyc23-mark-breathe 6.5s ease-in-out infinite!important;
}
.nav-inner .brand>span:last-child{
  font:700 10px/1 'Space Grotesk',sans-serif!important;
  letter-spacing:.13em!important;white-space:nowrap!important;
}
.nav-inner>nav{gap:2px!important;margin-left:auto!important}
.nav-inner>nav>button{
  min-height:34px!important;padding:7px 9px!important;
  font-size:9px!important;letter-spacing:.12em!important;
  border-radius:8px!important;
}
.nav-inner>nav>button.active{color:var(--text-primary)!important}
.nav-inner>nav>button.active:after{left:9px!important;right:9px!important;bottom:1px!important;height:1px!important}
.search-trigger{
  min-height:38px!important;height:38px!important;padding:0 13px!important;
  font-size:10px!important;gap:7px!important;display:flex!important;align-items:center!important;
  flex:0 0 auto!important;
}
.search-trigger kbd{display:none!important}
.theme-toggle{
  position:static!important;width:38px!important;height:38px!important;min-width:38px!important;
  box-shadow:none!important;font-size:16px!important;
}
.mobile-theme-float{display:none!important}
@keyframes jyc23-mark-breathe{
  0%,100%{transform:translateY(0) scale(1)}
  50%{transform:translateY(-1px) scale(1.025)}
}

/* ===== Homepage: compact editorial first screen ===== */
.home{width:100%!important;overflow:clip!important}
