  background:color-mix(in srgb,var(--bg-main) 70%,transparent)!important;border-color:var(--jyc23-line)!important;
}
.assistant-results strong{display:block!important;font-size:11px!important}.assistant-results small{display:block!important;font-size:7px!important;margin-top:2px!important;color:var(--accent-red)!important;letter-spacing:.1em!important}
.assistant-results em{display:block!important;font-size:9px!important;line-height:1.3!important;color:var(--text-muted)!important;font-style:normal!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;margin-top:3px!important}
.assistant-index{font-size:8px!important;color:var(--accent-red)!important}.assistant-results>button>b{font-size:12px!important;color:var(--text-muted)!important}
.assistant-empty{padding:18px!important;text-align:center!important;display:grid!important;gap:4px!important}.assistant-empty strong{font-size:12px!important}.assistant-empty span{font-size:10px!important;color:var(--text-muted)!important}
.assistant-foot{display:flex!important;align-items:center!important;gap:9px!important;padding:8px 17px 11px!important;border-top:1px solid var(--jyc23-line)!important;font-size:8px!important;color:var(--text-muted)!important}
.assistant-foot button{margin-left:auto!important;border:0!important;background:transparent!important;color:var(--text-primary)!important;font-size:9px!important}

/* ===== Night sky + constellation layer ===== */
.site-atmosphere{z-index:-1!important;pointer-events:none!important;position:fixed!important;inset:0!important;overflow:hidden!important}
.site-star{opacity:.58!important;background:var(--accent-gold)!important;box-shadow:0 0 7px color-mix(in srgb,var(--accent-gold) 32%,transparent)!important}
:root[data-theme="dark"] .site-star{opacity:.78!important}
:root[data-theme="light"] .site-star{opacity:.13!important;box-shadow:none!important}
.constellation-field{position:absolute;inset:0;opacity:.34;transition:opacity .4s}
.constellation-field svg{position:absolute;width:100%;height:100%;inset:0}
.constellation-field path,.constellation-field polyline{fill:none;stroke:var(--accent-gold);stroke-width:.7;stroke-linecap:round;stroke-linejoin:round;opacity:.4}
.constellation-field circle{fill:var(--accent-gold);opacity:.75}
:root[data-theme="light"] .constellation-field{opacity:.07}
:root[data-theme="light"] .site-atmosphere .shooting-star{opacity:.12!important}
@keyframes jyc23-phoenix-breathe{
  0%,100%{transform:translate3d(0,0,0) scale(1)}
  45%{transform:translate3d(0,-2px,0) scale(1.012)}
  70%{transform:translate3d(1px,0,0) scale(1)}
}
@keyframes jyc23-halo{0%,100%{opacity:.35;transform:scale(.98)}50%{opacity:.55;transform:scale(1.025)}}
@keyframes jyc23-orbit-a{from{transform:translate(-50%,-50%) rotate(-18deg)}to{transform:translate(-50%,-50%) rotate(342deg)}}
@keyframes jyc23-orbit-b{from{transform:translate(-50%,-50%) rotate(24deg)}to{transform:translate(-50%,-50%) rotate(-336deg)}}
@keyframes jyc23-orbit-c{from{transform:translate(-50%,-50%) rotate(0)}to{transform:translate(-50%,-50%) rotate(360deg)}}

/* ===== Shared JYC bird language ===== */
.team-hero-bird img,.team-closeout-bird img,.onboarding-bird img,.admin-tour-bird img,.loading-mark img,.footer-logo-lockup img{
  animation:jyc23-phoenix-breathe 6.2s ease-in-out infinite!important;
  transform-origin:50% 55%!important;
}
.team-hero-bird .team-orbit,.team-hero-bird .team-orbit-a{animation:jyc23-orbit-a 27s linear infinite!important}
.team-hero-bird .team-orbit-b{animation:jyc23-orbit-b 35s linear infinite reverse!important}

/* ===== Light mode: paper, ink, red/gold — no synthetic SaaS gradients ===== */
:root[data-theme="light"] body{
  background:
    radial-gradient(circle at 8% 8%,rgba(168,36,32,.045),transparent 28%),
    radial-gradient(circle at 92% 84%,rgba(191,156,111,.08),transparent 30%),
    var(--bg-main)!important;
}
