  .nav{height:62px!important}.nav-inner{height:62px!important}
  .nav-inner .brand>span:last-child{display:none!important}
  .nav-inner .brand-mark{width:34px!important;height:34px!important;min-width:34px!important;min-height:34px!important}
  .nav-inner .brand-mark img{width:25px!important;height:25px!important}
  .search-trigger{width:38px!important;padding:0!important;justify-content:center!important;border-radius:50%!important}
  .search-trigger .search-label{display:none!important}
  .home .hero{padding-top:18px!important}
  .home .hero h1{font-size:clamp(32px,9.5vw,43px)!important}
  .home .hero-copy>p{font-size:12px!important}
  .home .hero-actions .btn{min-height:38px!important;font-size:10px!important}
