  .home .phoenix-orbit-b{width:205px!important;height:115px!important}
  .home .phoenix-orbit-c{width:170px!important;height:170px!important}
  .home .phoenix-door-rail{grid-template-columns:repeat(3,1fr)!important;gap:4px!important}
  .home .phoenix-node{min-height:36px!important;padding:6px!important}
  .home .phoenix-node em{display:none!important}
