  .home .ecosystem-orbit:after{width:250px!important;height:88px!important}
  .home .ecosystem-core{width:64px!important;height:64px!important}
  .home .ecosystem-brand-lockup img{width:43px!important;height:41px!important}
  .home .ecosystem-node{width:80px!important;min-height:43px!important}
  .home .ecosystem-node strong{font-size:7px!important}.home .ecosystem-node em{display:none!important}
