  .home .ecosystem-node-2{right:0!important;bottom:7%!important}.home .ecosystem-node-3{left:0!important;bottom:7%!important}
  .campus-map-toolbar{align-items:stretch!important}
  .campus-switch{width:100%!important}.campus-switch button{flex:1!important}
  .map-search{width:100%!important;margin-left:0!important}
  .campus-map-frame{height:285px!important}
  .campus-map-summary{grid-template-columns:1fr 1fr!important}
  .assistant-head{padding:14px 14px 8px!important}.assistant-head h2{font-size:21px!important}
  .assistant-search{margin-inline:14px!important}
  .assistant-intent-row{padding-inline:14px!important}
  .assistant-results{max-height:53dvh!important}
  .assistant-foot{padding-inline:14px!important}
  .assistant-foot span{display:none!important}
}

/* Never animate continuously for reduced-motion users. */
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{scroll-behavior:auto!important}
  .nav-inner .brand-mark img,.home .phoenix-artwork img,.home .phoenix-halo,
  .home .phoenix-orbit-a,.home .phoenix-orbit-b,.home .phoenix-orbit-c,
  .home .ecosystem-orbit::before,.home .ecosystem-orbit::after,.home .ecosystem-brand-lockup img,
  .team-hero-bird img,.team-closeout-bird img,.onboarding-bird img,.admin-tour-bird img,.loading-mark img,.footer-logo-lockup img,
  .team-hero-bird .team-orbit,.team-hero-bird .team-orbit-a,.team-hero-bird .team-orbit-b{
    animation:none!important;
  }
}


/* ===== v18.24-jyc-human-final.css ===== */
/* JYC V18.24 — HUMAN COMPACT FINAL
   Visual authority after V18.23. No new design system; this only corrects
   hierarchy, navigation, theme transition, ecosystem interaction, planner,
   account sync, light mode and Control Center ergonomics.
*/
:root{
  --jyc24-max:1240px;
  --jyc24-gutter:clamp(14px,2.2vw,28px);
  --jyc24-line:color-mix(in srgb,var(--border-tech) 92%,transparent);
  --jyc24-paper:#f5f1e6;
  --jyc24-ink:#1a191d;
}

/* ---------- Public shell / typography ---------- */
html{scroll-padding-top:68px}
body{overflow-x:hidden}
.section{width:min(var(--jyc24-max),calc(100% - 2*var(--jyc24-gutter)))!important}
.section.page,.platform-page.section.page,.unified-public-page.section.page{
  padding-top:24px!important;padding-bottom:40px!important;
}
.page .feature-hero,.page .team-hero-panel,.page .club-detail-hero,.page .event-detail-hero,
.page .guide-hero,.page .hero-panel,.page .page-hero,.page .detail-hero{
  min-height:0!important;padding:16px 18px!important;margin-bottom:12px!important;border-radius:13px!important;
}
.page .feature-hero h1,.page .team-hero-panel h1,.page .club-detail-hero h1,.page .event-detail-hero h1,
.page .guide-hero h1,.page .hero-panel h1,.page .page-hero h1,.page .detail-hero h1{
  font-size:clamp(27px,3.1vw,38px)!important;
  line-height:1.02!important;letter-spacing:-.04em!important;margin:5px 0 8px!important;
}
.page h2{font-size:clamp(21px,2.6vw,30px)!important}
.page h3{font-size:clamp(15px,1.8vw,20px)!important}
.page p{font-size:13px!important;line-height:1.55!important}
.page .large-copy{font-size:14px!important;line-height:1.62!important}

/* ---------- Navbar: less empty space, true three-zone layout ---------- */
.nav{height:64px!important}
.nav-inner{
  width:min(1320px,calc(100% - 2*var(--jyc24-gutter)))!important;
  height:64px!important;padding:0!important;gap:10px!important;
  display:flex!important;align-items:center!important;
}
.nav-inner .brand{order:1!important;flex:0 0 auto!important;max-width:180px!important}
.nav-inner>nav{
  order:2!important;flex:1 1 auto!important;justify-content:center!important;
  margin:0!important;gap:1px!important;
}
.nav-inner .theme-toggle{order:3!important}
.nav-inner .search-trigger{order:4!important}
.nav-inner .hamb{order:5!important}
.nav-inner .brand-mark{
  width:36px!important;height:36px!important;min-width:36px!important;min-height:36px!important;
}
.nav-inner .brand-mark img{width:27px!important;height:27px!important;max-width:27px!important;max-height:27px!important}
.nav-inner .brand>span:last-child{font-size:9px!important;letter-spacing:.12em!important}
.nav-inner>nav>button{min-height:32px!important;padding:6px 8px!important;font-size:9px!important}
.search-trigger{min-height:36px!important;height:36px!important}
.theme-toggle{width:36px!important;height:36px!important;min-width:36px!important;font-size:15px!important}
@media (min-width:901px){
  .nav-inner>nav{max-width:720px!important}
}
@media (max-width:1100px) and (min-width:901px){
  .nav-inner .brand>span:last-child{display:none!important}
  .nav-inner>nav>button{padding-inline:6px!important}
}

/* ---------- Homepage Phoenix: contained aura + more orbital depth ---------- */
.home .hero-art{min-height:390px!important;height:390px!important}
.home .phoenix-3d-stage{height:390px!important;min-height:390px!important}
.home .phoenix-3d-core{transform:translateY(-8px)!important}
.home .phoenix-orbital-system{
  inset:5px 0 25px!important;
  transform:translateY(-5px)!important;
}
.home .phoenix-orbit-d{
  display:block!important;
  left:50%!important;top:50%!important;
  width:320px!important;height:105px!important;
  border:1px solid color-mix(in srgb,var(--accent-red) 18%,transparent)!important;
  transform:translate(-50%,-50%) rotate(58deg)!important;
  animation:jyc24-orbit-d 46s linear infinite!important;
}
.home .phoenix-orb-d{display:block!important}
.home .phoenix-orbital-system:after{
  content:"";position:absolute;left:50%;top:50%;width:350px;height:350px;
  border:1px dashed color-mix(in srgb,var(--accent-gold) 8%,transparent);
  border-radius:50%;transform:translate(-50%,-50%);
  animation:jyc24-slow-spin 70s linear infinite reverse;
}
@keyframes jyc24-orbit-d{from{transform:translate(-50%,-50%) rotate(58deg)}to{transform:translate(-50%,-50%) rotate(418deg)}}
@keyframes jyc24-slow-spin{to{transform:translate(-50%,-50%) rotate(360deg)}}
.home .phoenix-door-rail{bottom:4px!important}

/* ---------- Ecosystem: four routes physically connected to the Phoenix ---------- */
.home .ecosystem-orbit{
  height:300px!important;max-width:760px!important;margin:8px auto 0!important;
  overflow:visible!important;
}
.home .ecosystem-orbit:before{
  width:190px!important;height:190px!important;
  border-color:color-mix(in srgb,var(--accent-red) 22%,transparent)!important;
  animation:jyc24-eco-spin 32s linear infinite!important;
}
.home .ecosystem-orbit:after{
  width:350px!important;height:118px!important;
  border-color:color-mix(in srgb,var(--accent-gold) 19%,transparent)!important;
  animation:jyc24-eco-spin 43s linear infinite reverse!important;
}
@keyframes jyc24-eco-spin{to{transform:rotate(360deg)}}
.home .ecosystem-core-wrap{
  position:absolute!important;left:50%!important;top:50%!important;
  transform:translate(-50%,-50%)!important;z-index:8!important;
}
.home .ecosystem-core-action{
  width:92px!important;height:92px!important;padding:0!important;border-radius:50%!important;
  border:1px solid color-mix(in srgb,var(--accent-gold) 34%,transparent)!important;
  background:radial-gradient(circle at 50% 42%,color-mix(in srgb,var(--accent-red) 13%,transparent),color-mix(in srgb,var(--bg-card) 93%,transparent) 68%)!important;
  display:grid!important;place-items:center!important;position:relative!important;
  box-shadow:0 0 0 8px color-mix(in srgb,var(--accent-gold) 3%,transparent),0 0 34px color-mix(in srgb,var(--accent-red) 14%,transparent)!important;
  transition:transform .22s ease,border-color .22s ease,box-shadow .22s ease!important;
}
.home .ecosystem-core-action:hover,.home .ecosystem-core-action:focus-visible{
  transform:scale(1.045)!important;border-color:var(--accent-gold)!important;
  box-shadow:0 0 0 10px color-mix(in srgb,var(--accent-gold) 5%,transparent),0 0 45px color-mix(in srgb,var(--accent-red) 22%,transparent)!important;
}
.home .ecosystem-core-action .ecosystem-brand-lockup{inset:0!important}
.home .ecosystem-core-action img{
  width:60px!important;height:56px!important;object-fit:contain!important;
  animation:jyc23-phoenix-breathe 5.8s ease-in-out infinite!important;
}
.home .ecosystem-core-action>span{
  position:absolute!important;bottom:7px!important;font:700 6px/1 'Space Grotesk',sans-serif!important;
  letter-spacing:.22em!important;color:var(--accent-red)!important;
}
.home .ecosystem-connector{
  position:absolute!important;left:50%!important;top:50%!important;width:39%!important;height:1px!important;
  transform-origin:0 50%!important;opacity:.2!important;
  background:linear-gradient(90deg,var(--accent-gold),transparent)!important;
  transition:opacity .22s ease,filter .22s ease!important;z-index:2!important;
}
.home .ecosystem-connector-0{transform:rotate(210deg)}
.home .ecosystem-connector-1{transform:rotate(330deg)}
.home .ecosystem-connector-2{transform:rotate(30deg)}
.home .ecosystem-connector-3{transform:rotate(150deg)}
.home .ecosystem-active-clubs .ecosystem-connector-0,
.home .ecosystem-active-events .ecosystem-connector-1,
.home .ecosystem-active-my-jyc .ecosystem-connector-2,
.home .ecosystem-active-team .ecosystem-connector-3,
.home .ecosystem-active-core .ecosystem-connector{opacity:.9!important;filter:drop-shadow(0 0 4px color-mix(in srgb,var(--accent-gold) 30%,transparent))!important}
.home .ecosystem-node{
  width:108px!important;min-height:58px!important;padding:8px 9px!important;
  border-radius:12px!important;z-index:9!important;
  transition:transform .22s ease,border-color .22s ease,box-shadow .22s ease,background .22s ease!important;
}
.home .ecosystem-node.is-active,.home .ecosystem-node:hover,.home .ecosystem-node:focus-visible{
  transform:translateY(-2px)!important;border-color:var(--accent-gold)!important;
  box-shadow:0 10px 24px color-mix(in srgb,var(--accent-red) 12%,transparent)!important;
}
.home .ecosystem-node-0{left:5%!important;top:12%!important}
.home .ecosystem-node-1{right:5%!important;top:12%!important}
.home .ecosystem-node-2{right:5%!important;bottom:8%!important}
.home .ecosystem-node-3{left:5%!important;bottom:8%!important}

/* ---------- My JYC sync / agenda ---------- */
.my-jyc-sync-card{
  display:grid!important;grid-template-columns:minmax(0,1fr) minmax(320px,460px)!important;
  gap:16px!important;align-items:center!important;margin:12px 0 14px!important;
  padding:14px 16px!important;border:1px solid var(--jyc24-line)!important;border-radius:13px!important;
  background:color-mix(in srgb,var(--bg-card) 93%,transparent)!important;
}
.my-jyc-sync-card strong{display:block!important;font-size:15px!important;margin:4px 0!important}
.my-jyc-sync-card small{display:block!important;color:var(--text-muted)!important;font-size:10px!important;line-height:1.5!important;max-width:520px!important}
.my-jyc-sync-form{display:grid!important;grid-template-columns:minmax(0,1fr) auto!important;gap:7px!important}
.my-jyc-sync-form input{
  min-width:0!important;height:40px!important;border:1px solid var(--jyc24-line)!important;border-radius:10px!important;
  background:var(--bg-main)!important;color:var(--text-primary)!important;padding:0 11px!important;font-size:11px!important;
}
.my-jyc-sync-form .btn{min-height:40px!important;padding:8px 12px!important;font-size:10px!important}
.my-jyc-sync-card>p{grid-column:1/-1!important;margin:0!important;color:var(--accent-red)!important;font-size:10px!important}
.my-jyc-agenda-item{display:grid!important;grid-template-columns:minmax(0,1fr) auto!important;gap:7px!important;align-items:center!important}
.my-jyc-agenda-item>button:first-child{min-width:0!important}
.my-jyc-calendar-link{border:1px solid var(--jyc24-line)!important;background:transparent!important;color:var(--text-muted)!important;border-radius:8px!important;padding:7px 9px!important;font-size:9px!important}
.my-jyc-calendar-link:hover{color:var(--text-primary)!important;border-color:var(--accent-gold)!important}

/* ---------- Planner: compact planning tool, not a dashboard ---------- */
.calendar-page .feature-hero{background:transparent!important;border:0!important;padding:4px 0 10px!important}
.calendar-page .feature-hero h1{font-size:clamp(27px,3.1vw,38px)!important}
.calendar-page .calendar-mode-tabs{
  display:flex!important;gap:6px!important;flex-wrap:wrap!important;margin:4px 0 9px!important;
  padding:6px!important;border:1px solid var(--jyc24-line)!important;border-radius:13px!important;
  background:color-mix(in srgb,var(--bg-card) 92%,transparent)!important;
}
.calendar-page .calendar-mode-tabs button{
  min-height:34px!important;padding:7px 12px!important;border-radius:9px!important;font-size:10px!important;
}
.calendar-page .calendar-toolbar{
  min-height:58px!important;padding:8px 10px!important;border-radius:13px!important;
  background:color-mix(in srgb,var(--bg-card) 94%,transparent)!important;
}
.calendar-page .calendar-toolbar strong{font-size:15px!important}
.calendar-page .month-grid{gap:5px!important}
.calendar-page .month-grid>b{font-size:8px!important;padding:5px 2px!important}
.calendar-page .month-day{min-height:88px!important;padding:7px!important;border-radius:11px!important}
.calendar-page .month-day>b{font-size:11px!important}
.calendar-page .month-day button{font-size:8px!important;line-height:1.25!important;padding:5px 6px!important}
.calendar-page .calendar-event-list{margin-top:12px!important}
.calendar-page .calendar-event-row{padding:10px 11px!important;border-radius:11px!important}
.calendar-page .calendar-event-row strong{font-size:12px!important}

/* ---------- About absorbs the useful FAQ concept ---------- */
.about-quick-answers{
  margin-top:16px!important;display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:8px!important;
}
.about-quick-answers details{
  border:1px solid var(--jyc24-line)!important;border-radius:11px!important;
