  100%{transform:translate3d(112vw,-1vh,0) rotate(8deg) scale(.58);opacity:0}
}
@keyframes jyc24-flight-trail{
  0%{transform:translateX(0);opacity:0}
  35%{transform:translateX(45vw);opacity:.7}
  100%{transform:translateX(112vw);opacity:0}
}

