/* ===== v18.25-human-jyc-final.css ===== */
/* JYC V18.25 — HUMAN JYC FINAL PASS
   Fixes: compact nav, larger Phoenix ecosystem, orbiting interactive routes,
   stronger JYC paper light theme, smoother theme flight, search ergonomics,
   mobile containment and lower-motion/perf defaults.
*/

/* ---------- Navigation: remove dead air without turning it into a pill bar ---------- */
.nav{height:72px!important;min-height:72px!important}
.nav-inner{height:72px!important;width:min(1440px,calc(100% - 40px))!important;padding:0!important;gap:12px!important}
.nav-inner .brand{min-width:0!important}
.nav-inner .brand-mark{width:40px!important;height:40px!important;min-width:40px!important}
.nav-inner .brand-mark img{width:30px!important;height:30px!important;max-width:none!important;max-height:none!important}
.nav-inner .brand>span:last-child{font-size:10px!important;white-space:nowrap!important}
.nav-inner>nav{gap:2px!important;justify-content:center!important}
.nav-inner>nav>button{min-height:34px!important;padding:7px 9px!important;font-size:9px!important}
.nav-inner .theme-toggle{margin-left:auto!important}
.search-trigger{min-width:158px!important;height:38px!important;padding:7px 13px!important}
.search-trigger .search-label{font-size:10px!important}
.search-trigger kbd{font-size:8px!important}
@media(max-width:1100px) and (min-width:901px){
  .nav-inner{width:calc(100% - 28px)!important}
  .nav-inner>nav{gap:0!important}
  .nav-inner>nav>button{padding-inline:6px!important}
  .search-trigger{min-width:120px!important}
}

/* ---------- Phoenix: recognisable, larger, still restrained ---------- */
.home .hero .phoenix-3d-stage{overflow:visible!important}
.home .phoenix-artwork img{filter:drop-shadow(0 0 10px color-mix(in srgb,var(--accent-red) 26%,transparent))!important}
.home .phoenix-halo{box-shadow:0 0 0 14px color-mix(in srgb,var(--accent-gold) 4%,transparent),0 0 52px color-mix(in srgb,var(--accent-red) 18%,transparent)!important}

/* ---------- Ecosystem: the Phoenix is the centre of an actual orbit ---------- */
.home .ecosystem-orbit{
  height:380px!important;max-width:900px!important;position:relative!important;overflow:visible!important;
  margin:4px auto 0!important;
}
.home .ecosystem-orbit:before{width:220px!important;height:220px!important}
.home .ecosystem-orbit:after{width:470px!important;height:156px!important}
.home .ecosystem-core-wrap{z-index:12!important}
.home .ecosystem-core-action{
  width:150px!important;height:150px!important;
  box-shadow:0 0 0 10px color-mix(in srgb,var(--accent-gold) 5%,transparent),0 0 58px color-mix(in srgb,var(--accent-red) 20%,transparent)!important;
}
.home .ecosystem-core-action img{width:108px!important;height:100px!important;animation:jyc25-phoenix-breathe 5.5s ease-in-out infinite!important}
@keyframes jyc25-phoenix-breathe{0%,100%{transform:scale(.97)}50%{transform:scale(1.035)}}
.home .ecosystem-core-action>span{bottom:10px!important;font-size:7px!important}
.home .ecosystem-orbit-node{
  position:absolute!important;left:50%!important;top:50%!important;width:0!important;height:0!important;
  overflow:visible!important;z-index:15!important;pointer-events:none!important;
  animation:jyc25-orbit-route 30s linear infinite!important;
  transform-origin:0 0!important;
}
.home .ecosystem-orbit-node-0{--route-angle:0deg;--route-radius:210px;--route-y:105px;animation-delay:-1s!important}
.home .ecosystem-orbit-node-1{--route-angle:90deg;--route-radius:210px;--route-y:105px;animation-delay:-8.5s!important}
.home .ecosystem-orbit-node-2{--route-angle:180deg;--route-radius:210px;--route-y:105px;animation-delay:-16s!important}
.home .ecosystem-orbit-node-3{--route-angle:270deg;--route-radius:210px;--route-y:105px;animation-delay:-23.5s!important}
@keyframes jyc25-orbit-route{
  0%{transform:rotate(var(--route-angle)) translateX(var(--route-radius))}
  100%{transform:rotate(calc(var(--route-angle) + 360deg)) translateX(var(--route-radius)) scaleY(.43)}
}
.home .ecosystem-orbit-node .ecosystem-node{
  position:absolute!important;left:0!important;top:0!important;transform:translate(-50%,-50%) scale(1)!important;
  width:132px!important;min-height:68px!important;padding:10px 12px!important;
  pointer-events:auto!important;background:color-mix(in srgb,var(--bg-card) 94%,transparent)!important;
  backdrop-filter:blur(10px)!important;
}
.home .ecosystem-orbit-node .ecosystem-node:hover,
.home .ecosystem-orbit-node .ecosystem-node:focus-visible,
.home .ecosystem-orbit-node .ecosystem-node.is-active{transform:translate(-50%,-50%) scale(1.045)!important}
.home .ecosystem-orbit:has(.ecosystem-node:hover) .ecosystem-orbit-node,
.home .ecosystem-orbit:has(.ecosystem-node:focus-visible) .ecosystem-orbit-node{animation-play-state:paused!important}
.home .ecosystem-orbit-node .ecosystem-node-0,
.home .ecosystem-orbit-node .ecosystem-node-1,
.home .ecosystem-orbit-node .ecosystem-node-2,
.home .ecosystem-orbit-node .ecosystem-node-3{left:0!important;right:auto!important;top:0!important;bottom:auto!important}
.home .ecosystem-connector{width:30%!important;opacity:.28!important}
.home .ecosystem-active-clubs .ecosystem-connector-0,
.home .ecosystem-active-events .ecosystem-connector-1,
.home .ecosystem-active-my-jyc .ecosystem-connector-2,
.home .ecosystem-active-team .ecosystem-connector-3{opacity:1!important}

/* ---------- Theme flight: bird clearly travels left -> right ---------- */
body.theme-flight:after{
  width:112px!important;height:112px!important;left:-140px!important;top:40%!important;
  filter:drop-shadow(0 0 14px color-mix(in srgb,var(--accent-red) 55%,transparent))!important;
