  100%{transform:translate3d(112vw,-2vh,0) rotate(8deg) scale(.58);opacity:0}
}
@keyframes jyc25-flight-trail{
  0%{transform:translateX(0) scaleX(.2);opacity:0}
  30%{opacity:.75}
  100%{transform:translateX(112vw) scaleX(1);opacity:0}
}

