/* ===== v18.26-human-jyc-finish.css ===== */
/* JYC V18.26 — HUMAN FINISH
   Beige-first light mode, native View Transition theme reveal, richer Fest skins,
   Control Center theme presets, and a little less legacy visual noise.
*/

/* ---------- Native theme transition, inspired by open-source View Transition patterns ---------- */
::view-transition-old(root),
::view-transition-new(root){
  animation:none!important;
  mix-blend-mode:normal!important;
}
::view-transition-new(root){z-index:9999!important}
::view-transition-old(root){z-index:1!important}
html{view-transition-name:root}

body.theme-flight:after{
  content:""!important;
  position:fixed!important;
  z-index:10001!important;
  pointer-events:none!important;
  left:-150px!important;
  top:36%!important;
  width:128px!important;
  height:128px!important;
  background:url('/jyc-phoenix-reference-hd.png') center/contain no-repeat!important;
  filter:drop-shadow(0 0 14px color-mix(in srgb,var(--accent-gold) 60%,transparent))!important;
  animation:jyc26-bird-flight 1.08s cubic-bezier(.16,.72,.18,1) forwards!important;
}
body.theme-flight:before{
  content:""!important;
  position:fixed!important;
  z-index:10000!important;
  pointer-events:none!important;
  left:-180px!important;
  top:calc(36% + 62px)!important;
  width:210px!important;
  height:2px!important;
  border-radius:99px!important;
  background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--accent-gold) 80%,transparent),color-mix(in srgb,var(--accent-red) 55%,transparent),transparent)!important;
  filter:blur(.2px)!important;
  animation:jyc26-flight-trail 1.08s cubic-bezier(.2,.8,.2,1) forwards!important;
}
@keyframes jyc26-bird-flight{
  0%{transform:translate3d(0,70px,0) rotate(-13deg) scale(.5);opacity:0}
  10%{opacity:1}
  28%{transform:translate3d(23vw,-7vh,0) rotate(-2deg) scale(.92);opacity:1}
  52%{transform:translate3d(51vw,2vh,0) rotate(4deg) scale(1.02);opacity:1}
  76%{transform:translate3d(78vw,-5vh,0) rotate(1deg) scale(.88);opacity:1}
  100%{transform:translate3d(116vw,-11vh,0) rotate(10deg) scale(.5);opacity:0}
}
@keyframes jyc26-flight-trail{
  0%{transform:translateX(0) scaleX(.15);opacity:0}
  18%{opacity:.8}
  100%{transform:translateX(116vw) scaleX(1);opacity:0}
}

