/* ===== v18.27-jyc-restoration.css ===== */
/* JYC V18.27 — RESTORATION PASS
   Restores the calm V15/V17 composition, fixes the light paper palette,
   removes the awkward orbit-card rotation, and gives theme switching a
   slower, bird-like flight built with local SVG + the native View Transition API.
*/

/* ---------- Theme transition: slow editorial cross-fade + flying Phoenix ---------- */
::view-transition-old(root),
::view-transition-new(root){
  mix-blend-mode:normal!important;
  transform:none!important;
}
::view-transition-old(root){
  animation:jyc27-theme-old 1.55s cubic-bezier(.22,.61,.36,1) both!important;
  z-index:1!important;
}
::view-transition-new(root){
  animation:jyc27-theme-new 1.65s cubic-bezier(.22,.61,.36,1) both!important;
  z-index:2!important;
}

@keyframes jyc27-theme-old{
  from{opacity:1;filter:blur(0)}
  to{opacity:.04;filter:blur(1.2px)}
}
@keyframes jyc27-theme-new{
  from{opacity:.04;filter:blur(1.2px)}
  34%{opacity:.22;filter:blur(.55px)}
  to{opacity:1;filter:blur(0)}
}

/* Disable the old image-pseudo flight from V18.25/26. */
body.theme-flight:before,
body.theme-flight:after{display:none!important;content:none!important}

.jyc-flight-layer{
  position:fixed!important;
  inset:0!important;
  z-index:2147483646!important;
  pointer-events:none!important;
  overflow:hidden!important;
  isolation:isolate!important;
}
.jyc-flight-bird{
  position:absolute!important;
  left:-118px!important;
  top:38vh!important;
  width:104px!important;
  height:74px!important;
  overflow:visible!important;
  transform-origin:50% 50%!important;
  animation:jyc27-bird-cross 1.85s cubic-bezier(.18,.68,.2,1) both!important;
  filter:drop-shadow(0 9px 15px rgba(30,22,18,.18))!important;
}
.jyc-flight-bird svg{width:100%!important;height:100%!important;overflow:visible!important}
.jyc-flight-body{fill:#a82420!important;stroke:#5f1714!important;stroke-width:1.15!important}
.jyc-flight-wing{fill:#c02a24!important;stroke:#681815!important;stroke-width:1.1!important;transform-box:fill-box!important;transform-origin:88% 82%!important}
.jyc-flight-wing-back{fill:#8e1e1a!important;stroke:#58120f!important;stroke-width:1!important;transform-box:fill-box!important;transform-origin:88% 82%!important}
.jyc-flight-tail{fill:#7d1916!important;stroke:#53110f!important;stroke-width:1!important}
.jyc-flight-eye{fill:#fff4dc!important}
.jyc-flight-highlight{fill:#e4a87c!important;opacity:.72!important}
.jyc-flight-wing,.jyc-flight-wing-back{animation:jyc27-wing-flap .22s ease-in-out infinite alternate!important}
.jyc-flight-wing-back{animation-delay:-.08s!important;animation-duration:.27s!important}
.jyc-flight-body-group{animation:jyc27-bird-bob .42s ease-in-out infinite alternate!important;transform-origin:center!important}
