/* ---------- THEME FLIGHT: FULL-VIEWPORT PHOENIX ---------- */
.jyc-flight-layer{position:fixed!important;inset:0!important;width:100vw!important;height:100dvh!important;z-index:2147483647!important;pointer-events:none!important;overflow:hidden!important;isolation:isolate!important;background:rgba(10,8,6,.05)!important}
.jyc-flight-layer:before{content:"";position:absolute;inset:-18%;background:radial-gradient(circle at 50% 50%,color-mix(in srgb,var(--flight-accent) 22%,transparent),transparent 34%),linear-gradient(115deg,transparent 0 22%,color-mix(in srgb,var(--flight-accent2) 9%,transparent) 48%,transparent 78%);filter:blur(4px);animation:jyc19-flight-wash 2.25s cubic-bezier(.2,.7,.2,1) both}
.jyc-flight-layer:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent 0%,color-mix(in srgb,var(--flight-light) 5%,transparent) 50%,transparent 100%);mix-blend-mode:screen;animation:jyc19-flight-sheen 2.25s ease both}
.jyc-flight-bird{position:absolute!important;left:-46vw!important;top:-14vh!important;width:min(56vw,720px)!important;height:auto!important;aspect-ratio:120/84!important;overflow:visible!important;transform-origin:52% 50%!important;animation:jyc19-flight-path 2.25s cubic-bezier(.16,.72,.16,1) both!important;filter:drop-shadow(0 34px 48px rgba(24,16,9,.24))!important}
.jyc-flight-bird svg{width:100%!important;height:100%!important;overflow:visible!important}
.jyc-flight-body{fill:var(--flight-accent)!important;stroke:var(--flight-dark)!important;stroke-width:1.15!important}
.jyc-flight-wing{fill:var(--flight-accent2)!important;stroke:var(--flight-dark)!important;stroke-width:1.1!important;transform-box:fill-box!important;transform-origin:88% 82%!important}
.jyc-flight-wing-back{fill:var(--flight-dark)!important;stroke:var(--flight-dark2)!important;stroke-width:1!important;transform-box:fill-box!important;transform-origin:88% 82%!important}
.jyc-flight-tail{fill:var(--flight-dark)!important;stroke:var(--flight-dark2)!important;stroke-width:1!important}
.jyc-flight-eye{fill:#fff8e8!important}.jyc-flight-highlight{fill:var(--flight-light)!important;opacity:.84!important}
.jyc-flight-wing{animation:jyc19-wing 330ms cubic-bezier(.4,0,.6,1) infinite alternate!important}.jyc-flight-wing-back{animation:jyc19-wing 410ms cubic-bezier(.4,0,.6,1) -120ms infinite alternate!important}
.jyc-flight-body-group{animation:jyc19-body 540ms ease-in-out infinite alternate!important;transform-origin:center!important}.jyc-flight-feather{fill:none!important;stroke:var(--flight-light)!important;stroke-opacity:.7!important;stroke-width:1.1!important;stroke-linecap:round!important}
.jyc-flight-trace{position:absolute!important;left:-30vw!important;top:52vh!important;width:48vw!important;height:9px!important;border-radius:999px!important;background:linear-gradient(90deg,transparent,color-mix(in srgb,var(--flight-accent) 10%,transparent),color-mix(in srgb,var(--flight-accent) 66%,transparent),transparent)!important;filter:blur(3px)!important;animation:jyc19-trace 2.25s cubic-bezier(.16,.72,.16,1) both!important}
.jyc-flight-trace:after{content:"";position:absolute;right:0;top:-20px;width:18vw;height:48px;border-radius:50%;background:color-mix(in srgb,var(--flight-accent2) 17%,transparent);filter:blur(20px)}
.jyc-flight-spark{position:absolute;width:8px;height:8px;border-radius:50%;background:var(--flight-light);box-shadow:0 0 20px var(--flight-accent2);opacity:0;animation:jyc19-spark 1.25s ease-out both}
.spark-a{left:29%;top:51%;animation-delay:.42s}.spark-b{left:52%;top:30%;animation-delay:.74s}.spark-c{left:70%;top:52%;animation-delay:1.02s}
:root[data-theme="dark"]{--flight-accent:#d32e2e;--flight-accent2:#f06a57;--flight-dark:#701512;--flight-dark2:#43100e;--flight-light:#ffe4c7}
:root[data-theme="light"]{--flight-accent:#9b7442;--flight-accent2:#d3ad69;--flight-dark:#6d4f2c;--flight-dark2:#49331f;--flight-light:#fff0be}
@keyframes jyc19-flight-path{0%{transform:translate3d(0,86vh,0) rotate(-17deg) scale(.42);opacity:0}7%{opacity:1}24%{transform:translate3d(17vw,45vh,0) rotate(-9deg) scale(.72)}42%{transform:translate3d(35vw,17vh,0) rotate(-1deg) scale(1.02)}55%{transform:translate3d(51vw,5vh,0) rotate(5deg) scale(1.18)}72%{transform:translate3d(69vw,20vh,0) rotate(10deg) scale(1.02)}88%{transform:translate3d(90vw,48vh,0) rotate(17deg) scale(.72)}100%{transform:translate3d(118vw,82vh,0) rotate(22deg) scale(.40);opacity:0}}
@keyframes jyc19-wing{from{transform:rotate(19deg) translateY(6px) scaleY(.82)}to{transform:rotate(-30deg) translateY(-10px) scaleY(1.08)}}
@keyframes jyc19-body{from{transform:translateY(4px) rotate(-1deg)}to{transform:translateY(-4px) rotate(1deg)}}
@keyframes jyc19-trace{0%{transform:translateX(-10vw) scaleX(.02);opacity:0}14%{opacity:.9}100%{transform:translateX(125vw) scaleX(1.15);opacity:0}}
@keyframes jyc19-flight-wash{0%{opacity:0;transform:scale(.82)}18%{opacity:1}82%{opacity:1}100%{opacity:0;transform:scale(1.08)}}
@keyframes jyc19-flight-sheen{0%,100%{opacity:0;transform:translateX(-30%)}35%,68%{opacity:1}100%{transform:translateX(30%)}}
@keyframes jyc19-spark{0%{transform:scale(.2);opacity:0}25%{opacity:1}100%{transform:translate3d(40px,-34px,0) scale(0);opacity:0}}

/* View Transition foundation based on native View Transition examples. */
::view-transition-group(root){animation-duration:1.15s;animation-timing-function:cubic-bezier(.2,.7,.2,1)}
::view-transition-old(root){animation:jyc19-old 1.15s ease both}
::view-transition-new(root){animation:jyc19-new 1.15s ease both}
@keyframes jyc19-old{to{opacity:.55;filter:saturate(.84) brightness(.94)}}
@keyframes jyc19-new{from{opacity:.25;filter:saturate(.78) brightness(1.05);transform:scale(1.012)}to{opacity:1;filter:none;transform:scale(1)}}

/* ---------- PUBLIC ROUTE / EDITORIAL RHYTHM ---------- */
.route-stage{animation:jyc19-route-in .48s cubic-bezier(.2,.7,.2,1) both}.app>.section,.app>.home{min-width:0}
@keyframes jyc19-route-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.section,.home-layout{content-visibility:auto;contain-intrinsic-size:1px 700px}
:focus-visible{outline:2px solid var(--accent-gold)!important;outline-offset:3px!important}

/* ---------- TODAY ---------- */
.today-at-jyc{padding-top:66px!important;padding-bottom:72px!important}
