gb,var(--bg-card) 92%,transparent)!important}.admin-theme-options{display:flex!important;gap:5px!important}.admin-theme-options button{width:24px!important;height:24px!important;border-radius:50%!important;border:1px solid var(--border-tech)!important}.admin-theme-options button.active{outline:2px solid var(--accent-gold)!important;outline-offset:2px!important}.admin-content{max-width:1400px!important;padding:28px clamp(18px,3vw,44px) 120px!important}.admin-content .content-head{align-items:end!important;border-bottom:1px solid var(--border-tech)!important;padding-bottom:18px!important;margin-bottom:18px!important}.admin-content .content-head h2{font-size:clamp(34px,5vw,64px)!important;letter-spacing:-.06em!important}.admin-welcome-grid{gap:14px!important}.admin-welcome-card,.health-mini,.attention-panel,.quick-actions-panel,.workspace-cards,.admin-health-snapshot,.admin-ai-bar,.admin-ai-panel{border-radius:var(--admin-radius)!important;box-shadow:0 22px 60px rgba(0,0,0,.08)!important}.admin-welcome-card{padding:32px!important;background:linear-gradient(145deg,color-mix(in srgb,var(--bg-card) 95%,var(--accent-gold) 5%),var(--bg-card))!important}.admin-welcome-card h2{font-size:clamp(34px,4.5vw,60px)!important;letter-spacing:-.06em!important}.admin-stats{gap:9px!important}.admin-stats>div{min-height:118px!important;padding:20px!important;border-radius:16px!important;background:color-mix(in srgb,var(--bg-card) 94%,var(--accent-gold) 6%)!important}.admin-stats>div b{font-size:36px!important}.quick-action-grid button,.workspace-cards button{border-radius:15px!important}.admin-mobile-head{z-index:1900!important}.admin-mobile-tabs{z-index:1950!important}

