.not-found-page{min-height:70vh;display:grid;align-content:center;max-width:920px}.not-found-art{display:flex;align-items:end;gap:18px;height:150px;overflow:hidden;margin-bottom:18px}.not-found-art span{font:700 clamp(110px,20vw,190px)/.72 'Space Grotesk';letter-spacing:-.1em;color:color-mix(in srgb,var(--accent-gold) 24%,transparent)}.not-found-art img{width:150px;animation:jyc19-404-float 4s ease-in-out infinite}.not-found-page h1{font:700 clamp(42px,6vw,76px)/.95 'Space Grotesk';letter-spacing:-.06em;margin:10px 0}.not-found-page p{max-width:650px;color:var(--text-muted);font-size:17px;line-height:1.7}.loading-mark img{animation:jyc19-loader-wing 2.6s ease-in-out infinite!important}@keyframes jyc19-404-float{0%,100%{transform:translateY(3px) rotate(-2deg)}50%{transform:translateY(-9px) rotate(2deg)}}@keyframes jyc19-loader-wing{0%,100%{transform:scale(1) rotate(-1deg)}50%{transform:scale(1.035) rotate(1deg)}}

