/* ===== v20-complete.css ===== */
/* JYC V20.0 — production completion layer.
   Local JYC implementation inspired by open-source interaction patterns,
   View Transition API examples, editorial college-fest sites and modern CMS UX.
   This layer is intentionally dependency-free and is loaded last. */

:root{
  --jyc-max:1440px;
  --jyc-gutter:clamp(16px,3vw,48px);
  --jyc-radius:20px;
  --jyc-ease:cubic-bezier(.2,.72,.2,1);
  --jyc-fast:180ms;
  --jyc-mid:360ms;
}

/* ---------- Public design system ---------- */
:root[data-theme="light"]{
  --bg-main:#eee1c8!important;
  --bg-card:#fff9e9!important;
  --text-primary:#2a2117!important;
  --text-muted:#756655!important;
  --accent-red:#a17a45!important;
  --accent-gold:#c29a5a!important;
  --border-tech:rgba(126,91,48,.28)!important;
}
:root[data-theme="light"] body{
  background:
    radial-gradient(circle at 12% 0%,rgba(255,252,237,.98),transparent 30%),
    radial-gradient(circle at 88% 16%,rgba(215,186,127,.24),transparent 28%),
    linear-gradient(180deg,#f5ecd9 0%,#eee1c8 48%,#e5d4b6 100%)!important;
}
:root[data-theme="light"] body:after{
  content:"";position:fixed;inset:0;pointer-events:none;z-index:-1;opacity:.11;
  background-image:radial-gradient(rgba(73,49,25,.48) .5px,transparent .5px);
  background-size:11px 11px;mix-blend-mode:multiply;
}
:root[data-theme="light"] .card,
:root[data-theme="light"] .feature-hero,
:root[data-theme="light"] .compact-page-head,
:root[data-theme="light"] .discover-panel,
:root[data-theme="light"] .contact-form-card,
:root[data-theme="light"] .archive-event,
:root[data-theme="light"] .archive-club,
:root[data-theme="light"] .today-row,
:root[data-theme="light"] .today-empty,
:root[data-theme="light"] .more-sheet,
:root[data-theme="light"] .search-modal{
  background:linear-gradient(145deg,#fffaf0,#fff4df)!important;
  border-color:rgba(126,91,48,.24)!important;
  box-shadow:0 20px 60px rgba(73,49,25,.10)!important;
}
:root[data-theme="light"] .btn:not(.secondary),
:root[data-theme="light"] .gallery-filter button.active,
:root[data-theme="light"] .calendar-mode-tabs button.active,
:root[data-theme="light"] .event-scope-tabs button.active,
:root[data-theme="light"] .mobile-dock button.active{
  background:linear-gradient(135deg,#c19a5b,#a47b44)!important;
  border-color:#a47b44!important;color:#fff9ea!important;
  box-shadow:0 12px 28px rgba(126,91,48,.20)!important;
}
:root[data-theme="light"] .btn.secondary{background:#fff9e9!important;color:#2a2117!important;border-color:#a17a45!important}
:root[data-theme="light"] .eyebrow,
:root[data-theme="light"] .visible-breadcrumbs{color:#8b6538!important}
:root[data-theme="light"] .section-head h2,
:root[data-theme="light"] .page h1,
:root[data-theme="light"] .page h2,
:root[data-theme="light"] .page h3,
:root[data-theme="light"] .hero h1{color:#2a2117!important}
:root[data-theme="light"] .section-head p,
:root[data-theme="light"] .page p,
:root[data-theme="light"] .card p{color:#756655!important}

/* Phoenix becomes a true light-world emblem; red remains reserved for dark-world Phoenix. */
:root[data-theme="light"] .brand-mark img,
:root[data-theme="light"] .phoenix-artwork img,
:root[data-theme="light"] .footer-logo-lockup img,
:root[data-theme="light"] .admin-brand-mark img,
:root[data-theme="light"] .admin-mobile-brand img,
:root[data-theme="light"] .club-detail-hero img,
:root[data-theme="light"] .archive-seal img{
  filter:sepia(1) saturate(.68) hue-rotate(350deg) brightness(1.03) contrast(.90)
    drop-shadow(0 12px 26px rgba(126,91,48,.20))!important;
}

/* ---------- Public page rhythm ---------- */
.unified-public-page,.feature-page,.page{width:min(var(--jyc-max),calc(100% - var(--jyc-gutter)*2))!important;margin-inline:auto!important}
.section-head h2,.reference-section-head h2{letter-spacing:-.045em!important}
.page p,.section p{line-height:1.65}
.btn,.search-trigger,.theme-toggle,.gallery-filter button,.calendar-mode-tabs button,.event-scope-tabs button{transition:transform var(--jyc-fast) var(--jyc-ease),border-color var(--jyc-fast) ease,background var(--jyc-fast) ease,box-shadow var(--jyc-fast) ease!important}
.btn:hover,.search-trigger:hover,.gallery-filter button:hover,.calendar-mode-tabs button:hover,.event-scope-tabs button:hover{transform:translateY(-2px)!important}
.btn:active,.search-trigger:active{transform:translateY(0) scale(.98)!important}

/* ---------- Hero: editorial, not a template demo ---------- */
.home .hero{width:min(var(--jyc-max),calc(100% - var(--jyc-gutter)*2))!important;margin-inline:auto!important}
.home .hero-copy{max-width:700px!important}
.home .hero h1{font-size:clamp(48px,7vw,104px)!important;letter-spacing:-.075em!important}
.home .hero-art{isolation:isolate!important}
.home .hero-art:after{content:"";position:absolute;inset:8% 6%;border:1px solid color-mix(in srgb,var(--accent-gold) 20%,transparent);border-radius:50%;pointer-events:none;opacity:.45}
.home .reference-campus-badge{z-index:10!important}

/* Keep cards upright. Depth comes from light/shadow, not rotation. */
.tilt-card,.club-card-premium,.event-card-premium{transform:none!important;rotate:none!important}
.tilt-card:hover,.club-card-premium:hover,.event-card-premium:hover{transform:translateY(-5px)!important}

/* ---------- Ecosystem ---------- */
.ecosystem-section{position:relative;overflow:hidden!important}
.ecosystem-section .ecosystem-core-action{box-shadow:0 24px 70px color-mix(in srgb,var(--accent-gold) 14%,transparent)!important}
.ecosystem-node{transition:transform .35s var(--jyc-ease),border-color .25s ease,box-shadow .35s ease!important}
.ecosystem-node:hover{transform:translateY(-5px)!important;box-shadow:0 18px 42px color-mix(in srgb,var(--accent-gold) 15%,transparent)!important}

/* ---------- Archive / moments ---------- */
.archive-year-strip{position:sticky;top:76px;z-index:30;backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}
.archive-year-strip a{transition:color .2s ease,transform .2s ease}
.archive-year-strip a:hover{transform:translateY(-2px)}
.gallery-item{overflow:hidden!important}
.gallery-item img{transition:transform .65s var(--jyc-ease),filter .4s ease!important}
.gallery-item:hover img{transform:scale(1.035)!important}

/* ---------- Today ---------- */
.today-at-jyc{position:relative}
.today-head{display:flex;align-items:end;justify-content:space-between;gap:24px}
.today-date{font:700 12px/1 'Space Grotesk',sans-serif;letter-spacing:.12em;text-transform:uppercase;color:var(--accent-gold)}
.today-row{transition:transform .25s var(--jyc-ease),border-color .25s ease!important}
.today-row:hover{transform:translateX(4px)!important;border-color:var(--accent-gold)!important}

/* ---------- Admin Control Room ---------- */
.admin-shell{display:grid!important;grid-template-columns:276px minmax(0,1fr)!important;min-height:100dvh!important}
.admin-side{position:sticky!important;top:0!important;height:100dvh!important;overflow:hidden!important;z-index:1500!important}
.admin-side-scroll{height:calc(100dvh - 174px)!important;overflow:auto!important;overscroll-behavior:contain!important}
.admin-main{min-width:0!important;overflow:visible!important}
.admin-mobile-head{display:none!important}
.admin-top{position:sticky!important;top:0!important;z-index:1600!important;min-height:112px!important;backdrop-filter:blur(22px) saturate(1.1)!important;-webkit-backdrop-filter:blur(22px) saturate(1.1)!important}
.admin-top:after{content:"";position:absolute;inset:auto 0 0;height:1px;background:linear-gradient(90deg,transparent,var(--accent-gold),transparent);opacity:.35;pointer-events:none}
.admin-content{width:min(100%,1480px)!important;margin-inline:auto!important}
.admin-nav-group button{position:relative!important}
.admin-nav-group button.active{transform:none!important}
.admin-nav-group button:hover{transform:translateX(3px)!important}
.admin-content .content-head{position:relative!important}
.admin-welcome-card{position:relative!important;overflow:hidden!important}
.admin-welcome-card:after{content:"";position:absolute;right:-90px;bottom:-110px;width:300px;height:300px;border-radius:50%;border:1px solid color-mix(in srgb,var(--accent-gold) 18%,transparent);box-shadow:0 0 0 35px color-mix(in srgb,var(--accent-gold) 4%,transparent),0 0 0 70px color-mix(in srgb,var(--accent-gold) 2%,transparent);pointer-events:none}
.admin-stats>div{transition:transform .25s var(--jyc-ease),border-color .25s ease!important}
.admin-stats>div:hover{transform:translateY(-3px)!important;border-color:var(--accent-gold)!important}
.admin-command{max-height:min(720px,82dvh)!important;overflow:auto!important}
.admin-mobile-tabs{z-index:1950!important}
.admin-theme-heritage{--bg-main:#eee0c7!important;--bg-card:#fff9e9!important;--text-primary:#2a2117!important;--text-muted:#756655!important;--accent-red:#a17a45!important;--accent-gold:#b68b4e!important;--border-tech:rgba(126,91,48,.25)!important}
.admin-theme-heritage .admin-side{background:#e3d3b6!important}
.admin-theme-heritage .admin-top{background:rgba(245,234,211,.92)!important}

/* ---------- AI Studio ---------- */
.admin-ai-panel{position:relative;overflow:hidden!important}
.admin-ai-panel .error-box{background:color-mix(in srgb,var(--bg-card) 86%,var(--accent-gold) 8%)!important;border-color:color-mix(in srgb,var(--accent-gold) 50%,var(--border-tech))!important;color:var(--text-primary)!important}
.admin-ai-panel .error-box strong,.admin-ai-panel .error-box code{color:var(--text-primary)!important}

/* ---------- Theme flight: the entire viewport participates ---------- */
.jyc-flight-layer{animation:jyc20-flight-scene 2.45s var(--jyc-ease) both!important}
.jyc-flight-layer:before{animation:jyc20-flight-wash 2.45s ease both!important}
.jyc-flight-bird{width:min(52vw,760px)!important;height:auto!important;animation:jyc20-phoenix-arc 2.45s cubic-bezier(.16,.72,.14,1) both!important}
.jyc-flight-wing{animation:jyc20-wing 310ms cubic-bezier(.4,0,.6,1) infinite alternate!important}
.jyc-flight-wing-back{animation:jyc20-wing-back 390ms cubic-bezier(.4,0,.6,1) -120ms infinite alternate!important}
.jyc-flight-body-group{animation:jyc20-body 580ms ease-in-out infinite alternate!important}
.jyc-flight-trace{animation:jyc20-trail 2.45s cubic-bezier(.16,.72,.14,1) both!important}
@keyframes jyc20-flight-scene{0%,100%{opacity:0}9%,86%{opacity:1}}
@keyframes jyc20-flight-wash{0%{opacity:0;transform:scale(.86)}14%,80%{opacity:1}100%{opacity:0;transform:scale(1.08)}}
@keyframes jyc20-phoenix-arc{
  0%{transform:translate3d(-28vw,72vh,0) rotate(-14deg) scale(.34);opacity:0}
  8%{opacity:1}
  22%{transform:translate3d(5vw,42vh,0) rotate(-9deg) scale(.62)}
  39%{transform:translate3d(28vw,17vh,0) rotate(-2deg) scale(.94)}
  52%{transform:translate3d(46vw,5vh,0) rotate(4deg) scale(1.18)}
  67%{transform:translate3d(63vw,13vh,0) rotate(8deg) scale(1.08)}
  82%{transform:translate3d(82vw,39vh,0) rotate(13deg) scale(.72)}
  100%{transform:translate3d(118vw,74vh,0) rotate(20deg) scale(.30);opacity:0}
}
@keyframes jyc20-wing{from{transform:rotate(22deg) translateY(6px) scaleY(.82)}to{transform:rotate(-31deg) translateY(-10px) scaleY(1.08)}}
@keyframes jyc20-wing-back{from{transform:rotate(15deg) translateY(3px) scaleY(.9)}to{transform:rotate(-23deg) translateY(-7px) scaleY(1.03)}}
@keyframes jyc20-body{from{transform:translateY(4px) rotate(-1.2deg)}to{transform:translateY(-4px) rotate(1.2deg)}}
@keyframes jyc20-trail{0%{transform:translateX(-15vw) scaleX(.02);opacity:0}14%{opacity:.82}100%{transform:translateX(125vw) scaleX(1.25);opacity:0}}

/* Native View Transition: let the Phoenix own the spectacle while the UI itself stays calm. */
::view-transition-group(root){animation-duration:1.35s!important;animation-timing-function:cubic-bezier(.2,.72,.2,1)!important}
::view-transition-old(root){animation:jyc20-old-root 1.35s ease both!important}
::view-transition-new(root){animation:jyc20-new-root 1.35s cubic-bezier(.2,.72,.2,1) both!important}
@keyframes jyc20-old-root{0%{opacity:1;transform:scale(1)}45%{opacity:.55;transform:scale(.992)}100%{opacity:0;transform:scale(.985)}}
@keyframes jyc20-new-root{0%{opacity:0;transform:scale(1.015)}55%{opacity:.75}100%{opacity:1;transform:scale(1)}}

/* ---------- Accessibility ---------- */
:focus-visible{outline:2px solid var(--accent-gold)!important;outline-offset:3px!important}
button,a,input,select,textarea{touch-action:manipulation}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
  .jyc-flight-layer{display:none!important}
  .tilt-card:hover,.club-card-premium:hover,.event-card-premium:hover,.today-row:hover{transform:none!important}
}

/* ---------- Mobile ---------- */
@media (max-width:900px){
  .admin-shell{display:block!important}
  .admin-side{display:none!important}
  .admin-main{padding-bottom:106px!important}
  .admin-mobile-head{display:flex!important;position:sticky!important;top:0!important;align-items:center!important;justify-content:space-between!important;min-height:58px!important;padding:10px 12px!important}
  .admin-top{top:58px!important;padding:12px 14px!important;min-height:0!important}
  .admin-top h1{font-size:clamp(30px,8vw,44px)!important;line-height:.98!important}
  .admin-top .admin-actions{display:grid!important;grid-template-columns:1fr 1fr!important}
  .admin-top .admin-theme-control{grid-column:1/-1!important}
  .admin-content{padding:18px 14px 120px!important}
  .archive-year-strip{top:58px}
  .today-head{display:grid;align-items:start}
  .jyc-flight-bird{width:86vw!important}
}
@media (max-width:600px){
  .home .hero{padding-top:22px!important}
  .home .hero h1{font-size:clamp(43px,14vw,72px)!important}
  .home .hero-art{min-height:390px!important;height:390px!important}
  .today-row{grid-template-columns:68px minmax(0,1fr) 18px!important}
  .admin-mobile-tabs{bottom:max(8px,env(safe-area-inset-bottom))!important;left:8px!important;right:8px!important}
  .admin-command{width:min(94vw,620px)!important}
  .jyc-flight-bird{width:118vw!important;left:-110vw!important}
  .jyc-flight-layer:before{background:radial-gradient(circle at 50% 48%,color-mix(in srgb,var(--flight-accent) 22%,transparent),transparent 44%)!important}
}


/* ===== v21-ui-enhancement.css ===== */
/* JYC V21 enhancement layer: preserve V20 motion while removing orbit-ring decoration. */
:root{--v21-paper:#eee5d3;--v21-paper-2:#e5d8bf;--v21-ink:#211d18;--v21-muted:#716758;--v21-gold:#b08a55;--v21-line:rgba(89,70,44,.18);--v21-shadow:0 22px 70px rgba(62,45,26,.13)}
:root[data-theme="light"]{--bg-main:var(--v21-paper)!important;--bg-card:#f5efe3!important;--text-primary:var(--v21-ink)!important;--text-muted:var(--v21-muted)!important;--accent-gold:var(--v21-gold)!important;--accent-red:#8b6b42!important;--border-tech:var(--v21-line)!important}
/* Orbit rings: removed everywhere, while keeping the layout containers and navigation nodes. */
.phoenix-orbit,.phoenix-orbital-system .phoenix-orb,.ecosystem-orbit:before,.ecosystem-orbit:after,.ecosystem-connector,.team-orbit,.state-orbit,.hero-art:after,.orbit,.orbit-ring{display:none!important;animation:none!important}
/* Keep Phoenix itself, its halo and existing V20 motion. */
.home .phoenix-artwork img{filter:sepia(.16) saturate(.72) contrast(1.04) drop-shadow(0 24px 38px rgba(86,61,29,.20))!important}
.home .phoenix-calm-glow,.home .phoenix-halo{background:radial-gradient(circle,rgba(176,138,85,.20),transparent 68%)!important}
.home .phoenix-3d-stage{min-height:540px!important}
/* Compact the hero without flattening it. */
.home .hero{min-height:calc(100vh - 88px)!important;gap:10px!important}
.home .hero-copy{padding:48px 0!important}
.home .hero h1{font-size:clamp(64px,8.2vw,132px)!important;margin-top:25px!important}
.home .hero-art{min-height:530px!important}
@media(max-width:900px){.home .hero{min-height:auto!important}.home .hero-copy{padding:18px 0!important}.home .hero-art{min-height:330px!important}.home .phoenix-3d-stage{min-height:330px!important}}
/* Persistent JYC Bot — separate from Falcon/Phoenix. */
.jyc-bot-launcher{position:fixed;right:24px;bottom:26px;width:58px;height:58px;border:1px solid rgba(176,138,85,.42);border-radius:20px;background:linear-gradient(145deg,#f6eee0,#ded0b8);color:#2a241d;z-index:1800;box-shadow:0 16px 38px rgba(57,42,25,.20),0 0 0 5px rgba(176,138,85,.07);display:grid;place-items:center;padding:0;transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease}
.jyc-bot-launcher:hover{transform:translateY(-4px) scale(1.04);border-color:rgba(176,138,85,.72);box-shadow:0 22px 50px rgba(57,42,25,.25),0 0 0 8px rgba(176,138,85,.08)}
.jyc-bot-face{width:30px;height:24px;border:2px solid #6f5636;border-radius:9px;position:relative;background:#f8f1e5;display:block}
.jyc-bot-face:before{content:"";position:absolute;width:4px;height:4px;border-radius:50%;background:#6f5636;left:7px;top:7px;box-shadow:10px 0 #6f5636}
.jyc-bot-face:after{content:"";position:absolute;width:8px;height:3px;border-bottom:2px solid #6f5636;border-radius:0 0 8px 8px;left:9px;bottom:4px}
.jyc-bot-antenna{position:absolute;left:50%;top:-8px;width:2px;height:8px;background:#6f5636;transform:translateX(-50%)}
.jyc-bot-antenna:after{content:"";position:absolute;width:5px;height:5px;border-radius:50%;background:#b08a55;left:50%;top:-2px;transform:translateX(-50%);box-shadow:0 0 12px rgba(176,138,85,.7)}
.jyc-bot-launcher:before{content:"";position:absolute;inset:-5px;border:1px solid rgba(176,138,85,.18);border-radius:24px;animation:jycBotHalo 3.8s ease-in-out infinite}
.jyc-bot-launcher.is-jump .jyc-bot-face{animation:jycBotJump .72s cubic-bezier(.2,.8,.25,1)}
.jyc-bot-launcher.is-roll .jyc-bot-face{animation:jycBotRoll 1.05s cubic-bezier(.4,0,.2,1)}
.jyc-bot-launcher.is-wave .jyc-bot-face{animation:jycBotWave .95s ease-in-out}
.jyc-bot-launcher.is-bounce .jyc-bot-face{animation:jycBotBounce .85s ease-in-out}
.jyc-bot-launcher.is-jump,.jyc-bot-launcher.is-bounce{animation:jycBotButtonJump .72s cubic-bezier(.2,.8,.25,1)}
@keyframes jycBotHalo{0%,100%{transform:scale(.96);opacity:.35}50%{transform:scale(1.08);opacity:.8}}
@keyframes jycBotJump{0%{transform:translateY(0)}35%{transform:translateY(-12px) rotate(-4deg)}65%{transform:translateY(-4px) rotate(4deg)}100%{transform:translateY(0)}}
@keyframes jycBotButtonJump{0%{transform:translateY(0)}35%{transform:translateY(-7px)}65%{transform:translateY(-2px)}100%{transform:translateY(0)}}
@keyframes jycBotRoll{0%{transform:translateX(0) rotate(0)}45%{transform:translateX(7px) rotate(180deg)}100%{transform:translateX(0) rotate(360deg)}}
@keyframes jycBotWave{0%,100%{transform:rotate(0)}25%{transform:rotate(-12deg) translateY(-3px)}50%{transform:rotate(12deg) translateY(-5px)}75%{transform:rotate(-7deg)}}
@keyframes jycBotBounce{0%,100%{transform:scale(1)}45%{transform:scale(1.13,.9)}70%{transform:scale(.96,1.08)}}
.jyc-bot-label{position:absolute;right:68px;bottom:8px;white-space:nowrap;padding:7px 10px;border:1px solid var(--border-tech);background:rgba(245,239,227,.94);backdrop-filter:blur(12px);border-radius:10px;color:var(--text-primary);font:700 9px/1 'Space Grotesk',sans-serif;letter-spacing:.12em;opacity:0;transform:translateX(6px);pointer-events:none;transition:.25s ease}
.jyc-bot-launcher:hover .jyc-bot-label,.jyc-bot-launcher:focus-visible .jyc-bot-label{opacity:1;transform:none}
/* Assistant inspired by modern floating assistant patterns: compact bottom-right modal, warm paper palette, clear focus. */
.assistant-overlay{position:fixed!important;inset:0!important;background:rgba(35,27,18,.20)!important;backdrop-filter:blur(7px)!important;z-index:1790!important;display:flex!important;align-items:flex-end!important;justify-content:flex-end!important;padding:24px!important}
.assistant-panel-modern{width:min(440px,calc(100vw - 32px))!important;max-height:min(720px,calc(100vh - 48px))!important;background:#f6efe2!important;color:#2a241d!important;border:1px solid rgba(126,95,54,.24)!important;border-radius:24px!important;box-shadow:0 28px 100px rgba(39,28,16,.28)!important;overflow:hidden!important;animation:jycAssistantIn .34s cubic-bezier(.2,.8,.2,1)!important}
.assistant-head{padding:22px 22px 16px!important;border-bottom:1px solid rgba(126,95,54,.15)!important;background:linear-gradient(180deg,#f8f1e5,#f3eadb)!important}
.assistant-head h2{font-family:Georgia,serif!important;color:#282117!important;font-size:27px!important;letter-spacing:-.03em!important;margin:7px 0!important}
.assistant-head p{color:#766a5b!important;line-height:1.55!important}
.assistant-search{margin:15px 18px 10px!important;background:#fffaf1!important;border:1px solid rgba(126,95,54,.20)!important;border-radius:14px!important;color:#594b3a!important}
.assistant-search input{color:#2a241d!important}.assistant-search kbd,.assistant-foot kbd{background:#e8ddca!important;color:#6d5b43!important;border-color:rgba(126,95,54,.16)!important}
.assistant-intent-row{padding:0 18px 8px!important;display:flex!important;gap:7px!important;overflow:auto!important;scrollbar-width:none}
.assistant-intent-row button{border:1px solid rgba(126,95,54,.18)!important;background:#efe4d2!important;color:#665640!important;border-radius:999px!important;padding:7px 10px!important;font-size:10px!important}
.assistant-intent-row button.active,.assistant-intent-row button:hover{background:#d9c5a4!important;color:#2a241d!important;border-color:#b08a55!important}
.assistant-results{padding:4px 18px 14px!important;max-height:370px!important;overflow:auto!important}
.assistant-results button{background:rgba(255,250,241,.72)!important;border-color:rgba(126,95,54,.16)!important;color:#2a241d!important;border-radius:14px!important}
.assistant-results button:hover,.assistant-results button.is-selected{background:#eee1cc!important;border-color:rgba(176,138,85,.55)!important;transform:translateX(-2px)}
.assistant-results small,.assistant-results em{color:#786b5b!important}.assistant-index{color:#9a794c!important}
.assistant-foot{background:#eadfcd!important;color:#776955!important;border-top:1px solid rgba(126,95,54,.12)!important}
@keyframes jycAssistantIn{from{opacity:0;transform:translateY(20px) scale(.97)}to{opacity:1;transform:none}}
/* Club / Events / Team become distinct editorial destinations, not homepage cards. */
.clubs-page,.events-page,.jyc-team-page{padding-top:42px!important}
.clubs-page-head,.events-page-head{padding:34px!important;border:1px solid var(--border-tech)!important;background:linear-gradient(120deg,#f6eee0,#eadfc9)!important;border-radius:26px!important;box-shadow:var(--v21-shadow)!important}
.clubs-page-head h1,.events-page-head h1{font-family:Georgia,serif!important;font-size:clamp(50px,7vw,92px)!important;letter-spacing:-.055em!important;color:#2a241d!important}
.clubs-page-head p,.events-page-head p{max-width:760px!important;font-size:17px!important;color:#766958!important}
.clubs-page .discover-panel{background:#f6efe2!important;border-color:var(--border-tech)!important;border-radius:20px!important}
.clubs-grid-premium{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:20px!important}
.clubs-page .club-card-premium{min-height:330px!important}
.events-page .events-live-strip{border:1px solid rgba(176,138,85,.35)!important;background:#eee1cb!important;color:#3a2e20!important;border-radius:18px!important}
.events-page .event-grid-premium{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:20px!important}
.events-page .event-card-premium .event-poster{height:290px!important}
.team-hero-panel{background:linear-gradient(125deg,#f6eee0,#e4d4b9)!important;border-color:var(--border-tech)!important;box-shadow:var(--v21-shadow)!important}
.team-hero-panel h1{font-family:Georgia,serif!important;color:#2a241d!important}
.team-role-section{padding-top:48px!important}
.team-role-head{border-bottom:1px solid var(--border-tech)!important;padding-bottom:14px!important}
.team-card-editorial{background:#f7f0e5!important;border-color:var(--border-tech)!important}
.team-card-editorial:hover{border-color:#b08a55!important;box-shadow:var(--v21-shadow)!important}
.team-photo-editorial{background:#ded1ba!important}
.team-closeout{background:#e4d5bd!important;border-color:var(--border-tech)!important}
/* Hub directory */
.hub-directory{margin-top:34px;padding:26px;border:1px solid var(--border-tech);border-radius:24px;background:#f5eee1}
.hub-directory-head{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:18px}
.hub-directory-head h2{font-family:Georgia,serif;font-size:clamp(32px,5vw,56px);margin:8px 0;color:#2a241d}
.hub-family-row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.hub-family-row span{border:1px solid var(--border-tech);border-radius:999px;padding:7px 10px;font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#74624b}
