/* ===== v23-final-overhaul.css ===== */
/* V23 FINAL PUBLIC EXPERIENCE OVERHAUL
   - compact editorial layout
   - distinct light/dark identities
   - atmospheric sky restored
   - one Phoenix hero treatment
   - Pinterest-inspired collage gallery
   - filter panels stay closed until requested
   - persistent navigation
   - animated JYC assistant launcher
*/

:root{
  --jyc-paper:#f2e7d4;
  --jyc-paper-2:#fbf5e9;
  --jyc-paper-3:#e7d8be;
  --jyc-ink:#29231d;
  --jyc-muted:#766b5c;
  --jyc-gold:#a47b43;
  --jyc-gold-2:#c7a36a;
  --jyc-line:rgba(126,95,54,.22);
  --jyc-night:#090a0d;
  --jyc-night-2:#111217;
  --jyc-night-3:#19171d;
  --jyc-night-text:#f4ead8;
  --jyc-night-muted:#b4a99b;
  --jyc-night-line:rgba(199,163,106,.22);
}

/* Theme identity: never blend the two palettes. */
html[data-theme="light"] body{
  background:
    radial-gradient(circle at 12% 12%,rgba(199,163,106,.16),transparent 27%),
    radial-gradient(circle at 88% 30%,rgba(164,123,67,.10),transparent 28%),
    var(--jyc-paper)!important;
  color:var(--jyc-ink)!important;
}
html[data-theme="dark"] body{
  background:
    radial-gradient(circle at 12% 10%,rgba(199,163,106,.10),transparent 25%),
    radial-gradient(circle at 88% 32%,rgba(93,72,48,.18),transparent 30%),
    linear-gradient(180deg,#08090c 0%,#0d0e12 55%,#111015 100%)!important;
  color:var(--jyc-night-text)!important;
}

/* Fixed Agentic-style navigation. */
.nav{
  position:fixed!important;top:0;left:0;right:0;height:74px!important;z-index:1800!important;
  background:color-mix(in srgb,var(--bg-main) 86%,transparent)!important;
  border-bottom:1px solid var(--border-tech)!important;
  backdrop-filter:blur(22px) saturate(120%);
}
.nav-inner{height:74px!important;width:min(1440px,calc(100% - 32px))!important;padding:0!important;gap:14px!important}
.public-app{padding-top:74px!important}
.brand{min-width:188px!important;gap:9px!important}
.brand-mark{width:44px!important;height:44px!important;display:grid!important;place-items:center!important;border:1px solid var(--border-tech)!important;border-radius:50%!important;background:color-mix(in srgb,var(--bg-card) 84%,transparent)!important;overflow:hidden!important}
.brand-mark img{width:34px!important;height:34px!important;object-fit:contain!important;filter:none!important}
.brand>span:last-child{font-size:12px!important;letter-spacing:.14em!important}
.nav nav{gap:2px!important}
.nav nav button{padding:10px 13px!important;border-radius:999px!important;font-size:12px!important;letter-spacing:.05em!important}
.nav nav button.active{background:var(--accent-gold)!important;color:#fff8ec!important}
.nav nav button.active:after{display:none!important}
.nav-more-trigger{background:transparent!important}
.theme-toggle{position:relative!important;top:auto!important;right:auto!important;flex:0 0 44px!important;width:44px!important;height:44px!important;box-shadow:none!important}
.search-trigger{min-width:150px!important;height:42px!important;padding:0 15px!important}
.hamb{display:none!important}

/* Restore atmosphere in both themes. */
.site-atmosphere{display:block!important;position:fixed!important;inset:0!important;z-index:0!important;pointer-events:none!important;overflow:hidden!important;opacity:1!important}
.site-star-field{position:absolute!important;inset:0!important;display:block!important}
.site-star{position:absolute!important;left:var(--x);top:var(--y);width:var(--s);height:var(--s);border-radius:50%;background:var(--accent-gold)!important;opacity:.45;animation:jycStarTwinkle var(--d) ease-in-out infinite alternate}
.constellation-field{position:absolute!important;inset:0!important;opacity:.34!important}
.constellation-field svg{width:100%;height:100%}
.constellation-field polyline{fill:none;stroke:var(--accent-gold)!important;stroke-width:1;opacity:.24}
.constellation-field circle{fill:var(--accent-gold)!important;opacity:.6}
.light-dust{position:absolute!important;inset:0!important;background-image:radial-gradient(circle,rgba(199,163,106,.32) 0 1px,transparent 1.5px);background-size:87px 93px;opacity:.12}
.atmosphere-glow{position:absolute!important;border-radius:50%;filter:blur(60px);opacity:.18}
.atmosphere-glow-a{width:30vw;height:30vw;left:-10vw;top:24vh;background:var(--accent-gold)!important}
.atmosphere-glow-b{width:28vw;height:28vw;right:-9vw;top:48vh;background:#7b6447!important}
.shooting-star{display:block!important;position:absolute!important;width:1px;height:100px;background:linear-gradient(180deg,transparent,var(--accent-gold),transparent);opacity:.18;transform:rotate(48deg);animation:jycShoot 8s linear infinite}
.shooting-one{top:10%;left:18%}.shooting-two{top:28%;right:17%;animation-delay:4s}
