html[data-theme="light"] .constellation-field{opacity:.18!important}
html[data-theme="light"] .shooting-star{opacity:.10}
html[data-theme="dark"] .site-star{opacity:.62}
html[data-theme="dark"] .constellation-field{opacity:.40!important}

@keyframes jycStarTwinkle{from{opacity:.25;transform:scale(.85)}to{opacity:.8;transform:scale(1.15)}}
@keyframes jycShoot{0%,72%{transform:translate3d(0,0,0) rotate(48deg);opacity:0}78%{opacity:.35}100%{transform:translate3d(120px,180px,0) rotate(48deg);opacity:0}}

