/* Assistant: animated, small, theme-matched. */
.jyc-bot-launcher{right:20px!important;bottom:20px!important;width:66px!important;height:66px!important;border-radius:22px!important;background:var(--bg-card)!important;border:1px solid var(--border-tech)!important;color:var(--text-primary)!important;box-shadow:0 14px 40px rgba(0,0,0,.16),0 0 0 5px color-mix(in srgb,var(--accent-gold) 10%,transparent)!important;display:grid!important;place-items:center!important;padding:4px!important;overflow:visible!important;z-index:1900!important;animation:none!important}
