.jyc-bot-wave-arm{position:absolute!important;right:-7px!important;top:4px!important;width:7px!important;height:12px!important;border:2px solid var(--accent-gold)!important;border-left:0!important;border-radius:0 8px 8px 0!important;transform-origin:bottom left!important}
.jyc-bot-spark{position:absolute!important;width:5px;height:5px;border-radius:50%;background:var(--accent-gold);right:-1px;top:5px;box-shadow:-34px 47px 0 color-mix(in srgb,var(--accent-gold) 65%,transparent);animation:jycSpark 2.6s ease-in-out infinite}
