.jyc-bot-launcher.is-bounce .jyc-bot-model-wrap,.jyc-bot-launcher.is-bounce .jyc-bot-fallback{animation:jycBotBounce .85s ease-in-out}
.jyc-bot-launcher.is-jump .jyc-bot-model-wrap,.jyc-bot-launcher.is-jump .jyc-bot-fallback{animation:jycBotJump .72s cubic-bezier(.2,.8,.25,1)}
.jyc-bot-launcher:hover{transform:translateY(-3px) scale(1.035)!important}
@keyframes jycBotHalo{0%,100%{opacity:.3;transform:scale(.98)}50%{opacity:.75;transform:scale(1.06)}}
@keyframes jycBotRoll{0%{transform:translateX(0) rotate(0)}45%{transform:translateX(7px) rotate(180deg)}100%{transform:translateX(0) rotate(360deg)}}
@keyframes jycBotBounce{0%,100%{transform:scale(1)}45%{transform:scale(1.12,.9)}70%{transform:scale(.96,1.07)}}
