@keyframes jycBotArmWave{0%,100%{transform:rotate(0)}35%{transform:rotate(28deg)}65%{transform:rotate(-18deg)}85%{transform:rotate(16deg)}}
@keyframes jycSpark{0%,100%{opacity:.2;transform:scale(.8)}50%{opacity:.8;transform:scale(1.25)}}

