/* ===== v25-theme-coherence.css ===== */
/* V25 THEME COHERENCE + PUBLIC READABILITY PASS
   Canonical public visual layer. This file intentionally loads last so legacy
   V13–V24 experiments cannot mix colours, surfaces or typography.
*/
:root{
  --jyc-light-bg:#eee4d1;
  --jyc-light-surface:#f8f1e4;
  --jyc-light-surface-2:#fff9ef;
  --jyc-light-ink:#2b241c;
  --jyc-light-muted:#6f6252;
  --jyc-light-gold:#a47b43;
  --jyc-light-gold-2:#c5a16b;
  --jyc-light-line:rgba(122,88,48,.22);
  --jyc-dark-bg:#090a0d;
  --jyc-dark-surface:#121318;
  --jyc-dark-surface-2:#18191f;
  --jyc-dark-ink:#f4ead8;
  --jyc-dark-muted:#b9ad9d;
  --jyc-dark-gold:#c7a56d;
  --jyc-dark-line:rgba(199,165,109,.23);
  --jyc-font:Inter,'Segoe UI',system-ui,-apple-system,BlinkMacSystemFont,'Helvetica Neue',Arial,sans-serif;
}

/* ---------- Global public typography ---------- */
html[data-theme="light"] .public-app,
html[data-theme="light"] .jyc-footer,
html[data-theme="light"] .public-app button,
html[data-theme="light"] .public-app input,
html[data-theme="light"] .public-app textarea,
html[data-theme="light"] .public-app select{
  color:var(--jyc-light-ink)!important;
  font-family:var(--jyc-font)!important;
}
html[data-theme="dark"] .public-app,
html[data-theme="dark"] .jyc-footer,
html[data-theme="dark"] .public-app button,
html[data-theme="dark"] .public-app input,
html[data-theme="dark"] .public-app textarea,
html[data-theme="dark"] .public-app select{
  color:var(--jyc-dark-ink)!important;
  font-family:var(--jyc-font)!important;
}
html[data-theme="light"] .public-app h1,
html[data-theme="light"] .public-app h2,
html[data-theme="light"] .public-app h3,
html[data-theme="light"] .public-app h4,
html[data-theme="light"] .public-app h5,
html[data-theme="light"] .public-app h6,
html[data-theme="light"] .public-app strong,
html[data-theme="light"] .public-app b,
html[data-theme="light"] .public-app .text-link,
html[data-theme="light"] .public-app a{color:var(--jyc-light-ink)!important}
html[data-theme="dark"] .public-app h1,
html[data-theme="dark"] .public-app h2,
html[data-theme="dark"] .public-app h3,
html[data-theme="dark"] .public-app h4,
html[data-theme="dark"] .public-app h5,
html[data-theme="dark"] .public-app h6,
html[data-theme="dark"] .public-app strong,
html[data-theme="dark"] .public-app b,
html[data-theme="dark"] .public-app .text-link,
html[data-theme="dark"] .public-app a{color:var(--jyc-dark-ink)!important}
html[data-theme="light"] .public-app p,
html[data-theme="light"] .public-app li,
html[data-theme="light"] .public-app small,
html[data-theme="light"] .public-app em,
html[data-theme="light"] .public-app .card-body p,
html[data-theme="light"] .public-app .large-copy,
html[data-theme="light"] .public-app .section-head p,
html[data-theme="light"] .public-app .reference-section-head p,
html[data-theme="light"] .public-app .compact-page-head p,
html[data-theme="light"] .public-app .meta,
html[data-theme="light"] .public-app .state p,
html[data-theme="light"] .public-app .small-copy{color:var(--jyc-light-muted)!important}
html[data-theme="dark"] .public-app p,
html[data-theme="dark"] .public-app li,
html[data-theme="dark"] .public-app small,
html[data-theme="dark"] .public-app em,
html[data-theme="dark"] .public-app .card-body p,
html[data-theme="dark"] .public-app .large-copy,
html[data-theme="dark"] .public-app .section-head p,
html[data-theme="dark"] .public-app .reference-section-head p,
html[data-theme="dark"] .public-app .compact-page-head p,
html[data-theme="dark"] .public-app .meta,
html[data-theme="dark"] .public-app .state p,
html[data-theme="dark"] .public-app .small-copy{color:var(--jyc-dark-muted)!important}

html[data-theme="light"] .public-app .eyebrow,
html[data-theme="light"] .public-app .tag,
html[data-theme="light"] .public-app .live,
html[data-theme="light"] .public-app .live-pill,
html[data-theme="light"] .public-app .live-db,
html[data-theme="light"] .public-app .footer-brand span,
html[data-theme="light"] .public-app .results-line,
html[data-theme="light"] .public-app .visible-breadcrumbs{color:var(--jyc-light-gold)!important}
html[data-theme="dark"] .public-app .eyebrow,
html[data-theme="dark"] .public-app .tag,
html[data-theme="dark"] .public-app .live,
html[data-theme="dark"] .public-app .live-pill,
html[data-theme="dark"] .public-app .live-db,
html[data-theme="dark"] .public-app .footer-brand span,
html[data-theme="dark"] .public-app .results-line,
html[data-theme="dark"] .public-app .visible-breadcrumbs{color:var(--jyc-dark-gold)!important}

/* ---------- Separate light / night identities ---------- */
html[data-theme="light"] body,
html[data-theme="light"] #root,
html[data-theme="light"] .app-frame,
html[data-theme="light"] .public-app{
  background:
    radial-gradient(circle at 17% 22%,rgba(205,171,115,.15),transparent 28%),
    radial-gradient(circle at 84% 28%,rgba(214,169,147,.08),transparent 25%),
    linear-gradient(180deg,#f3eadb 0%,#eee4d1 52%,#e8dcc6 100%)!important;
  color:var(--jyc-light-ink)!important;
}
html[data-theme="dark"] body,
html[data-theme="dark"] #root,
html[data-theme="dark"] .app-frame,
html[data-theme="dark"] .public-app{
  background:
    radial-gradient(circle at 18% 18%,rgba(177,135,82,.11),transparent 28%),
    radial-gradient(circle at 82% 24%,rgba(94,68,49,.12),transparent 25%),
    linear-gradient(180deg,#07080a 0%,#0b0d10 52%,#121015 100%)!important;
  color:var(--jyc-dark-ink)!important;
}

/* Atmosphere is gold in both modes; no old red/pink wash. */
html[data-theme="light"] .site-atmosphere{opacity:.48!important}
html[data-theme="dark"] .site-atmosphere{opacity:1!important}
.atmosphere-glow-a{background:radial-gradient(circle,rgba(196,155,93,.18),transparent 68%)!important}
.atmosphere-glow-b{background:radial-gradient(circle,rgba(150,117,82,.13),transparent 68%)!important}
html[data-theme="light"] .site-star{background:#b08a50!important;box-shadow:0 0 5px rgba(176,138,80,.28)!important}
html[data-theme="dark"] .site-star{background:#c8a56c!important;box-shadow:0 0 7px rgba(200,165,108,.35)!important}
