html[data-theme="light"] .constellation-field circle{fill:#a47b43!important}
html[data-theme="dark"] .constellation-field polyline{stroke:rgba(199,165,109,.28)!important}
html[data-theme="dark"] .constellation-field circle{fill:#c7a56d!important}

/* ---------- Persistent navigation ---------- */
.nav{height:70px!important;position:fixed!important;top:0!important;left:0!important;right:0!important;z-index:5000!important;backdrop-filter:blur(18px)!important}
.nav-inner{height:70px!important;width:min(1420px,calc(100% - 36px))!important;margin:0 auto!important;display:flex!important;align-items:center!important;gap:12px!important}
html[data-theme="light"] .nav{background:rgba(248,241,228,.92)!important;border-bottom:1px solid var(--jyc-light-line)!important;box-shadow:0 8px 30px rgba(78,55,31,.08)!important}
html[data-theme="dark"] .nav{background:rgba(8,9,11,.90)!important;border-bottom:1px solid var(--jyc-dark-line)!important;box-shadow:0 8px 30px rgba(0,0,0,.28)!important}
.brand{min-width:130px!important;height:48px!important;gap:9px!important}
.brand-mark{width:42px!important;height:42px!important;border-radius:50%!important;overflow:hidden!important;display:grid!important;place-items:center!important;border:1px solid transparent!important}
html[data-theme="light"] .brand-mark{background:#fff8ea!important;border-color:var(--jyc-light-line)!important}
html[data-theme="dark"] .brand-mark{background:#111318!important;border-color:var(--jyc-dark-line)!important}
.brand-mark img{width:38px!important;height:38px!important;object-fit:contain!important;mix-blend-mode:normal!important;filter:none!important}
.brand>span:last-child{font:800 9px/1 var(--jyc-font)!important;letter-spacing:.15em!important;white-space:nowrap!important}
html[data-theme="light"] .brand>span:last-child{color:var(--jyc-light-ink)!important}
html[data-theme="dark"] .brand>span:last-child{color:var(--jyc-dark-ink)!important}
.nav nav{display:flex!important;align-items:center!important;justify-content:center!important;gap:2px!important;flex:1!important}
.nav nav button{height:38px!important;padding:0 12px!important;border:0!important;border-radius:999px!important;background:transparent!important;font:750 11px/1 var(--jyc-font)!important;letter-spacing:.05em!important;white-space:nowrap!important}
html[data-theme="light"] .nav nav button{color:#675945!important}
html[data-theme="dark"] .nav nav button{color:#c4b6a4!important}
html[data-theme="light"] .nav nav button.active{background:#a47b43!important;color:#fff8ed!important}
