.nav .theme-toggle{position:static!important;display:flex!important;order:3!important;flex:0 0 auto!important;width:auto!important;min-width:46px!important;height:40px!important;padding:0 11px!important;border-radius:999px!important;align-items:center!important;justify-content:center!important;gap:6px!important;box-shadow:none!important;margin:0!important}
html[data-theme="light"] .nav .theme-toggle{background:#fff9ee!important;color:#76572e!important;border:1px solid var(--jyc-light-line)!important}
html[data-theme="dark"] .nav .theme-toggle{background:#15161b!important;color:#e4c28e!important;border:1px solid var(--jyc-dark-line)!important}
.theme-icon{font-size:15px!important;line-height:1!important}
.theme-label{font:800 8px/1 var(--jyc-font)!important;letter-spacing:.08em!important}
.search-trigger{order:4!important;width:148px!important;min-width:148px!important;height:40px!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:8px!important;border-radius:999px!important;font:700 10px/1 var(--jyc-font)!important;letter-spacing:.04em!important;padding:0 14px!important}
html[data-theme="light"] .search-trigger{background:#fff9ee!important;color:#594a38!important;border:1px solid var(--jyc-light-line)!important;box-shadow:0 6px 20px rgba(78,55,31,.06)!important}
html[data-theme="dark"] .search-trigger{background:#15161b!important;color:#eee3d2!important;border:1px solid var(--jyc-dark-line)!important}
html[data-theme="light"] .search-trigger svg{stroke:#8b673a!important}
html[data-theme="dark"] .search-trigger svg{stroke:#c8a773!important}
