@keyframes jycBotRoll{0%{transform:rotate(0) translateY(0)}35%{transform:rotate(-18deg) translateY(-3px)}70%{transform:rotate(18deg) translateY(-2px)}100%{transform:rotate(0) translateY(0)}}
@keyframes jycBotWave{0%,100%{transform:rotate(0)}25%{transform:rotate(-7deg) translateY(-2px)}50%{transform:rotate(7deg) translateY(-4px)}75%{transform:rotate(-5deg) translateY(-2px)}}
@keyframes jycBotBounce{0%,100%{transform:translateY(0) scale(1)}35%{transform:translateY(-10px) scale(1.02)}65%{transform:translateY(2px) scale(.98)}}
@keyframes jycBotJump{0%,100%{transform:translateY(0) scale(1)}45%{transform:translateY(-18px) scale(1.03)}70%{transform:translateY(1px) scale(.99)}}

