.club-identity-card[data-hub="vamunique"] .club-card-visual{background-image:radial-gradient(ellipse at 70% 30%,var(--hub-accent-soft),transparent 58%),repeating-radial-gradient(ellipse at center,transparent 0 18px,var(--hub-accent-line) 19px 20px)!important;}
.club-identity-card[data-hub="panache"] .club-card-visual{background-image:linear-gradient(125deg,transparent 0 46%,var(--hub-accent-line) 47% 48%,transparent 49%),linear-gradient(55deg,var(--hub-accent-soft),transparent 70%)!important;}
.club-identity-card[data-hub="rph"] .club-card-visual,.club-identity-card[data-hub="zencoders"] .club-card-visual,.club-identity-card[data-hub="jodc"] .club-card-visual{background-image:linear-gradient(90deg,var(--hub-accent-soft) 1px,transparent 1px),linear-gradient(var(--hub-accent-soft) 1px,transparent 1px)!important;background-size:18px 18px!important;}
.club-identity-card[data-hub="cicr"] .club-card-visual,.club-identity-card[data-hub="dronotics"] .club-card-visual{background-image:radial-gradient(circle,var(--hub-accent-line) 0 1px,transparent 2px),linear-gradient(135deg,var(--hub-accent-soft),transparent 70%)!important;background-size:18px 18px,auto!important;}
.club-identity-card[data-hub="innovation"] .club-card-visual{background-image:linear-gradient(45deg,transparent 46%,var(--hub-accent-line) 47% 48%,transparent 49%),linear-gradient(-45deg,transparent 46%,var(--hub-accent-soft) 47% 48%,transparent 49%)!important;background-size:28px 28px!important;}
.club-identity-card[data-hub="cypherx"] .club-card-visual{background-image:linear-gradient(90deg,transparent 49%,var(--hub-accent-line) 50%,transparent 51%),linear-gradient(transparent 49%,var(--hub-accent-soft) 50%,transparent 51%)!important;background-size:24px 24px!important;}
.club-identity-card[data-hub="arcadia"] .club-card-visual{background-image:radial-gradient(circle at 25% 25%,var(--hub-accent-line) 0 2px,transparent 3px),radial-gradient(circle at 75% 70%,var(--hub-accent-soft) 0 20%,transparent 21%)!important;}
.club-identity-card[data-hub="neural-nexus"] .club-card-visual{background-image:radial-gradient(circle at center,var(--hub-accent-line) 0 1px,transparent 2px),linear-gradient(30deg,transparent 48%,var(--hub-accent-soft) 49% 51%,transparent 52%)!important;background-size:20px 20px,36px 36px!important;}
.club-identity-card[data-hub="gdg"] .club-card-visual{background-image:radial-gradient(circle,var(--hub-accent-soft) 0 3px,transparent 4px)!important;background-size:28px 28px!important;}
