/* ---------- 4. Agentic AI band: theme-aware gradient ---------- */
html[data-theme="light"] .app-frame .route-stage .agentic-home-inner{background:linear-gradient(120deg,#f8f0e1,#ecdcbe)!important;border-color:rgba(122,88,48,.26)!important;color:var(--jyc-light-ink)!important}
