/* ===== v23.7-falcon-3d.css ===== */
/* Falcon 3D hero layer. Sits at z-index 0 inside .home .hero, so it renders
   beneath the existing hero art (z-index 1) and beneath the hero copy
   (z-index 20). The scrim re-injects the page background behind the centred
   copy in both themes, which is what keeps headline contrast intact. */
.home .falcon-3d-layer{
  position:absolute!important;inset:0!important;z-index:0!important;
  display:block!important;pointer-events:none!important;overflow:hidden!important;
  contain:layout paint!important;opacity:0!important;
  transition:opacity .9s var(--ease)!important
}
.home .falcon-3d-layer.is-ready{opacity:1!important}
.home .falcon-3d-stage{position:absolute!important;inset:0!important;display:block!important;pointer-events:none!important}
.home .falcon-3d-canvas{
  position:absolute!important;inset:0!important;width:100%!important;height:100%!important;
  display:block!important;opacity:.92!important;
  -webkit-mask-image:radial-gradient(86% 76% at 52% 46%,#000 0%,#000 58%,rgba(0,0,0,.5) 78%,transparent 96%)!important;
  mask-image:radial-gradient(86% 76% at 52% 46%,#000 0%,#000 58%,rgba(0,0,0,.5) 78%,transparent 96%)!important
}
.home .falcon-3d-scrim{
  position:absolute!important;inset:0!important;z-index:1!important;display:block!important;pointer-events:none!important;
  background:
    radial-gradient(58% 50% at 50% 48%,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 90%,transparent) 0%,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 62%,transparent) 52%,transparent 78%),
    linear-gradient(to bottom,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 34%,transparent) 0%,transparent 34%,transparent 66%,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 40%,transparent) 100%)!important
}
html[data-theme="dark"] .home .falcon-3d-canvas{opacity:1!important}
html[data-theme="dark"] .home .falcon-3d-scrim{
  background:
    radial-gradient(58% 50% at 50% 48%,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 88%,transparent) 0%,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 60%,transparent) 52%,transparent 78%),
    linear-gradient(to bottom,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 32%,transparent) 0%,transparent 34%,transparent 66%,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 38%,transparent) 100%)!important
}
html[data-performance="lite"] .home .falcon-3d-layer{display:none!important}
@media(max-width:1100px){
  .home .falcon-3d-canvas{
    opacity:.8!important;
    -webkit-mask-image:radial-gradient(92% 66% at 52% 42%,#000 0%,#000 52%,rgba(0,0,0,.45) 76%,transparent 95%)!important;
    mask-image:radial-gradient(92% 66% at 52% 42%,#000 0%,#000 52%,rgba(0,0,0,.45) 76%,transparent 95%)!important
  }
  html[data-theme="dark"] .home .falcon-3d-canvas{opacity:.88!important}
}
@media(max-width:760px){
  .home .falcon-3d-canvas{
    opacity:.62!important;
    -webkit-mask-image:radial-gradient(96% 50% at 52% 36%,#000 0%,#000 46%,transparent 90%)!important;
    mask-image:radial-gradient(96% 50% at 52% 36%,#000 0%,#000 46%,transparent 90%)!important
  }
  .home .falcon-3d-scrim{
    background:
      radial-gradient(78% 34% at 50% 40%,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 88%,transparent) 0%,transparent 76%),
      linear-gradient(to bottom,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 30%,transparent) 0%,transparent 30%,transparent 72%,color-mix(in srgb,var(--jyc-light-bg,#eee4d1) 42%,transparent) 100%)!important
  }
  html[data-theme="dark"] .home .falcon-3d-canvas{opacity:.7!important}
  html[data-theme="dark"] .home .falcon-3d-scrim{
    background:
      radial-gradient(78% 34% at 50% 40%,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 86%,transparent) 0%,transparent 76%),
      linear-gradient(to bottom,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 28%,transparent) 0%,transparent 30%,transparent 72%,color-mix(in srgb,var(--jyc-dark-bg,#090a0d) 40%,transparent) 100%)!important
  }
}
@media(prefers-reduced-motion:reduce){
  .home .falcon-3d-layer{display:none!important}
}

/* ===== v23.7-moments-mosaic.css ===== */
/* The moments grid had three competing placement layers (v14 .moment-0/.moment-3
   class spans, v24 !important nth-child spans, and a 4 column track definition),
   so auto-placement backtracked and left ragged holes. This resets placement to
   a known baseline and then lays the 12 tiles out on an explicit editorial
   mosaic. Explicit grid-area rather than fixed grid-template-rows means the
   grid simply gets shorter if JYC publishes fewer than 12 photos, instead of
   reserving empty rows. */
.app-frame .route-stage .moments-editorial .moment-tile{
  grid-area:auto!important;grid-column:auto!important;grid-row:auto!important
}
.app-frame .route-stage .moments-editorial{
  grid-template-columns:repeat(4,minmax(0,1fr))!important;
  grid-auto-rows:clamp(104px,8.4vw,124px)!important;
  grid-auto-flow:row dense!important;
  gap:9px!important
}
.app-frame .route-stage .moments-editorial .moment-tile:nth-child(1){grid-area:1/1/3/3!important}
.app-frame .route-stage .moments-editorial .moment-tile:nth-child(2){grid-area:1/3/3/4!important}
.app-frame .route-stage .moments-editorial .moment-tile:nth-child(3){grid-area:1/4/3/5!important}
.app-frame .route-stage .moments-editorial .moment-tile:nth-child(4){grid-area:3/1/4/3!important}
